var e=(e,t,n)=>({t:`info`,text:e,tip:t,fx:n}),t=[`SUED`,`OST`,`NORD`,`WEST`],n={NORD:`GESELLIG_TANJA`,WEST:`ERFAHREN_HANS`,OST:`VORSICHTIG_PETRA`},r=[{id:`EICHEL`,label:`Eichel`,suit:`EICHEL`},{id:`SCHELLE`,label:`Schelle`,suit:`SCHELLE`},{id:`ROSE`,label:`Rose`,suit:`ROSE`},{id:`SCHILTE`,label:`Schilte`,suit:`SCHILTE`},{id:`OBENABE`,label:`Obenabe`},{id:`UNDENUFE`,label:`Undenufe`}],i=(e,t)=>({id:e,code:e,label:t}),a=[{lesson:`Schieben und Buur`,ziele:[`Trumpf wählen oder schieben`,`Schmieren: Punkte zum Partner`,`Den Buur erkennen`,`Abwerfen, wenn nichts sticht`],zielAt:[1,5,6,14],einstieg:`Setz dich, wir spielen eine Runde. Du schaust mir einfach beim Denken zu.`,regionId:`BE`,kind:`trick`,title:`Schieber`,order:t,firstLeader:`NORD`,score:`teams`,hands:{SUED:`EA E6 LA L8 L6 R10 R8 R7 R6`,NORD:`EU E9 SA SK S9 S8 L7 R9 RO`,WEST:`EK E8 SO SU S10 S7 S6 L9 L10`,OST:`EO E7 E10 LK LO LU RA RK RU`},steps:[e(`Nu, setz dich. Schieber ist der Jass, den hier oben jeder kann: Du spielst mit {NORD} gegen {OST} und {WEST}. Jeder hat neun Karten, und weil du alle siehst, kannst du mir beim Denken zuschauen. Wer einen Stich holt, spielt als Nächster aus.`,`Gespielt wird gegen den Uhrzeigersinn: Du, dann {OST}, {NORD}, {WEST}.`),{t:`choose`,text:`Du bist Vorhand und müsstest den Trumpf ansagen – oder schieben. Schau deine Karten an: ein paar Asse, aber keine Farbe, die trägt. {NORD} dagegen hält in der Eichel den Under und den Nell. Was tust du?`,tip:`Schieben: Hast du keine starke Farbe, überlässt du die Ansage dem Partner. Er muss dann ansagen.`,options:[...r,{id:`SCHIEBEN`,label:`Schieben`}],answer:`SCHIEBEN`,wrong:{EICHEL:`In der Eichel hast du nur das Ass und die Sechs. Den Under und den Nell hat {NORD} – schieb zu ihm.`,SCHELLE:`Du hast gar keine Schellen. Was willst du damit stechen? Schieb zu {NORD}.`,ROSE:`Deine Rosen sind klein: Zehn, Acht, Sieben, Sechs. Das trägt nicht als Trumpf – schieb.`,SCHILTE:`Mit Ass, Acht und Sechs ist Schilte kein Trumpf. Schieb zu {NORD}.`,OBENABE:`Für Obenabe fehlen dir genug Asse und Könige. Schieb lieber zu {NORD}.`,UNDENUFE:`Für Undenufe fehlen dir die Sechser. Schieb lieber zu {NORD}.`},fx:{bubbles:{SUED:`Schieben!`}}},e(`{NORD} sagt Eichel an: Er hat den Eichel-Under, den Buur, und den Nell. Hmpf, das war ein guter Schieber von dir. Trumpf ist die stärkste Farbe im Spiel und sticht jede andere. Die Rangfolge im Trumpf: Under, Nell, Ass, König, Ober, Zehn, Acht, Sieben, Sechs.`,`Der Under (Buur) schlägt alles, der Nell (die Neun) ist die Nummer zwei.`,{trump:`EICHEL`,bubbles:{NORD:`Eichel!`}}),{t:`play`,seat:`NORD`,code:`EU`,text:`{NORD} spielt den Buur aus, den Trumpf-Under. Das ist die höchste Karte im ganzen Spiel. Er holt damit die gegnerischen Trümpfe aus den Händen.`,fx:{bubbles:{}}},{t:`play`,seat:`WEST`,code:`EK`,text:`{WEST} muss Eichel bedienen und gibt den König zu. Wer die Farbe hat, muss sie zugeben.`},{t:`play`,seat:`SUED`,code:`EA`,text:`Eichel ist Trumpf und wurde ausgespielt: Du musst Eichel bedienen. Der Buur von {NORD} gewinnt den Stich sicher. Leg also dein Ass dazu. Das nennt man Schmieren: Du schenkst deinem Team 11 Punkte.`,tip:`Schmieren: Gewinnt dein Partner den Stich sicher, leg die Karte mit den meisten Punkten dazu.`,wrong:{E6:`Das ist erlaubt, aber du verschenkst Punkte. {NORD} gewinnt sicher mit dem Buur – leg das Ass dazu.`}},{t:`choose`,text:`Bevor {OST} seine Karte legt: Im Stich liegen der Eichel-Under, der Eichel-König und dein Eichel-Ass. Welche der drei Karten sticht?`,tip:`Im Trumpf zählt die Trumpf-Rangfolge, nicht die der normalen Farben.`,options:[i(`EU`,`Under`),i(`EK`,`König`),i(`EA`,`Ass`)],answer:`EU`,wrong:{EA:`In einer normalen Farbe wäre das Ass die Beste. Im Trumpf aber steht es erst an dritter Stelle, hinter dem Under und dem Nell.`,EK:`Der König liegt im Trumpf noch hinter dem Ass. Der Under schlägt alles.`}},{t:`play`,seat:`OST`,code:`E7`},{t:`play`,seat:`NORD`,code:`E9`,text:`{NORD} spielt den Nell, jetzt der höchste Trumpf. {WEST} und {OST} müssen wieder Eichel bedienen, falls sie noch welche haben.`},{t:`play`,seat:`WEST`,code:`E8`},{t:`play`,seat:`SUED`,code:`E6`,text:`Du hast nur noch die Eichel 6. Eichel wurde ausgespielt, also musst du sie bedienen. Du hast keine Wahl, Bub.`,tip:`Farbzwang: Wer die ausgespielte Farbe hat, muss sie zugeben.`,wrong:{"*":`Farbzwang! Eichel wurde ausgespielt und du hast noch die Eichel 6 – die musst du spielen.`}},{t:`play`,seat:`OST`,code:`EO`},{t:`play`,seat:`NORD`,code:`SA`,text:`{NORD} spielt das Schellen-Ass. Du hast keine Schellen mehr – gleich siehst du, was du dann tun darfst.`},{t:`play`,seat:`WEST`,code:`S6`,text:`{WEST} gibt die Sechs zu. Jetzt bist du dran: keine Schellen, kein Trumpf. Schau, was {OST} noch auf der Hand hat, dann weisst du, wem dieser Stich gehört.`},{t:`play`,seat:`SUED`,code:`L6`,riddle:!0,text:`Du darfst jetzt jede Karte legen. Welche wirfst du ab?`,tip:`Wer nicht bedienen kann und den Stich nicht gewinnt, wirft die Karte ab, die er am wenigsten braucht.`,wrong:{LA:`Dein Schilten-Ass brauchst du noch, es holt später einen Stich. Wirf die Sechs ab.`,R10:`Die Rosen-Zehn bringt 10 Punkte – und die schenkst du den Gegnern, denn {OST} sticht diesen Stich gleich mit Trumpf. Wirf die Schilten 6 ab.`,R6:`Auch eine Sechs, aber die Rosen sind deine längste Farbe. Die hältst du zusammen. Wirf die Schilten 6 ab.`,"*":`{OST} hat keine Schellen mehr und sticht diesen Stich gleich mit Trumpf. Wirf die Karte ab, die dir am wenigsten bringt: die Schilten 6.`}},{t:`play`,seat:`OST`,code:`E10`,text:`{OST} hat keine Schelle mehr und sticht mit der Eichel 10. Trumpf schlägt jede andere Farbe, auch ein Ass. Sticht man ab, heisst das «Abstechen».`},{t:`play`,seat:`OST`,code:`LK`,text:`{OST} hat den Stich gewonnen und spielt aus: Schilten-König.`},{t:`play`,seat:`NORD`,code:`L7`},{t:`play`,seat:`WEST`,code:`L9`},{t:`play`,seat:`SUED`,code:`LA`,riddle:!0,text:`Schilten wurde ausgespielt, {NORD} und {WEST} haben mit Siebner und Neuner nachgelegt. Welche Karte spielst du?`,tip:`Das höchste Ass einer Farbe («Bock») gewinnt den Stich, wenn niemand mehr sticht.`,wrong:{L8:`Das ist erlaubt (Schilten bedienen), aber mit dem Ass holst du den Stich samt den Punkten.`,"*":`Farbzwang! Schilten wurde ausgespielt und du hast noch Schilten: Spiele das Schilten-Ass.`}},e(`Gut gemacht. So geht es weiter bis zum neunten Stich. Der letzte Stich zählt 5 Punkte extra, wer alle neun holt (Match), bekommt 100 dazu. Eine Hand hat 157 Punkte. Dazu kommen das Weisen (Folgen und Vierlinge) und der Stöck. Merk dir: Schieb, wenn du nichts hast, schmier, wenn der Partner sicher gewinnt, und wirf klein ab, wenn der Gegner sticht.`)]},{lesson:`Obenabe`,ziele:[`Obenabe ansagen`,`Die Acht zählt 8 Punkte`,`Das Zeichen des Partners lesen`,`Die Zehn auf den sicheren Stich legen`],zielAt:[1,3,16,22],einstieg:`Hier gibt es keinen Trumpf. Das ist leichter, als es klingt.`,regionId:`BE`,kind:`trick`,title:`Schieber`,order:t,score:`teams`,hands:{SUED:`EA EK EO S10 S7 S6 L9 L8 L10`,NORD:`E8 E6 L6 SA SK SO L7 RA R6`,OST:`E7 EU R7 S8 R9 RU RK LA LU`,WEST:`E9 E10 R8 S9 SU R10 RO LK LO`},steps:[e(`Zweite Hand: Obenabe. Hier gibt es gar keinen Trumpf. Es zählt nur, wer in der Farbe die höchste Karte hat. Du spielst wieder mit {NORD} gegen {OST} und {WEST}, und diesmal sagst du an.`,`Beim Obenabe sticht nichts: Wer die Farbe nicht hat, wirft ab.`),{t:`choose`,text:`Schau deine Hand an: Eichel-Ass, -König und -Ober, dazu zwei Zehner. Kein Under, kein Nell. Ein Farbtrumpf hätte hier wenig Halt. Was sagst du an?`,tip:`Obenabe passt zu Händen mit Assen, Königen und Obern. Die Karten sind dann alle «oben».`,options:[...r,{id:`SCHIEBEN`,label:`Schieben`}],answer:`OBENABE`,wrong:{EICHEL:`Ass, König und Ober sind schön, aber ohne Under und Nell ist Eichel als Trumpf dünn. Als Obenabe zählen genau diese Karten voll.`,SCHELLE:`In der Schelle hast du nur die Zehn, die Sieben und die Sechs. Das trägt nicht.`,ROSE:`Du hast keine einzige Rose. Wie willst du damit trumpfen?`,SCHILTE:`Schilten mit Zehn, Neun und Acht: kein Under, kein Nell. Nein.`,UNDENUFE:`Undenufe wäre etwas für Sechser und Siebner, und davon hast du kaum welche. Dein Wert steckt in den hohen Karten.`,SCHIEBEN:`Mit drei hohen Eicheln und zwei Zehnern schiebst du nicht. Das ist eine Hand für Obenabe – sag an.`},fx:{trump:`OBENABE`,bubbles:{SUED:`Obenabe!`}}},e(`Obenabe also. In jeder Farbe gilt die Rangfolge Ass, König, Ober, Under, Zehn, Neun, Acht, Sieben, Sechs. Wer die gespielte Farbe nicht hat, kann nicht stechen, sondern wirft ab. Das Ass einer Farbe ist darum immer ein sicherer Stich.`,`Wer die Farbe hat, muss sie zugeben – so wie sonst auch.`),{t:`choose`,text:`Eine Frage, die viele falsch beantworten: Wie viele Punkte zählt die Acht in Obenabe?`,tip:`Im Obenabe (und im Undenufe) hat die Acht einen eigenen Wert.`,options:[{id:`NULL`,label:`0 Punkte`},{id:`ACHT`,label:`8 Punkte`},{id:`ZEHN`,label:`10 Punkte`}],answer:`ACHT`,wrong:{NULL:`Im Farbtrumpf zählt die Acht nichts. Beim Obenabe aber 8 Punkte, merk dir das.`,ZEHN:`Zehn Punkte bringt nur die Zehn. Die Acht zählt, was sie heisst: 8.`}},{t:`play`,seat:`SUED`,code:`EA`,riddle:!0,text:`Du hast angesagt und spielst aus. Welche Karte?`,wrong:{EK:`Der König gewinnt hier auch, aber das Ass zuerst: Es ist die einzige Karte, die dir niemand nehmen kann. Ohne offene Karten wüsstest du nicht, wer das Ass hält.`,S10:`Mit der Zehn zu eröffnen ist heikel: Schon ein Ass oder König nimmt sie dir weg. Du hast sichere Stiche in der Eichel – fang dort an.`,"*":`Spiel zuerst die Farbe, in der du die höchsten Karten hast: die Eichel, und mit dem Ass beginnst du.`}},{t:`play`,seat:`OST`,code:`E7`},{t:`play`,seat:`NORD`,code:`E8`,text:`{NORD} gibt die Eichel 8 zu. In Obenabe sind das 8 Punkte für unser Team. Schmieren geht hier genauso.`},{t:`play`,seat:`WEST`,code:`E9`},{t:`play`,seat:`SUED`,code:`EK`,text:`Das Ass ist gespielt, jetzt ist der König die höchste Eichel. Spiel ihn aus.`,wrong:{"*":`Der König ist jetzt die höchste Eichel im Spiel. Spiel ihn aus.`}},{t:`play`,seat:`OST`,code:`EU`},{t:`play`,seat:`NORD`,code:`E6`},{t:`play`,seat:`WEST`,code:`E10`,text:`{WEST} hat nur noch die Zehn und muss sie zugeben, Farbzwang. 10 Punkte für uns.`},{t:`play`,seat:`SUED`,code:`EO`,text:`Jetzt ist der Ober die höchste Eichel. Spiel ihn aus, dann siehst du, was Obenabe heisst.`,wrong:{"*":`Spiel den Eichel-Ober: Er ist jetzt die höchste Eichel.`}},{t:`play`,seat:`OST`,code:`R7`,text:`{OST} hat keine Eichel mehr und kann nicht stechen, es gibt ja keinen Trumpf. Er wirft ab.`},{t:`play`,seat:`NORD`,code:`L6`,text:`Achtung, {NORD} wirft die Schilten 6 ab. Das ist ein Zeichen für dich: Eine tiefe Karte aus einer Farbe heisst, dass er diese Farbe nicht will.`,tip:`Verwerfen: Der Partner wirft eine tiefe Karte der Farbe ab, die er nicht will. Spiel ihm eine andere.`},{t:`play`,seat:`WEST`,code:`LO`},{t:`play`,seat:`SUED`,code:`S6`,riddle:!0,text:`Du hast den Stich geholt und spielst aus. Deine Eicheln sind aufgebraucht. Welche Karte spielst du?`,wrong:{S10:`Spiel nicht die Zehn. {NORD} hat das Schellen-Ass und holt den Stich – und deine Zehn bleibt für später.`,S7:`Auch Schellen, aber die Sechs ist noch kleiner. Spiel die kleinste Karte.`,"*":`{NORD} hat die Schilten abgeworfen und damit gesagt: Schilten nicht. Bleiben dir die Schellen. Spiel die kleinste.`}},{t:`play`,seat:`OST`,code:`S8`},{t:`play`,seat:`NORD`,code:`SA`,text:`{NORD} gewinnt mit dem Schellen-Ass und spielt als Nächster aus.`},{t:`play`,seat:`WEST`,code:`S9`},{t:`play`,seat:`NORD`,code:`SK`,text:`Das Ass ist weg, jetzt ist {NORD}s König die höchste Schelle.`},{t:`play`,seat:`WEST`,code:`SU`},{t:`play`,seat:`SUED`,code:`S10`,riddle:!0,text:`{NORD} hält diesen Stich sicher. Welche Schelle gibst du zu?`,wrong:{S7:`Die Sieben bringt nichts. {NORD} gewinnt den Stich sicher, also schmier die Zehn dazu: 10 Punkte für unser Team.`}},{t:`play`,seat:`OST`,code:`R9`},{t:`play`,seat:`NORD`,code:`SO`},{t:`play`,seat:`WEST`,code:`LK`},{t:`play`,seat:`SUED`,code:`S7`,text:`Du hast nur noch die Schellen 7. Spiel sie.`,wrong:{"*":`Farbzwang: Spiel die Schellen 7.`}},{t:`play`,seat:`OST`,code:`RU`},{t:`play`,seat:`NORD`,code:`RA`,text:`{NORD} spielt das Rosen-Ass und geht damit sicher.`},{t:`play`,seat:`WEST`,code:`RO`},{t:`play`,seat:`SUED`,code:`L10`,riddle:!0,text:`Du hast keine Rosen. {NORD} gewinnt mit dem Ass sicher. Was wirfst du ab?`,wrong:{L8:`Die Acht zählt 8 – gut. Aber die Zehn bringt 10. Schmier die Zehn.`,L9:`Die Neun zählt nichts. Der Stich gehört sicher uns: Schmier die Zehn.`}},{t:`play`,seat:`OST`,code:`RK`},{t:`info`,nurSchieber:!0,text:`Beim Schieber zählt Obenabe dreifach. Darum sagt man es nur an, wenn die Hand wirklich oben ist – so wie deine heute.`},e(`Sieben Stiche, und die Gegner haben keinen einzigen – so soll Obenabe aussehen, wie ein frisch gemähter Hang. Merk dir: Ass vor König vor Ober, ein Zeichen vom Partner lesen, die Zehn auf seinen sicheren Stich legen und nie vergessen, dass die Acht 8 Punkte zählt.`,`Obenabe gewinnst du mit hohen Karten in langen Farben.`)]},{lesson:`Trumpf ziehen`,ziele:[`Mit dem Trumpf ansagen`,`Erst die hohen Trümpfe spielen`,`Dann die Asse abziehen`],zielAt:[1,7,16],einstieg:`Jetzt zeig ich dir, in welcher Reihenfolge man spielt. Das macht den Unterschied.`,regionId:`BE`,kind:`trick`,title:`Schieber`,order:t,score:`teams`,hands:{SUED:`RU R9 RA RK RO EA SA LA L8`,OST:`R10 R7 E7 E9 EK S6 S9 L6 L9`,NORD:`R8 E6 E10 EU S7 S8 SU L7 LU`,WEST:`R6 E8 EO S10 SO SK L10 LO LK`},steps:[e(`Dritte Hand. Jetzt geht es um die Reihenfolge: Was spielst du zuerst, was zuletzt? Du bist wieder Vorhand und sagst an. Dieselbe Hand, in der falschen Reihenfolge gespielt, bringt nur die Hälfte.`,`Wer den Trumpf ansagt, hat meist die Karten, ihn auch durchzuziehen.`),{t:`choose`,text:`Schau deine Karten an: Rosen-Under, -Nell, -Ass, -König und -Ober, dazu drei Asse. Was sagst du an?`,tip:`Fünf Rosen mit Buur und Nell sind eine Trumpfhand, wie sie im Buche steht.`,options:[...r,{id:`SCHIEBEN`,label:`Schieben`}],answer:`ROSE`,wrong:{EICHEL:`In der Eichel hast du nur das Ass. Deine Stärke liegt in den Rosen.`,SCHELLE:`Nur das Schellen-Ass. Sag Rose an.`,SCHILTE:`Ass und Acht in der Schilte – das trägt nicht. Du hast fünf Rosen!`,OBENABE:`Drei Asse sind schön, aber mit Buur und Nell in den Rosen sagst du Trumpf an.`,UNDENUFE:`Mit Assen Undenufe? Das ist das Gegenteil von dem, was du hast. Sag Rose an.`,SCHIEBEN:`Mit fünf Rosen, darunter Buur und Nell, schiebst du doch nicht. Sag selber an!`},fx:{trump:`ROSE`,bubbles:{SUED:`Rose!`}}},e(`Rose ist Trumpf, und du hältst die fünf besten: Buur, Nell, Ass, König und Ober. Zusammen haben die Gegner nur vier Rosen, und die sind klein. Das heisst: Wenn du diese Rosen herausholst, hat keiner mehr etwas zum Stechen.`),{t:`play`,seat:`SUED`,code:`RU`,riddle:!0,text:`Du spielst aus. Die Gegner haben noch Rosen. Welche Karte spielst du?`,wrong:{R9:`Der Nell ist gut, aber der Buur ist noch besser. Die höchste Karte zuerst: Sie holt die gegnerischen Trümpfe heraus.`,RA:`Ass, König und Ober sind schwächer als Buur und Nell. Spiel die höchsten Trümpfe zuerst, so ziehst du die Gegner leer.`,RK:`Ass, König und Ober sind schwächer als Buur und Nell. Spiel die höchsten Trümpfe zuerst, so ziehst du die Gegner leer.`,RO:`Ass, König und Ober sind schwächer als Buur und Nell. Spiel die höchsten Trümpfe zuerst, so ziehst du die Gegner leer.`,EA:`Mit dem Ass anfangen? Die Gegner haben noch Rosen und stechen es dir weg. Zuerst Trumpf.`,SA:`Mit dem Ass anfangen? Die Gegner haben noch Rosen und stechen es dir weg. Zuerst Trumpf.`,LA:`Mit dem Ass anfangen? Die Gegner haben noch Rosen und stechen es dir weg. Zuerst Trumpf.`,"*":`Die Gegner haben noch Rosen. Zieh zuerst die Trümpfe, mit dem höchsten: dem Buur.`}},{t:`play`,seat:`OST`,code:`R7`},{t:`play`,seat:`NORD`,code:`R8`},{t:`play`,seat:`WEST`,code:`R6`,text:`{WEST} gibt die Sechs zu. Auf den Buur gibt es nichts zu sagen.`},{t:`play`,seat:`SUED`,code:`R9`,text:`Und jetzt der Nell, der zweithöchste Trumpf. Er holt die letzte gegnerische Rose heraus.`,wrong:{"*":`Spiel den Nell, die Rosen 9.`}},{t:`play`,seat:`OST`,code:`R10`,text:`{OST} muss die Zehn zugeben: 10 Punkte für uns. Das waren alle Rosen der Gegner. Schau: {NORD} und {WEST} haben keine mehr.`},{t:`play`,seat:`NORD`,code:`L7`,text:`{NORD} hat keine Rose mehr und wirft ab.`},{t:`play`,seat:`WEST`,code:`E8`},{t:`choose`,text:`Die Gegner haben keinen Trumpf mehr. Du hältst Ass, König und Ober in den Rosen und drei Asse in den anderen Farben. Was ist jetzt dein Plan?`,tip:`Asse in den Nebenfarben sind nur sicher, solange niemand sie mit Trumpf stechen kann.`,options:[{id:`TRUMPF`,label:`Weiter Trumpf spielen`},{id:`ASSE`,label:`Meine Asse abziehen`},{id:`TIEF`,label:`Zuerst die tiefen Karten loswerden`}],answer:`ASSE`,wrong:{TRUMPF:`Das gewinnt auch. Aber deine Rosen kann dir keiner mehr nehmen, die haben Zeit. Die Asse in den anderen Farben bringen jetzt Punkte, weil niemand mehr stechen kann.`,TIEF:`Tiefe Karten zuerst verschenkt Stiche. Du hast lauter sichere Gewinner in der Hand – spiel sie aus.`}},{t:`play`,seat:`SUED`,code:`EA`,text:`Das Eichel-Ass: Die Gegner haben keinen Trumpf mehr, also kann es keiner stechen.`,wrong:{"*":`Zieh jetzt ein Ass: Das Eichel-Ass ist ein sicherer Stich.`}},{t:`play`,seat:`OST`,code:`E7`},{t:`play`,seat:`NORD`,code:`E6`},{t:`play`,seat:`WEST`,code:`EO`},{t:`replay`,tricks:[`SA S6 S7 SO`,`LA L6 LU LO`],text:`Schellen-Ass und Schilten-Ass gehen gleich durch. Die Gegner müssen bedienen oder abwerfen – stechen kann niemand.`},{t:`play`,seat:`SUED`,code:`RK`,text:`Die Asse sind eingesammelt. Jetzt kommen deine letzten Rosen, der König zuerst.`,wrong:{"*":`Spiel jetzt den Rosen-König.`}},{t:`play`,seat:`OST`,code:`E9`},{t:`play`,seat:`NORD`,code:`S8`},{t:`play`,seat:`WEST`,code:`LK`},{t:`choose`,nurSchieber:!0,text:`Du hast König und Ober der Rosen auf der Hand: den Stöck. Gleich spielst du die zweite der beiden Karten aus. Wann sagst du den Stöck an?`,tip:`Der Stöck ist 20 Punkte wert und hat mit dem Weis nichts zu tun.`,options:[{id:`ERSTER`,label:`Beim ersten Stich, zusammen mit dem Weis`},{id:`ZWEITE`,label:`Wenn ich die zweite der beiden Karten ausspiele`},{id:`ENDE`,label:`Erst am Ende der Hand`}],answer:`ZWEITE`,wrong:{ERSTER:`Nein, der Weis kommt beim ersten Stich, der Stöck nicht. Erst bei der zweiten der beiden Karten sagst du ihn an.`,ENDE:`Zu spät, dann hättest du ihn vergessen. Du sagst ihn an, wenn du die zweite Karte ausspielst.`},fx:{bubbles:{SUED:`Stöck!`}}},{t:`play`,seat:`SUED`,code:`RO`,text:`Der Rosen-Ober, die zweite Karte.`,wrong:{"*":`Spiel den Rosen-Ober.`}},{t:`play`,seat:`OST`,code:`S9`},{t:`play`,seat:`NORD`,code:`EU`},{t:`play`,seat:`WEST`,code:`SK`},{t:`info`,nurSchieber:!0,text:`Das war der Stöck: König und Ober im Trumpf, 20 Punkte, und er zählt immer, auch wenn dein Team die Hand sonst verliert. Merk dir: König und Ober im Trumpf zusammen auf einer Hand – das sind 20 Punkte extra.`,fx:{badges:[`Stöck: 20 Punkte`]}},e(`Sieben Stiche, kein einziger für die Gegner. Das gelingt nicht immer, aber die Reihenfolge ist immer gleich: erst die hohen Trümpfe, damit die Gegner leer sind, dann die Asse, dann den Rest. Wer es umgekehrt macht, sieht seine Asse gestochen.`,`Trumpf ziehen, dann Asse: Das ist der Grundstein jeder guten Hand.`)]}],o=[{regionId:`WOLHUSEN`,kind:`trick`,title:`Entlebucher`,lesson:`Der Kartenwunsch`,ziele:[`Eine Karte wünschen`,`Den Trumpf ansagen`,`Erst die Trümpfe ziehen`,`Dann die Asse spielen`],zielAt:[2,3,9,13],einstieg:`Im Entlebucher darfst du dir etwas wünschen. Schau, was daraus wird.`,order:t,score:`teams`,hands:{SUED:`EA E8 SA S7 RU R9 RA RK R7`,NORD:`E6 EK S9 SK L7 L9 LA R6 R8`,WEST:`E10 E7 S6 SU S10 L6 L8 L10 LO`,OST:`E9 EO EU S8 SO LK LU R10 RO`},initial:{SUED:{replace:[`R9`,`L6`]},WEST:{replace:[`L6`,`R9`]}},steps:[e(`Nu, dann schau dir das an. Im Entlebucher jasst du wie beim Schieber, nur schieben darf keiner: Die Vorhand sagt den Trumpf immer selbst an. Dafür darf sie sich vorher eine Karte wünschen. Du spielst mit {NORD} gegen {OST} und {WEST}, alle Karten liegen offen.`,`Gespielt wird gegen den Uhrzeigersinn: Du, dann {OST}, {NORD}, {WEST}.`),{t:`choose`,text:`Du bist Vorhand. Deine Rosen sind stark: Under, Ass, König und Sieben. Aber der Nell fehlt dir, und {WEST} hat ihn. Wer deine Wunschkarte hält, muss sie dir geben. Was wünschst du dir?`,tip:`Wünsche dir die Karte, die deine beste Farbe am meisten stärkt: im Trumpf der Buur oder der Nell.`,options:[{id:`R9`,label:`Rosen 9 (Nell)`,code:`R9`},{id:`EK`,label:`Eichel König`,code:`EK`},{id:`LA`,label:`Schilte Ass`,code:`LA`}],answer:`R9`,wrong:{EK:`Der Eichel-König bringt dir wenig. Deine Rosen sind das Pfund, und denen fehlt der Nell.`,LA:`Ein Ass in einer Nebenfarbe ist nett. Aber der Nell macht aus deinen Rosen fast unschlagbare Trümpfe.`},fx:{badges:[`Wunsch: Rosen 9`],bubbles:{SUED:`Rosen Nell, bitte!`}}},{t:`pick`,code:`L6`,exchange:{seat:`WEST`,code:`R9`},text:`{WEST} gibt dir den Nell. Dafür gibst du ihm verdeckt eine Karte zurück, und nur ihr zwei wisst, welche. Gib die schwächste: die Schilte 6.`,tip:`Gib die Karte zurück, die dir am wenigsten nützt, meist die kleinste einer Nebenfarbe.`,wrong:{"*":`Die brauchst du noch. Gib die Schilte 6 zurück, die ist am wenigsten wert.`},fx:{bubbles:{WEST:`Na gut …`}}},{t:`choose`,text:`Jetzt hast du Under, Nell, Ass, König und Sieben in Rosen. Was sagst du als Trumpf an?`,tip:`Ansagen: Die Farbe mit den meisten und höchsten Karten ist ein guter Trumpf.`,options:r,answer:`ROSE`,wrong:{"*":`Deine stärkste Farbe sind die Rosen mit Under, Nell, Ass, König und Sieben. Sag Rose an.`},fx:{trump:`ROSE`,badges:[],bubbles:{SUED:`Rose!`}}},{t:`play`,seat:`SUED`,code:`RU`,riddle:!0,text:`Du spielst aus. Welche Karte?`,wrong:{R9:`Auch Trumpf, aber der Nell ist nur die zweitstärkste Karte. Der Under zuerst.`,RA:`Das Ass ist stark, aber im Trumpf stehen Under und Nell darüber. Fang mit der stärksten an.`,EA:`Das Eichel-Ass ist noch nicht sicher, die Gegner haben Rosen und könnten stechen. Zieh zuerst die Trümpfe.`,"*":`Deine Rosen sind angesagt. Spiel zuerst die stärkste Rose.`}},{t:`play`,seat:`OST`,code:`R10`,text:`{OST} muss Trumpf bedienen und gibt die Zehn.`},{t:`play`,seat:`NORD`,code:`R8`},{t:`choose`,text:`{WEST} hat keine Rosen mehr, den Nell hast du ihm ja abgenommen. Was darf er jetzt legen?`,options:[{id:`ANY`,label:`Eine beliebige Karte`},{id:`FARBE`,label:`Nur Schilte`},{id:`PASS`,label:`Er muss passen`}],answer:`ANY`,wrong:{FARBE:`Er soll Rosen bedienen, die hat er nicht. Dann ist er frei und darf legen, was er will.`,PASS:`Passen gibt es im Stich nicht, jeder legt eine Karte.`}},{t:`play`,seat:`WEST`,code:`S6`,text:`Er wirft eine kleine Schelle ab.`},{t:`play`,seat:`SUED`,code:`R9`,riddle:!0,text:`Der Under ist draussen. Du hast den Stich und spielst aus. Welche Karte jetzt?`,wrong:{RA:`Das Ass ist gut, aber der Nell steht im Trumpf höher. Den Nell zuerst, bevor ihn dir einer schnappt.`,RK:`Der König ist kleiner als Nell und Ass. Spiel die stärkste Trumpfkarte.`,EA:`Noch nicht. Die Gegner haben noch Rosen. Erst die ziehen.`,"*":`Zieh weiter Trumpf, mit der stärksten Karte, die du hast.`}},{t:`play`,seat:`OST`,code:`RO`},{t:`play`,seat:`NORD`,code:`R6`},{t:`play`,seat:`WEST`,code:`L8`},{t:`play`,seat:`SUED`,code:`EA`,text:`Die Gegner haben keinen Trumpf mehr. Jetzt gehören dir die Asse: Spiel das Eichel-Ass.`,tip:`Sind die gegnerischen Trümpfe weg, sind deine Asse sichere Stiche.`,wrong:{"*":`Spiel das Eichel-Ass: Die Gegner haben keinen Trumpf mehr, es ist ein sicherer Stich.`}},{t:`play`,seat:`OST`,code:`E9`},{t:`play`,seat:`NORD`,code:`E6`},{t:`play`,seat:`WEST`,code:`E7`},e(`Siehst du? Der Wunsch hat dir den Nell gebracht, und der Rest war Handwerk. Alles andere läuft wie im Schieber: Farbzwang, Weis, Stöck, 157 Punkte pro Hand, Zielpunktzahl 1000.`)]},{regionId:`WOLHUSEN`,kind:`trick`,title:`Entlebucher`,lesson:`Den Buur dem Gegner abluchsen`,ziele:[`Den Buur vom Gegner wünschen`,`Sehen, was der Wunsch verrät`,`Stichpunkte zusammenzählen`,`Asse holen, Trümpfe aufheben`],zielAt:[2,3,9,10],einstieg:`Diesmal fragst du den richtigen Mann. Schau genau hin, wo die Karten liegen.`,order:t,score:`teams`,hands:{SUED:`EU EO EK E10 E8 E7 SA R9 R7`,OST:`E6 L6 RA RK RO LA LK S10 S9`,NORD:`E9 S8 S7 SU R10 R8 L9 L8 L7`,WEST:`EA S6 SO SK R6 RU L10 LU LO`},initial:{SUED:{replace:[`EU`,`L6`]},OST:{replace:[`L6`,`EU`]}},steps:[e(`Zweite Hand. Diesmal schaust du, wen du fragst. Du hast viele Eichel, aber weder Under noch Nell. Beide sitzen am Tisch, und nicht beim selben Spieler. Schau genau hin, wo sie liegen.`),{t:`choose`,text:`Du bist Vorhand und darfst dir eine Karte wünschen. Der Buur sitzt bei {OST}, der Nell bei deinem Partner {NORD}, das Ass bei {WEST}. Was wünschst du dir?`,tip:`Der Buur ist die stärkste Karte im Spiel. Und wenn du ihn einem Gegner abnimmst, fehlt er ihm erst recht.`,options:[{id:`EU`,label:`Eichel Under (Buur)`,code:`EU`},{id:`E9`,label:`Eichel 9 (Nell)`,code:`E9`},{id:`EA`,label:`Eichel Ass`,code:`EA`}],answer:`EU`,wrong:{E9:`Der Nell sitzt bei deinem Partner, den holst du dir nicht gern. Wichtiger ist der Buur bei {OST}, denn der ist die stärkste Karte.`,EA:`Das Ass hilft, aber der Buur schlägt es. Und der sitzt bei {OST}, einem Gegner. Hol dir zuerst den Buur.`},fx:{badges:[`Wunsch: Eichel Under`],bubbles:{SUED:`Den Buur, bitte!`}}},{t:`pick`,code:`L6`,exchange:{seat:`OST`,code:`EU`},text:`{OST} muss dir den Buur geben und kriegt dafür verdeckt eine Karte von dir. Er weiss, dass sie von dir kommt. Gib ihm also nichts, was er brauchen kann: die Schilte 6.`,tip:`Der Halter bekommt deine Rückgabekarte. Gib dem Gegner nie etwas Nützliches.`,wrong:{"*":`Die brauchst du selber. Gib die Schilte 6 zurück, damit kann {OST} nichts anfangen.`},fx:{bubbles:{OST:`Hmpf …`}}},{t:`choose`,text:`Dein Wunsch war für alle sichtbar: {OST} hat den Buur abgegeben. Was können {OST} und {WEST} daraus schliessen?`,options:[{id:`EICHEL`,label:`Dass du Eichel ansagst`},{id:`NICHTS`,label:`Gar nichts`},{id:`SCHIEBEN`,label:`Dass du schieben willst`}],answer:`EICHEL`,wrong:{NICHTS:`Doch. Wer sich den Under wünscht, hat meist die Farbe dazu. Der Wunsch verrät einiges.`,SCHIEBEN:`Schieben gibt es im Entlebucher gar nicht.`}},{t:`choose`,text:`Jetzt sag den Trumpf an.`,options:r,answer:`EICHEL`,wrong:{"*":`Du hast sechs Eichel mit dem Buur. Was soll es sonst sein?`},fx:{trump:`EICHEL`,badges:[],bubbles:{SUED:`Eichel!`}}},{t:`play`,seat:`SUED`,code:`EU`,text:`Du spielst aus, natürlich mit dem Buur. Jetzt muss jeder Trumpf zugeben, der noch einen hat.`},{t:`play`,seat:`OST`,code:`E6`,text:`{OST} hat nur noch die Sechs. Sein Buur liegt ja bei dir.`},{t:`play`,seat:`NORD`,code:`E9`,text:`{NORD} hat nur noch den Nell und muss ihn zugeben. 14 Punkte für euer Team.`},{t:`play`,seat:`WEST`,code:`EA`,text:`Auch {WEST} muss sein Ass opfern. Ein Stich, und alle Trümpfe der Gegner liegen am Tisch.`},{t:`choose`,text:`Wie viele Punkte hat dieser Stich eurem Team gebracht? Buur 20, Sechs 0, Nell 14 und Ass 11.`,options:[{id:`P34`,label:`34`},{id:`P45`,label:`45`},{id:`P65`,label:`65`}],answer:`P45`,wrong:{P34:`Da fehlt das Ass: 20 plus 14 plus 11 gibt mehr.`,P65:`Zu viel. Rechne nochmal: 20 plus 14 plus 11.`}},{t:`play`,seat:`SUED`,code:`SA`,text:`Keiner hat mehr Eichel, deine restlichen Trümpfe sind die höchsten. Aber heb sie auf. Hol dir jetzt die Asse: das Schellen-Ass.`,tip:`Trümpfe, die niemand mehr schlagen kann, kannst du jederzeit spielen. Erst die anderen Asse.`,wrong:{EK:`Der Trumpf-König ist auch sicher, aber der läuft dir nicht davon. Hol zuerst mit dem Ass, was du holen kannst.`,"*":`Spiel das Schellen-Ass, es holt jetzt 25 Punkte.`}},{t:`play`,seat:`OST`,code:`S10`,text:`{OST} muss Schelle bedienen und opfert die Zehn.`},{t:`play`,seat:`NORD`,code:`S7`},{t:`play`,seat:`WEST`,code:`SK`},e(`Siehst du den Unterschied? Hätte dein Partner den Buur gehabt, wäre es nur ein Tausch gewesen. So hast du ihn dem Gegner genommen, das bringt doppelt. Merk dir: Der Wunsch ist offen, alle sehen ihn. Nur die Rückgabekarte kennt ausser dir allein der Halter.`)]},{regionId:`WOLHUSEN`,kind:`trick`,title:`Entlebucher`,lesson:`Wunsch und Obenabe`,ziele:[`Ein fehlendes Ass wünschen`,`Obenabe ansagen`,`Wissen: Obenabe kennt kein Stechen`,`Sichere Stiche erkennen`],zielAt:[2,3,15,17],einstieg:`Mit vielen Assen und Königen wird es leicht. Du brauchst nur noch eins dazu.`,order:t,score:`teams`,hands:{SUED:`EA EK SA SK RA RK LA L10 L8`,OST:`E10 EO SO S9 S8 RO R9 R8 R7`,NORD:`EU E9 S10 SU S7 R10 RU R6 L6`,WEST:`E8 E7 E6 S6 L7 LK LO LU L9`},initial:{SUED:{replace:[`LA`,`L7`]},WEST:{replace:[`L7`,`LA`]}},steps:[e(`Dritte Hand. Schau dein Blatt an: drei Asse und drei Könige, kreuz und quer über alle Farben verteilt. Ob das für eine bestimmte Farbe als Trumpf taugt? Überleg dir das, aber zuerst darfst du dir etwas wünschen.`),{t:`choose`,text:`Du bist Vorhand und darfst dir eine Karte wünschen. Dir fehlt noch das Schilten-Ass, es liegt bei {WEST}. Was wünschst du dir?`,tip:`In Obenabe gewinnt immer die höchste Karte der ausgespielten Farbe. Asse sind Gold.`,options:[{id:`LA`,label:`Schilte Ass`,code:`LA`},{id:`EO`,label:`Eichel Ober`,code:`EO`},{id:`SU`,label:`Schellen Under`,code:`SU`}],answer:`LA`,wrong:{EO:`Ein Ober hilft dir kaum, und Asse hast du schon drei. Mach das vierte voll.`,SU:`In Obenabe ist ein Under nur eine Mittelkarte. Ein Ass wäre viel mehr wert.`},fx:{badges:[`Wunsch: Schilten-Ass`],bubbles:{SUED:`Schilten-Ass, bitte!`}}},{t:`pick`,code:`L7`,exchange:{seat:`WEST`,code:`LA`},text:`{WEST} gibt dir das Ass. Welche Karte gibst du zurück? In Obenabe zählt die Acht 8 Punkte, die Zehn 10. Die Sieben zählt nichts. Gib die Schilte 7.`,tip:`Gib die Karte zurück, die weder Stiche noch Punkte bringt.`,wrong:{L8:`Die Acht zählt in Obenabe 8 Punkte. Die Sieben ist wertlos, gib die.`,L10:`Die Zehn bringt 10 Punkte, die behältst du. Gib die Sieben.`,"*":`Die brauchst du noch. Gib die Schilte 7 zurück, die ist ganz wertlos.`},fx:{bubbles:{WEST:`Da, bitte.`}}},{t:`choose`,text:`Jetzt hast du vier Asse und drei Könige. Was sagst du an?`,options:r,answer:`OBENABE`,wrong:{UNDENUFE:`Undenufe ist das Gegenteil: Dort gewinnt die tiefste Karte. Du hast aber lauter hohe.`,"*":`Eine Farbe als Trumpf lohnt sich nicht: Deine Asse und Könige liegen in vier Farben verteilt. Sag Obenabe an.`},fx:{trump:`OBENABE`,badges:[],bubbles:{SUED:`Obenabe!`}}},{t:`play`,seat:`SUED`,code:`EA`,text:`Du spielst aus. In Obenabe gibt es keinen Trumpf. Wer die höchste Karte der ausgespielten Farbe legt, holt den Stich. Fang mit dem Eichel-Ass an.`,wrong:{"*":`Spiel ein Ass, das ist ein sicherer Stich. Fang mit dem Eichel-Ass an.`}},{t:`play`,seat:`OST`,code:`E10`,text:`{OST} muss Eichel bedienen und opfert die Zehn.`},{t:`play`,seat:`NORD`,code:`EU`},{t:`play`,seat:`WEST`,code:`E8`},{t:`play`,seat:`SUED`,code:`SA`,text:`Weiter mit dem Schellen-Ass.`},{t:`play`,seat:`OST`,code:`SO`},{t:`play`,seat:`NORD`,code:`S10`,text:`{NORD} ist dein Partner und schmiert dir die Zehn.`},{t:`play`,seat:`WEST`,code:`S6`},{t:`play`,seat:`SUED`,code:`RA`,text:`Und jetzt das Rosen-Ass.`},{t:`play`,seat:`OST`,code:`RO`},{t:`play`,seat:`NORD`,code:`R10`},{t:`choose`,text:`{WEST} hat keine Rosen mehr. Er hält aber den Schilten-König. Kann er mit dem das Rosen-Ass schlagen?`,options:[{id:`JA`,label:`Ja, der König sticht`},{id:`NEIN`,label:`Nein`}],answer:`NEIN`,wrong:{JA:`Nein, in Obenabe gibt es keinen Trumpf. Nur die ausgespielte Farbe zählt.`}},{t:`play`,seat:`WEST`,code:`L7`,text:`So ist es. Jede andere Farbe ist nur ein Abwurf. Er wirft die Schilte 7 ab, genau die Karte, die du ihm zurückgegeben hast.`},{t:`choose`,text:`Du hast noch Eichel-König, Schellen-König, Rosen-König, Schilten-Ass, Schilten-Zehn und Schilten-Acht. Welche dieser Karten kann dir {WEST} mit seinem König abknöpfen, wenn du sie jetzt ausspielst?`,options:[{id:`EK`,label:`Eichel-König`,code:`EK`},{id:`SK`,label:`Schellen-König`,code:`SK`},{id:`L10`,label:`Schilten-Zehn`,code:`L10`}],answer:`L10`,wrong:{EK:`Das Eichel-Ass ist schon gespielt, dein König ist jetzt die höchste Eichel.`,SK:`Auch das Schellen-Ass ist weg, dein König steht an der Spitze.`}},{t:`play`,seat:`SUED`,code:`EK`,text:`Dein Eichel-König ist sicher. Mit der Schilten-Zehn wartest du, bis {WEST} den König abgegeben hat.`},{t:`play`,seat:`OST`,code:`EO`},{t:`play`,seat:`NORD`,code:`E9`},{t:`play`,seat:`WEST`,code:`E7`},e(`Gut gemacht. Merk dir: Du wünschst dir, was deine Ansage stärkt, und gibst zurück, was dir nichts nützt. Aber denk daran, dass die Gegner den Wunsch sehen: Er verrät, was du vorhast.`)]}],s={EICHEL:{id:`EICHEL`,label:`Eichel`,sub:`x1`},ROSE:{id:`ROSE`,label:`Rose`,sub:`x2`},SCHILTE:{id:`SCHILTE`,label:`Schilte`,sub:`x3`},SCHELLE:{id:`SCHELLE`,label:`Schelle`,sub:`x4`},OBENABE:{id:`OBENABE`,label:`Obenabe`,sub:`x5`},UNDENUFE:{id:`UNDENUFE`,label:`Undenufe`,sub:`x6`},SLALOM:{id:`SLALOM`,label:`Slalom`,sub:`x7`},GUSCHTI:{id:`GUSCHTI`,label:`Guschti/Mary`,sub:`x8`},JOKER1:{id:`JOKER1`,label:`Joker 1`,sub:`x9`},JOKER2:{id:`JOKER2`,label:`Joker 2`,sub:`x10`}},c=Object.values(s),l=[{regionId:`SOLOTHURN_BASEL`,kind:`trick`,title:`Coiffeur`,lesson:`Starke Hand, hoher Faktor`,ziele:[`Starke Hand, hohes Feld wählen`,`Den Joker-Trumpf ansagen`,`Erst Trumpf ziehen, dann Asse`,`Punkte mal Faktor rechnen`],zielAt:[1,2,12,16],einstieg:`Beim Coiffeur wählst du dein Feld selbst. Ich zeig dir, wie man es klug tut.`,order:t,score:`teams`,hands:{SUED:`EA SA RA RK LU L9 LA LK L6`,NORD:`EU E10 E9 SK S9 S8 R9 R8 LO`,OST:`EK EO S10 S6 RO RU R10 L10 L8`,WEST:`E8 E7 E6 SO SU S7 R7 R6 L7`},steps:[e(`Nu, dann schau dir das an. Beim Coiffeur hat jedes Team eine Tafel mit zehn Feldern: Eichel, Rose, Schilte, Schelle, Obenabe, Undenufe, Slalom, Guschti/Mary und zwei Joker. Jedes Feld hat einen Faktor von x1 bis x10, und die Punkte der Runde zählen mal diesen Faktor. Jedes Feld spielt dein Team genau einmal. Du musst also klug entscheiden, welche Hand du wohin steckst.`,`Gespielt wird gegen den Uhrzeigersinn: Du, dann {OST}, {NORD}, {WEST}.`),{t:`choose`,text:`Du bist Ansager und wählst ein freies Feld. Schau dein Blatt an: Schilten-Under, Nell, Ass und König, dazu noch drei Asse und Könige. Hmpf, das ist keine Hand für ein kleines Feld. Welches nimmst du?`,tip:`Starke Hände in hohe Faktoren, schwache in tiefe. Mit einem Joker bestimmst du den Trumpf frei.`,options:c,answer:`JOKER1`,wrong:{EICHEL:`Eichel mit x1? Da verschenkst du neun Zehntel von dem, was diese Hand wert ist.`,SCHILTE:`Die Schilte stimmt als Trumpf, aber im Feld Schilte zählt es nur x3. Nimm einen Joker: Da sagst du die Schilte genauso an, aber mit viel mehr Faktor.`,JOKER2:`Joker 2 zählt sogar x10, richtig gerechnet. Aber heb dir den für eine noch bessere Hand auf. Nimm für dieses Mal den ersten Joker.`,"*":`Das ist mir zu bescheiden. Mit dieser Hand holst du viele Punkte, also soll der Faktor auch gross sein. Greif zu einem Joker.`},fx:{badges:[`Joker 1 · x9`]}},{t:`choose`,text:`Ein Joker darf jede Spielart sein. Welchen Trumpf sagst du an? Zähl nach, wo dein Blatt am stärksten ist.`,tip:`Beim Joker wählst du Farbe, Obenabe, Undenufe, Slalom oder Guschti/Mary.`,options:r,answer:`SCHILTE`,wrong:{"*":`Deine Schilten mit Under, Nell, Ass und König sind die stärkste Farbe. Sag Schilte an.`},fx:{trump:`SCHILTE`,badges:[`Joker 1 · x9`],bubbles:{SUED:`Schilte!`}}},{t:`play`,seat:`SUED`,code:`LU`,riddle:!0,text:`Du spielst aus. Welche Karte?`,wrong:{L9:`Auch Trumpf, aber der Nell ist nur die zweitstärkste Karte. Der Under schlägt ihn. Beginn mit der stärksten.`,LA:`Das Ass ist stark, aber im Trumpf stehen Under und Nell darüber. Die stärkste Karte kommt zuerst.`,EA:`Das Eichel-Ass ist noch nicht sicher: Die Gegner haben Schilten und könnten es abstechen. Zieh zuerst die Trümpfe.`,"*":`Du hast die stärkste Farbe angesagt. Spiel damit auf und zieh die gegnerischen Trümpfe.`}},{t:`play`,seat:`OST`,code:`L10`,text:`{OST} muss Schilte bedienen und legt die Zehn zu: 10 Punkte für dich.`},{t:`play`,seat:`NORD`,code:`LO`},{t:`choose`,text:`Drei Karten liegen: dein Under, die Zehn von {OST} und der Ober von {NORD}. Welche gewinnt, wenn {WEST} nichts Besseres hat?`,options:[{id:`LU`,label:`Schilten-Under`,code:`LU`},{id:`L10`,label:`Schilten-Zehn`,code:`L10`},{id:`LO`,label:`Schilten-Ober`,code:`LO`}],answer:`LU`,wrong:{L10:`Im Trumpf steht die Zehn weit hinter Under, Nell, Ass, König und Ober.`,LO:`Der Ober ist im Trumpf nur Mittelfeld. Der Under schlägt alles.`}},{t:`play`,seat:`WEST`,code:`L7`},{t:`play`,seat:`SUED`,code:`L9`,riddle:!0,text:`Der Buur ist durch. Du hast den Stich und spielst wieder aus. Welche Karte jetzt?`,wrong:{LA:`Das Ass ist stark, aber im Trumpf ist der Nell die zweitstärkste Karte. Spiel ihn zuerst, bevor ihn dir einer schnappt.`,LK:`Der König ist kleiner als Nell und Ass. Spiel die stärkste Trumpfkarte, die du noch hast.`,EA:`Noch nicht. Erst müssen die letzten Trümpfe der Gegner aus der Hand.`,"*":`Zieh weiter Trumpf, und zwar mit der stärksten Karte, die du noch hast.`}},{t:`play`,seat:`OST`,code:`L8`,text:`{OST} muss seine letzte Schilte zugeben.`},{t:`play`,seat:`NORD`,code:`R8`,text:`{NORD} und {WEST} haben keine Schilten mehr. Die dürfen jetzt abwerfen, was sie wollen.`},{t:`play`,seat:`WEST`,code:`E6`},{t:`play`,seat:`SUED`,code:`EA`,text:`Die Gegner haben keinen Trumpf mehr. Jetzt gehören dir die Asse: Eichel-Ass, bitte.`,tip:`Sind die Trümpfe der Gegner weg, sind Asse sichere Stiche.`,wrong:{"*":`Spiel das Eichel-Ass. Es ist jetzt ein sicherer Stich.`}},{t:`play`,seat:`OST`,code:`EK`,text:`{OST} muss Eichel bedienen und opfert den König.`},{t:`play`,seat:`NORD`,code:`E9`},{t:`play`,seat:`WEST`,code:`E8`},{t:`choose`,text:`Rechnen wir: Deine drei Stiche brachten 33, 14 und 15 Punkte, zusammen 62. Wie viele Punkte schreibst du dir damit im Feld Joker 1 (x9) gut?`,options:[{id:`P62`,label:`62`},{id:`P124`,label:`124`},{id:`P558`,label:`558`},{id:`P620`,label:`620`}],answer:`P558`,wrong:{P62:`Das wären die Punkte ohne Faktor. Im Feld zählt alles mal 9.`,P124:`Das wäre mal 2. Das Feld Joker 1 hat den Faktor 9.`,P620:`Das wäre mal 10, aber 62 mal 9 ist weniger.`}},e(`Merk dir: Starke Hand in ein hohes Feld, schwache in ein tiefes. Am Ende zählt die Summe über alle zehn Felder. Und wenn dir ein Feld gerade nicht liegt, darfst du auch schieben.`)]},{regionId:`SOLOTHURN_BASEL`,kind:`trick`,title:`Coiffeur`,lesson:`Schwache Hand, tiefes Feld`,ziele:[`Schwache Hand, tiefes Feld wählen`,`Felder und Faktoren vergleichen`,`Asse früh ausspielen`,`Trumpf bedienen`],zielAt:[1,7,13,17],einstieg:`Auch eine schwache Hand ist keine Katastrophe. Du musst nur das richtige Feld wählen.`,order:t,score:`teams`,hands:{SUED:`E7 E6 SA SK R9 R6 L8 L7 L6`,OST:`S8 E8 EU E9 RA RK R10 LA LK`,NORD:`E10 EO S10 S9 R7 R8 RU L9 L10`,WEST:`EK EA S7 S6 SU SO RO LU LO`},steps:[e(`Zweite Hand, andere Karten. Schau genau hin: kein Under, kein Nell, nur ein Schellen-Ass und ein König. Mit so einem Blatt gewinnt man nicht viel, und das ist nicht schlimm. Beim Coiffeur kommt es darauf an, wohin du eine Hand steckst.`),{t:`choose`,text:`Du bist Ansager und musst ein Feld wählen. Dein Blatt bringt wenig Punkte. Also soll das Feld wenig zählen, damit ein Verlust nicht wehtut. Welches nimmst du?`,tip:`Schwache Hand: ins Feld mit dem tiefsten Faktor. Die hohen Felder hebst du dir für starke Hände auf.`,options:[s.EICHEL,s.ROSE,s.OBENABE,s.JOKER2],answer:`EICHEL`,wrong:{ROSE:`Rose x2 ginge, aber Eichel mit x1 hast du noch frei. Das ist der geringste Schaden. Nimm das tiefste Feld.`,OBENABE:`Obenabe zählt x5. Mit einem einzigen Ass verlierst du hier fünfmal so viel. Das Feld brauchst du für eine bessere Hand.`,JOKER2:`Joker mit x10? Hmpf. Mit dieser Hand wäre das ein Fiasko. Verlierst du die Runde, verlierst du sie zehnfach.`},fx:{trump:`EICHEL`,badges:[`Eichel · x1`]}},e(`Eichel ist jetzt Trumpf, und weil das Feld nur x1 zählt, kostet dich eine Niederlage fast nichts. Die guten Felder bleiben frei für die guten Hände. Spielen wir trotzdem das Beste daraus.`),{t:`play`,seat:`SUED`,code:`SA`,text:`Du spielst aus. Dein Schellen-Ass ist deine einzige starke Karte. Nimm damit, was geht.`,tip:`Asse spielst du aus, bevor dir ein Gegner die Farbe leer spielt und sie mit Trumpf absticht.`,wrong:{"*":`Spiel dein Schellen-Ass, es ist deine beste Karte.`}},{t:`play`,seat:`OST`,code:`S8`},{t:`play`,seat:`NORD`,code:`S10`,text:`{NORD} ist dein Partner und schmiert dir die Zehn dazu. Er rechnet damit, dass dein Ass durchgeht.`},{t:`play`,seat:`WEST`,code:`S7`},{t:`choose`,text:`Dein Stich bringt 21 Punkte: Ass 11 und Zehn 10. Im Eichel-Feld zählt das 21. Was wäre es gewesen, wenn du diese Hand im Joker 2 (x10) gespielt hättest?`,options:[{id:`P21`,label:`21`},{id:`P210`,label:`210`},{id:`P2100`,label:`2100`}],answer:`P210`,wrong:{P21:`Das ist der Wert im Eichel-Feld mit x1. Joker 2 zählt zehnmal so viel.`,P2100:`Zu viel: mal zehn, nicht mal hundert.`}},{t:`play`,seat:`SUED`,code:`SK`,text:`Du hast den Stich und spielst weiter: der Schellen-König. Das Ass ist weg, also müsste er durchgehen.`},{t:`choose`,text:`{OST} hat keine Schellen mehr. Was darf er jetzt?`,options:[{id:`FREI`,label:`Abwerfen oder mit Trumpf stechen`},{id:`MUSS`,label:`Er muss Schelle bedienen`},{id:`PASS`,label:`Er muss passen`}],answer:`FREI`,wrong:{MUSS:`Schelle bedienen kann er nur, wenn er Schellen hat. Er hat keine mehr.`,PASS:`Passen gibt es im Stich nicht. Jeder muss eine Karte legen.`}},{t:`play`,seat:`OST`,code:`E8`},{t:`play`,seat:`NORD`,code:`S9`},{t:`choose`,text:`Jetzt liegen drei Karten: dein König, die Eichel 8 von {OST} und die Schelle 9 von {NORD}. Welche gewinnt, falls {WEST} nur noch Schellen hat?`,options:[{id:`SK`,label:`Schellen-König`,code:`SK`},{id:`E8`,label:`Eichel 8`,code:`E8`},{id:`S9`,label:`Schellen 9`,code:`S9`}],answer:`E8`,wrong:{SK:`Der König ist stark, aber Eichel ist Trumpf. Trumpf schlägt jede Karte einer anderen Farbe.`,S9:`Die Neun ist die kleinste der drei. Trumpf schlägt sie.`}},{t:`play`,seat:`WEST`,code:`S6`,text:`Da hast du es: Trumpf sticht. Auch die kleine Eichel 8 schlägt dein Schellen-Ass, wenn sie rechtzeitig kommt. Darum spielt man Asse früh.`},{t:`play`,seat:`OST`,code:`EU`,text:`{OST} hat den Stich gewonnen und spielt aus. Mit dem Eichel-Under zieht er den Trumpf, auch deinen.`},{t:`play`,seat:`NORD`,code:`EO`,text:`{NORD} legt nur den Ober zu: 3 Punkte. Die Zehn behält er.`},{t:`play`,seat:`WEST`,code:`EK`},{t:`play`,seat:`SUED`,code:`E6`,text:`Du musst Trumpf bedienen. Gib die Sechs, die ist am wenigsten wert.`,wrong:{E7:`Beide sind wertlos. Spiel hier die Sechs, die Sieben ist im Trumpf immerhin eine Stufe stärker.`}},e(`Du hast diese Hand eher verloren, und das macht nichts. Im Feld Eichel mit x1 kostet dich das fast nichts, im Joker würde es wehtun. Merk dir: Schwache Hand in ein tiefes Feld, starke in ein hohes.`)]},{regionId:`SOLOTHURN_BASEL`,kind:`trick`,title:`Coiffeur`,lesson:`Undenufe: die Kleinen siegen`,ziele:[`Undenufe bei lauter Kleinen wählen`,`Die Punkte bei Undenufe kennen`,`Die tiefste Karte gewinnt`,`Hohe Karten dem Partner zuwerfen`],zielAt:[1,6,11,15],einstieg:`Jetzt stellen wir alles auf den Kopf: Hier gewinnen die Kleinen.`,order:t,score:`teams`,hands:{SUED:`S6 S7 S9 E7 EK L6 L7 L8 L9`,OST:`SU S10 E8 EU RA R7 R8 L10 LU`,NORD:`S8 SO E6 EO R6 R9 RU LO LK`,WEST:`SK SA E9 E10 EA RK R10 RO LA`},steps:[e(`Dritte Hand, und jetzt drehen wir die Rangfolge um. Du hast noch das Feld Undenufe frei, x6. Dort gewinnt nicht die höchste, sondern die tiefste Karte. Die Sechs ist der Chef, das Ass das Schlusslicht.`),{t:`choose`,text:`Schau dein Blatt an: lauter Sechser, Siebner und Achter, nur ein einziger König. Welches Feld passt dazu?`,tip:`Viele tiefe Karten: Undenufe. Viele Asse und Könige: Obenabe.`,options:[s.EICHEL,s.OBENABE,s.UNDENUFE,s.JOKER1],answer:`UNDENUFE`,wrong:{EICHEL:`Eine Hand, die in Undenufe so gut sitzt, steckst du nicht ins kleinste Feld. Da verschenkst du Faktor.`,OBENABE:`Obenabe ist das Gegenteil: Dort gewinnen die hohen Karten, und du hast keine Asse.`,JOKER1:`Ein Joker könnte Undenufe zwar auch spielen, aber Undenufe selber ist noch frei. Sei sparsam, die Joker brauchst du für Blätter, die sonst nirgends hinpassen.`},fx:{trump:`UNDENUFE`,badges:[`Undenufe · x6`]}},e(`Gut. In Undenufe gibt es keinen Trumpf. Es zählt nur die ausgespielte Farbe, und darin gewinnt die tiefste Karte: Sechs vor Sieben vor Acht und so weiter, das Ass zuletzt. Punkte: Die Sechs zählt 11, die Acht 8, die Zehn 10, das Ass nichts.`,`Die Punktewerte sind sonst wie beim Schieber, nur Sechs und Ass tauschen den Platz.`),{t:`play`,seat:`SUED`,code:`S6`,text:`Du spielst aus: die Schellen 6, die höchste Karte der Farbe, kein Mensch kann sie schlagen. Und sie bringt dir 11 Punkte.`},{t:`play`,seat:`OST`,code:`SU`},{t:`play`,seat:`NORD`,code:`S8`},{t:`choose`,text:`{NORD} ist dein Partner und hat die Schelle 8 zugegeben. Wie viele Punkte zählt sie bei Undenufe?`,options:[{id:`P0`,label:`0`},{id:`P8`,label:`8`},{id:`P10`,label:`10`}],answer:`P8`,wrong:{P0:`Beim Schieber wäre die Acht nichts wert. In Obenabe und Undenufe zählt sie aber 8 Punkte.`,P10:`Die Zehn zählt 10, die Acht ein bisschen weniger.`}},{t:`play`,seat:`WEST`,code:`SK`,text:`Der König gibt 4 Punkte dazu. Dein Stich: 25 Punkte.`},{t:`play`,seat:`SUED`,code:`E7`,text:`Du spielst weiter mit einer tiefen Karte: die Eichel 7. Mal sehen, ob jemand eine noch tiefere hat.`},{t:`play`,seat:`OST`,code:`E8`},{t:`play`,seat:`NORD`,code:`E6`},{t:`choose`,text:`Auf dem Tisch liegen Eichel 7 (du), Eichel 8 ({OST}) und Eichel 6 ({NORD}). Welche gewinnt, wenn {WEST} die Eichel 9 zugibt?`,options:[{id:`E7`,label:`Eichel 7`,code:`E7`},{id:`E8`,label:`Eichel 8`,code:`E8`},{id:`E6`,label:`Eichel 6`,code:`E6`}],answer:`E6`,wrong:{E7:`Deine Sieben ist tief, aber es gibt eine noch tiefere.`,E8:`Die Acht ist hier die höchste Karte, nicht die tiefste.`}},{t:`play`,seat:`WEST`,code:`E9`,text:`{NORD} holt den Stich mit der Sechs, das ist dein Team. 19 Punkte, davon 11 für die Sechs und 8 für die Acht von {OST}.`},{t:`play`,seat:`NORD`,code:`R6`,text:`{NORD} hat gewonnen und spielt aus: die Rosen 6, wieder die unschlagbare Karte. Du hast gar keine Rosen mehr.`},{t:`play`,seat:`WEST`,code:`RK`},{t:`play`,seat:`SUED`,code:`EK`,riddle:!0,text:`Du hast keine Rosen und darfst abwerfen, was du willst. Dein Partner gewinnt den Stich sicher. Welche Karte legst du dazu?`,wrong:{S7:`Die Sieben ist eine gute tiefe Karte, die behältst du. Dazu bringt sie dem Partner keinen einzigen Punkt.`,L6:`Die Sechs ist deine beste Karte in Undenufe. Die behältst du.`,L9:`Das bringt dem Partner nichts. Schmier lieber einen König.`,"*":`Dein Partner gewinnt sicher, also schenk ihm Punkte. Wirf die Karte ab, die dir nie einen Stich bringt und trotzdem Punkte zählt: den König.`}},{t:`play`,seat:`OST`,code:`RA`},{t:`info`,text:`Schmieren geht in Undenufe umgekehrt: Du wirfst hohe Karten ab, weil sie nie einen Stich gewinnen, und gibst dem Partner dabei Punkte mit. Dein Team hat jetzt 63 Punkte, mal x6 gibt das 378.`},e(`Merk dir: In Undenufe gewinnt die Tiefste. Tiefe Karten behältst du, hohe wirfst du dem Partner zu. Obenabe und Undenufe sind Spiegelbilder, du musst nur die Rangfolge umdrehen.`)]},{regionId:`SOLOTHURN_BASEL`,kind:`trick`,title:`Coiffeur`,lesson:`Slalom: hoch, tief, hoch, tief`,ziele:[`Slalom für gemischte Blätter`,`Die Startrichtung bestimmen`,`Die Richtung nach jedem Stich`,`Mit der Sechs tief gewinnen`],zielAt:[1,2,8,13],einstieg:`Slalom ist wie Skifahren: einmal links, einmal rechts. Du schaffst das.`,order:t,score:`teams`,hands:{SUED:`EA E6 RA R6 SK S7 L8 L6 LK`,OST:`E8 EK EU R9 R8 S6 SU L7 LU`,NORD:`E10 E7 R10 RU RO S8 S9 SO LO`,WEST:`E9 EO R7 RK SA S10 LA L10 L9`},steps:[e(`Vierte Hand, und jetzt wird es lustig: Slalom, das Feld x7. Wie ein Skifahrer zwischen den Stangen wechselst du bei jedem Stich die Richtung. Einmal gewinnt die höchste Karte, dann die tiefste, dann wieder die höchste. Pass auf, dass du nie vergisst, wo du gerade bist.`),{t:`choose`,text:`Du bist Ansager. Dein Blatt hat die Asse in Eichel und Rose und dazu zwei Sechser. Welches Feld deiner Tafel nimmst du?`,tip:`Slalom passt, wenn du hohe und tiefe Karten mischst: Asse für die Obenabe-Stiche, Sechser für die Undenufe-Stiche.`,options:[s.EICHEL,s.OBENABE,s.SLALOM,s.GUSCHTI],answer:`SLALOM`,wrong:{EICHEL:`Mit einem Blatt, das so gut zum Wechseln passt, steckst du nichts in das kleinste Feld.`,OBENABE:`Obenabe geht mit deinen Sechsern nicht auf. Du hast Asse und Sechser, das ist die Mischung für Slalom.`,GUSCHTI:`Guschti/Mary wechselt nur einmal, nach fünf Stichen. Dein Blatt passt besser zum ständigen Wechsel.`},fx:{badges:[`Slalom · x7`]}},{t:`choose`,text:`Jetzt sagst du, womit Slalom beginnt: Obenabe oder Undenufe. Du spielst im ersten Stich aus. Was passt zu deinem Eichel-Ass?`,tip:`Die Startrichtung gilt für Stich 1, 3, 5, 7 und 9. Und sie bestimmt auch die Punkte der ganzen Runde.`,options:[{id:`OBEN`,label:`Mit Obenabe`},{id:`UNTEN`,label:`Mit Undenufe`}],answer:`OBEN`,wrong:{UNTEN:`Mit Undenufe wäre dein Ass im ersten Stich die schlechteste Karte der Farbe. Beginn mit Obenabe, da zählt es.`},fx:{trump:`SLALOM_OBENABE`,badges:[`Slalom · x7`],bubbles:{SUED:`Slalom!`}}},e(`Gut gewählt. Im ersten Stich gilt Obenabe: Die höchste Karte der ausgespielten Farbe gewinnt. Dann dreht es: Stich 2 ist Undenufe, Stich 3 wieder Obenabe, und immer so weiter. Oben in der Anzeige siehst du, welche Richtung gerade gilt.`,`Trumpf gibt es im Slalom nicht. Es zählt nur die ausgespielte Farbe, und man muss sie bedienen.`),{t:`play`,seat:`SUED`,code:`EA`,text:`Stich 1, Obenabe. Du spielst das Eichel-Ass aus: Höher geht nicht, und es bringt 11 Punkte.`},{t:`play`,seat:`OST`,code:`E8`},{t:`play`,seat:`NORD`,code:`E10`,text:`{NORD} schmiert die Zehn, 10 Punkte für euch. Den Stich holt das Ass.`},{t:`play`,seat:`WEST`,code:`E9`},{t:`choose`,text:`Du hast den Stich geholt und spielst aus. Welche Richtung gilt jetzt?`,options:[{id:`OBENABE`,label:`Obenabe`},{id:`UNDENUFE`,label:`Undenufe`}],answer:`UNDENUFE`,wrong:{OBENABE:`Das war der erste Stich. Nach jedem Stich dreht die Richtung, jetzt gilt also Undenufe: Die tiefste Karte gewinnt.`}},{t:`play`,seat:`SUED`,code:`E6`,riddle:!0,text:`Stich 2, Undenufe. Du hast Eichel 6 und Rose 6 in der Hand. Welche Karte spielst du aus?`,wrong:{R6:`Das geht auch, aber die Eichel 6 ist in Eichel die tiefste Karte und nicht zu schlagen. Spiel sie.`,"*":`Hier gewinnt die tiefste Karte, und die Eichel 6 ist in Eichel nicht zu schlagen. Das Ass wäre jetzt die schlechteste Karte der Farbe.`}},{t:`play`,seat:`OST`,code:`EK`},{t:`play`,seat:`NORD`,code:`E7`},{t:`play`,seat:`WEST`,code:`EO`},{t:`choose`,text:`Du holst den Stich mit der Eichel 6. Wie viele Punkte zählt diese Sechs? Denk daran, was du als Startrichtung angesagt hast.`,tip:`Beim Slalom gilt immer die Punktetabelle der Startrichtung, auch in den Undenufe-Stichen.`,options:[{id:`P0`,label:`0`},{id:`P8`,label:`8`},{id:`P11`,label:`11`}],answer:`P0`,wrong:{P11:`Elf Punkte wäre die Sechs in Undenufe. Du hast aber mit Obenabe angesagt, also zählt die Sechs nichts, auch wenn sie den Stich holt.`,P8:`Acht Punkte bringt die Acht, nicht die Sechs.`}},e(`Eben: 0 Punkte. In diesem Stich zählen nur der König (4) und der Ober (3), zusammen 7. Das merkst du dir für die Coiffeur-Tafel: Welche Karten Punkte bringen, entscheidet der Start, nicht der einzelne Stich.`),{t:`play`,seat:`SUED`,code:`RA`,riddle:!0,text:`Stich 3: Die Richtung ist wieder oben. Du hast Rosen-Ass und Rosen 6, dazu König und Siebner in Schelle. Welche Karte spielst du aus?`,wrong:{R6:`Das wäre die Karte für Undenufe. In diesem Stich gewinnt die höchste, und die Sechs ginge unter.`,"*":`Diesmal gewinnt die höchste Karte. Du hast ein Ass, das nicht zu schlagen ist: das Rosen-Ass.`}},{t:`play`,seat:`OST`,code:`R9`},{t:`play`,seat:`NORD`,code:`R10`,text:`{NORD} schmiert wieder die Zehn. 21 Punkte in diesem Stich.`},{t:`play`,seat:`WEST`,code:`R7`},{t:`play`,seat:`SUED`,code:`R6`,text:`Stich 4, wieder Undenufe, und jetzt hast du noch die Rosen 6. Die tiefste Karte der Farbe: spielen.`,tip:`Auch hier hilft der Spiegel: Obenabe-Stiche mit dem Ass, Undenufe-Stiche mit der Sechs.`,wrong:{"*":`Spiel die Rosen 6, die ist in Undenufe nicht zu schlagen.`}},{t:`play`,seat:`OST`,code:`R8`},{t:`play`,seat:`NORD`,code:`RU`},{t:`play`,seat:`WEST`,code:`RK`},e(`Vier Stiche, vier Mal dein Team, 71 Punkte, mal 7 gibt 497. Das war ein Wunschblatt, in der Wirklichkeit treffen die Asse und Sechser nicht immer so schön. Merk dir: Vor jedem Ausspielen fragst du dich zuerst, welche Richtung jetzt gilt. Dann weisst du, ob du das Ass oder die Sechs bringst.`)]},{regionId:`SOLOTHURN_BASEL`,kind:`trick`,title:`Coiffeur`,lesson:`Guschti: erst hoch, dann tief`,ziele:[`Guschti oder Mary wählen`,`Die fünf Stiche oben zählen`,`Den Richtungswechsel erkennen`,`Mit Sechsern unten gewinnen`],zielAt:[2,9,14,19],einstieg:`Zwei Spiele in einem. Schau, wie die Richtung nach fünf Stichen dreht.`,order:t,score:`teams`,hands:{SUED:`EA E6 RA R6 SA S6 LA LK L6`,OST:`E8 EU EK R9 R8 S8 SU L8 LU`,NORD:`E10 E7 R10 RU S10 S7 SO L10 LO`,WEST:`E9 EO R7 RO RK S9 SK L9 L7`},steps:[e(`Fünfte und letzte Hand: Guschti/Mary, das Feld x8. Zwei Spielarten in einer. Die ersten fünf Stiche gilt die eine Richtung, die letzten vier die andere. Du musst also nicht nur oben oder unten denken, sondern merken, wann es dreht.`),{t:`choose`,text:`Du bist Ansager und hast vier Asse, einen König und vier Sechser. Hohe Karten für den Anfang, tiefe für den Schluss. Welches Feld nimmst du?`,tip:`Guschti/Mary passt zu einem Blatt, das hohe und tiefe Karten hat, aber mit einer klaren Reihenfolge: zuerst die einen, dann die anderen.`,options:[s.OBENABE,s.UNDENUFE,s.SLALOM,s.GUSCHTI],answer:`GUSCHTI`,wrong:{OBENABE:`Mit vier Sechsern in der Hand holst du in Obenabe am Schluss nichts mehr. Dein Blatt kann beides, nimm ein Feld, das beides zählt.`,UNDENUFE:`Deine Asse wären in Undenufe wertlos. Du hast aber Asse und Sechser, und die kommen zu verschiedenen Zeiten.`,SLALOM:`Slalom wechselt nach jedem Stich. Dein Blatt hat aber eine klare Ordnung: erst die Asse, dann die Sechser. Das ist Guschti.`},fx:{badges:[`Guschti/Mary · x8`]}},{t:`choose`,text:`Jetzt musst du sagen, ob Guschti oder Mary. Bei Guschti beginnst du oben (Obenabe), bei Mary unten (Undenufe). Du spielst mit den Assen an. Was nimmst du?`,tip:`Die Startrichtung bestimmt auch die Punkte der ganzen Runde: Guschti zählt nach der Obenabe-Tabelle, Mary nach der Undenufe-Tabelle.`,options:[{id:`GUSCHTI`,label:`Guschti`},{id:`MARY`,label:`Mary`}],answer:`GUSCHTI`,wrong:{MARY:`Mary beginnt mit Undenufe, da wären deine Asse im ersten Stich die schlechtesten Karten. Du willst mit den Assen anfangen, also Guschti.`},fx:{trump:`GUSCHTI`,badges:[`Guschti/Mary · x8`],bubbles:{SUED:`Guschti!`}}},e(`Also Guschti. Stich 1 bis 5 gilt Obenabe, die höchste Karte gewinnt. Stich 6 bis 9 gilt Undenufe, die tiefste Karte gewinnt. Oben in der Anzeige siehst du immer, welche Richtung gerade läuft. Punkte zählen die ganze Runde nach Obenabe: Ass 11, Zehn 10, Acht 8 und die Sechs nichts.`,`Trumpf gibt es nicht. Es zählt nur die ausgespielte Farbe, und man muss sie bedienen.`),{t:`play`,seat:`SUED`,code:`EA`,text:`Stich 1, Obenabe. Du beginnst mit dem Eichel-Ass: nicht zu schlagen, und 11 Punkte.`},{t:`play`,seat:`OST`,code:`E8`},{t:`play`,seat:`NORD`,code:`E10`,text:`{NORD} schmiert die Zehn, 10 Punkte für euch.`},{t:`play`,seat:`WEST`,code:`E9`},{t:`replay`,tricks:[`RA R9 R10 R7`,`SA S8 S10 S9`,`LA L8 L10 L9`],text:`Die nächsten drei Stiche lasse ich im Schnelldurchlauf laufen: Rosen-Ass, Schellen-Ass, Schilten-Ass. Jedes Mal holst du den Stich, und {NORD} schmiert die Zehn dazu. Vier Stiche sind durch.`},{t:`choose`,text:`Vier Stiche sind gespielt. Wie viele Stiche gelten noch in der Richtung Obenabe?`,tip:`Zähl mit: Nach dem fünften Stich dreht Guschti.`,options:[{id:`N1`,label:`Noch einer`},{id:`N2`,label:`Noch zwei`},{id:`N5`,label:`Noch fünf`}],answer:`N1`,wrong:{N2:`Es gelten fünf Stiche Obenabe, vier sind schon vorbei. Es bleibt einer.`,N5:`Die fünf Stiche sind insgesamt, vier sind schon vorbei. Es bleibt einer.`}},{t:`play`,seat:`SUED`,code:`LK`,riddle:!0,text:`Stich 5, der letzte in Richtung Obenabe. Du hast das Schilten-Ass schon gespielt. Welche Karte spielst du aus?`,wrong:{E6:`Die Sechser sparst du für die zweite Hälfte, da werden sie stark. Jetzt gilt noch Obenabe.`,R6:`Die Sechser sparst du für die zweite Hälfte, da werden sie stark. Jetzt gilt noch Obenabe.`,S6:`Die Sechser sparst du für die zweite Hälfte, da werden sie stark. Jetzt gilt noch Obenabe.`,L6:`Die Sechser sparst du für die zweite Hälfte, da werden sie stark. Jetzt gilt noch Obenabe.`,"*":`Mit dem Schilten-Ass ist der König jetzt die höchste Schilte. Spiel ihn aus, solange Obenabe gilt.`}},{t:`play`,seat:`OST`,code:`LU`},{t:`play`,seat:`NORD`,code:`LO`},{t:`play`,seat:`WEST`,code:`L7`},{t:`choose`,text:`Der König hat den Stich geholt, fünf Stiche sind vorbei. Welche Richtung gilt jetzt?`,options:[{id:`OBENABE`,label:`Obenabe`},{id:`UNDENUFE`,label:`Undenufe`}],answer:`UNDENUFE`,wrong:{OBENABE:`Das waren die fünf Stiche in Obenabe-Richtung. Ab dem sechsten Stich gilt Undenufe: Die tiefste Karte gewinnt.`}},{t:`play`,seat:`SUED`,code:`E6`,text:`Jetzt kommen deine Sechser dran. Spiel die Eichel 6: Sie ist die tiefste Karte der Farbe und nicht zu schlagen.`,tip:`Die hohen Karten sind jetzt Ballast, die Sechser Gold. Gut, dass du sie aufgespart hast.`,wrong:{"*":`Spiel die Eichel 6, jetzt gewinnt die tiefste Karte.`}},{t:`play`,seat:`OST`,code:`EU`},{t:`play`,seat:`NORD`,code:`E7`},{t:`play`,seat:`WEST`,code:`EO`},{t:`choose`,text:`Die Eichel 6 hat den Stich geholt. Wie viele Punkte zählt sie bei Guschti?`,tip:`Bei Guschti gilt die Punktetabelle von Obenabe, in allen neun Stichen.`,options:[{id:`P0`,label:`0`},{id:`P8`,label:`8`},{id:`P11`,label:`11`}],answer:`P0`,wrong:{P11:`Elf Punkte wäre die Sechs bei Mary und bei Undenufe. Guschti zählt nach Obenabe, da ist die Sechs nichts wert.`,P8:`Acht Punkte bringt die Acht, nicht die Sechs.`}},{t:`play`,seat:`SUED`,code:`R6`,text:`Und gleich die nächste: die Rosen 6. Alle müssen Rosen bedienen, und keiner kann dich unterbieten.`,wrong:{"*":`Spiel die Rosen 6, sie ist die tiefste Rose und nicht zu schlagen.`}},{t:`play`,seat:`OST`,code:`R8`},{t:`play`,seat:`NORD`,code:`RU`},{t:`play`,seat:`WEST`,code:`RO`},e(`Sieben Stiche, alle für dein Team, 135 Punkte, mal 8. Und zwei Stiche kommen noch. Das war wieder ein Wunschblatt. Merk dir: Bei Guschti zählst du die Stiche mit. Erst die hohen Karten ausspielen, die Sechser aufsparen, und nach dem fünften Stich dreht es. Mary ist das Spiegelbild: zuerst Undenufe, danach Obenabe, und die Punkte zählen nach Undenufe, die Sechs 11 und das Ass nichts.`)]},{regionId:`SOLOTHURN_BASEL`,kind:`trick`,title:`Coiffeur`,lesson:`Misère: bloss keinen Stich`,ziele:[`Misère bei lauter Kleinen wählen`,`Die Richtung wählen`,`Wer sticht, schenkt die Punkte`,`Unter den anderen bleiben`],zielAt:[1,2,7,10],einstieg:`Die Misère ist etwas für Mutige. Hier will niemand einen Stich.`,order:t,score:`teams`,hands:{SUED:`E6 E7 E9 S6 S8 R6 R7 L6 L8`,OST:`EA EK E8 SA S9 R8 RA LA L7`,NORD:`E10 EO SK S7 RK R9 RO LK L9`,WEST:`EU SU SO S10 R10 RU LU LO L10`},steps:[e(`Zum Schluss noch etwas für Mutige: die Misère. Die gibt es nur, wenn ihr sie vor der Partie einschaltet. Dann ersetzt sie den ersten Joker und zählt x9. Gespielt wird wie Obenabe oder Undenufe, aber umgekehrt gedacht: Wer einen Stich macht, schreibt die Punkte dem Gegner. Du willst also möglichst keinen Stich.`),{t:`choose`,text:`Schau dein Blatt an: lauter Sechser, Siebner und Achter, kein Ass, kein Trumpfkern. Welches Feld nimmst du?`,tip:`Eine Hand ohne hohe Karten holt sonst fast nichts. Bei der Misère ist genau das die Stärke.`,options:[s.EICHEL,s.OBENABE,s.UNDENUFE,{id:`MISERE`,label:`Misère`,sub:`x9`}],answer:`MISERE`,wrong:{EICHEL:`Eichel als Trumpf mit Sechs, Sieben und Neun? Da holst du kaum einen Stich. Bei der Misère ist das gerade gut.`,OBENABE:`Obenabe mit diesen Karten bringt fast nichts, du machst kaum einen Stich. Dreh den Spiess um: Misère.`,UNDENUFE:`Für Undenufe fehlen dir die sicheren Sechser-Reihen. Mit so tiefen Karten machst du am besten gar keinen Stich: Misère.`},fx:{badges:[`Misère · x9`]}},{t:`choose`,text:`Misère Obenabe oder Misère Undenufe? Denk daran: Du willst die Stiche verlieren.`,tip:`Bei Misère Obenabe sticht die höchste Karte. Wer tiefe Karten hat, liegt dann immer darunter.`,options:[{id:`OBEN`,label:`Misère Obenabe`},{id:`UNTEN`,label:`Misère Undenufe`}],answer:`OBEN`,wrong:{UNTEN:`Bei Undenufe sticht die tiefste Karte. Mit deinen Sechsern würdest du dann jeden Stich machen. Nimm Obenabe.`},fx:{trump:`MISERE_OBENABE`,badges:[`Misère · x9`],bubbles:{SUED:`Misère!`}}},{t:`play`,seat:`SUED`,code:`E9`,riddle:!0,text:`Du spielst aus. Welche Karte bringst du?`,tip:`Spiel eine Karte, die die anderen noch überbieten können. Die Sechser sind deine sichersten Karten: Heb sie auf, vor allem für den letzten Stich.`,wrong:{E6:`Die Eichel 6 ist ganz sicher, aber genau darum brauchst du sie später. Bring zuerst eine Karte, die andere noch überbieten.`,S6:`Die Sechser sind deine Notausgänge. Heb sie auf und spiel eine höhere Karte, die noch überboten wird.`,R6:`Die Sechser sind deine Notausgänge. Heb sie auf und spiel eine höhere Karte, die noch überboten wird.`,L6:`Die Sechser sind deine Notausgänge. Heb sie auf und spiel eine höhere Karte, die noch überboten wird.`,"*":`Auch gut möglich, aber die Eichel 9 ist hier am geschicktesten: In Eichel liegen noch viele höhere Karten bei den anderen.`}},{t:`play`,seat:`OST`,code:`E8`,text:`{OST} bleibt mit der Acht schlau darunter.`},{t:`play`,seat:`NORD`,code:`E10`,text:`{NORD} hat nur Zehn und Ober und muss drüber.`},{t:`play`,seat:`WEST`,code:`EU`,text:`{WEST} hat nur den Under und muss noch höher. Jetzt hält {WEST} den Stich.`},{t:`choose`,text:`{WEST} hat den Stich gemacht. Wer bekommt die Punkte?`,options:[{id:`WIR`,label:`Dein Team`},{id:`SIE`,label:`Die Gegner`}],answer:`WIR`,wrong:{SIE:`Umgekehrt! Bei der Misère schreibt, wer sticht, die Punkte dem Gegner. {WEST} sticht, also punktet ihr.`}},e(`Genau: 20 Punkte für euch. Die Acht zählt wie bei Obenabe 8, die Zehn 10, der Under 2. Wer sticht, spielt auch wieder aus. Darum kommt jetzt {WEST}.`),{t:`play`,seat:`WEST`,code:`S10`},{t:`play`,seat:`SUED`,code:`S8`,riddle:!0,text:`{WEST} spielt die Schellen-Zehn. Du hast Schelle 6 und 8. Welche legst du?`,tip:`Knapp unter dem Stich bleiben: die höchste Karte, die noch nicht sticht. So wirst du die gefährlicheren Karten los.`,wrong:{S6:`Die Sechs geht auch drunter, aber die Acht ist gefährlicher. Wirf sie jetzt weg, solange sie unter der Zehn bleibt.`}},{t:`play`,seat:`OST`,code:`S9`,text:`{OST} bleibt ebenfalls darunter.`},{t:`play`,seat:`NORD`,code:`S7`},e(`Wieder sticht {WEST}, und 18 Punkte gehen an euch: die Zehn 10 und deine eigene Acht 8. Zusammen schon 38. Merk dir für die Misère: knapp unter dem Stich bleiben, hohe Karten loswerden, solange sie noch jemand überbietet, und eine Sechs für den letzten Stich aufheben. Er bringt 5 Punkte extra, und die willst du dem Gegner lassen. Machst du gar keinen Stich, schreibst du einen Match, 16 auf die Tafel.`)]}],u=[{lesson:`Zwei Stapel`,ziele:[`Einen Stapel aufnehmen`,`Den Trumpf ansagen`,`Die Trümpfe mitzählen`,`Den zweiten Stapel aufnehmen`],zielAt:[1,3,8,15],einstieg:`Zu zweit jasst es sich anders: Jeder hat zwei Stapel. Ich zeig dir den Ablauf.`,regionId:`ZWEIER`,kind:`trick`,title:`Schieber zu zweit`,order:[`SUED`,`NORD`],score:`duel`,blind:!0,hands:{SUED:`LU L9 LA L10 EA EK R7 S6 S7`,NORD:`L7 L6 E6 E8 RA R9 R10 SK S9`},stacks:{SUED:`LO E9 E10 EU EO R6 R8 RU RO`,NORD:`LK L8 E7 S8 S10 SU SO SA RK`},steps:[e(`Nu, Schieber zu zweit. Du spielst allein gegen {NORD}, jeder schreibt seine Punkte selbst auf. {NORD} ist Geber und hat jedem zwei verdeckte Stapel zu neun Karten hingelegt – so sind alle 36 Karten verteilt.`,`Gestochen wird wie beim Schieber: Farbe bedienen, Trumpf sticht, der höchste Trumpf ist der Under (Buur).`),{t:`stack`,seat:`SUED`,text:`Du bist der Gegenspieler des Gebers und nimmst zuerst einen deiner beiden Stapel auf. Sie liegen verdeckt, du wählst blind. Tipp einen an!`,tip:`Den anderen Stapel lässt du liegen. Er kommt erst nach dem 9. Stich dazu.`},{t:`stack`,seat:`NORD`,text:`Jetzt nimmt auch {NORD} einen seiner Stapel auf. Hier siehst du seine Karten offen, am Spieltisch natürlich nicht.`},{t:`choose`,text:`Als Gegenspieler des Gebers sagst du den Trumpf an. Schieben gibt es nicht, du hast ja keinen Partner. Deine Schilten mit Under, Nell, Ass und Zehn sind stark. Was sagst du an?`,tip:`Der Trumpf gilt für beide Stapel. Den zweiten kennst du noch nicht – sag an, was dein erster Stapel hergibt.`,options:r,answer:`SCHILTE`,wrong:{EICHEL:`Mit Ass und König ist Eichel gut, aber zu kurz für einen Trumpf. Deine Schilten mit Under und Nell sind viel stärker.`,ROSE:`Du hast nur die Rosen 7. Sag Schilte an – dort hast du Under, Nell, Ass und Zehn.`,SCHELLE:`Mit Schellen 7 und 6 ist Schelle kein Trumpf. Sag Schilte an.`,OBENABE:`Für Obenabe hast du zu wenig Asse und Könige. Sag Schilte an.`,UNDENUFE:`Für Undenufe fehlen dir die tiefen Karten. Sag Schilte an.`},fx:{trump:`SCHILTE`,bubbles:{SUED:`Schilte!`}}},{t:`play`,seat:`SUED`,code:`LU`,text:`Wer ansagt, spielt auch aus. Beginn mit dem Buur, dem Schilten-Under: Er ist die höchste Karte und holt die Trümpfe von {NORD}.`,tip:`Zu zweit hält {NORD} alle Karten, die du nicht hast. Hol seine Trümpfe früh heraus.`,wrong:{"*":`Spiel zuerst den Buur, den Schilten-Under.`},fx:{bubbles:{}}},{t:`play`,seat:`NORD`,code:`L7`,text:`Trumpf wurde ausgespielt: {NORD} muss Schilte bedienen. Ein Stich hat hier nur zwei Karten.`},{t:`play`,seat:`SUED`,code:`L9`,text:`Du hast den Stich gewonnen und spielst wieder aus. Jetzt der Nell, die Schilten 9 – der zweithöchste Trumpf.`,wrong:{"*":`Spiel den Nell (Schilten 9): So holst du den letzten Trumpf von {NORD}.`}},{t:`play`,seat:`NORD`,code:`L6`,text:`{NORD} gibt seinen letzten Trumpf ab. In seinem ersten Stapel hat er jetzt keinen mehr.`},{t:`choose`,text:`Zählen zahlt sich aus. Es gibt neun Schilten, und vier davon sind gespielt: Buur, Nell, Sieben und Sechs. Wie viele Trümpfe sind noch im Spiel?`,tip:`Du siehst deine Karten und die von {NORD}, aber nicht die zweiten Stapel – zähl, was weg ist.`,options:[{id:`DREI`,label:`3 Trümpfe`},{id:`FUENF`,label:`5 Trümpfe`},{id:`SIEBEN`,label:`7 Trümpfe`}],answer:`FUENF`,wrong:{DREI:`Das wären zu wenige. Neun Schilten, vier sind weg: Fünf sind noch im Spiel, zwei davon in deiner Hand.`,SIEBEN:`Zu viele. Neun Schilten, vier sind weg: Fünf sind noch im Spiel.`}},{t:`play`,seat:`SUED`,code:`EA`,text:`{NORD} hat in diesem Stapel keinen Trumpf mehr: Dein Eichel-Ass ist ein sicherer Stich.`,tip:`Hat der Gegner keinen Trumpf mehr, sind deine Asse sicher.`,wrong:{"*":`Spiel jetzt das Eichel-Ass – {NORD} kann es nicht mehr stechen.`}},{t:`play`,seat:`NORD`,code:`E6`},{t:`replay`,tricks:[`EK E8`,`R7 RA`,`R10 L10`,`LA R9`,`S6 SK`],text:`Die nächsten fünf Stiche im Schnelldurchlauf: Du holst den Eichel-König, {NORD} das Rosen-Ass. Auf seine Rosen 10 stichst du mit der Schilten 10, mit dem Schilten-Ass holst du die Rosen 9. Mit der Schellen 6 gibst du {NORD} den Stich ab.`},{t:`play`,seat:`NORD`,code:`S9`,text:`Der 9. Stich – der letzte des ersten Stapels. {NORD} spielt aus.`},{t:`play`,seat:`SUED`,code:`S7`,text:`Du hast nur noch die Schellen 7. Spiel sie.`,wrong:{"*":`Spiel deine letzte Karte, die Schellen 7.`}},{t:`choose`,text:`Der erste Stapel ist gespielt, die Hände sind leer. Wann nimmst du den zweiten Stapel auf?`,tip:`Der Trumpf bleibt der gleiche, und wer den 9. Stich gemacht hat, spielt den 10. aus.`,options:[{id:`SOFORT`,label:`Sofort, schon mitten im ersten Stapel`},{id:`NACH9`,label:`Nach dem 9. Stich, wenn die Hand leer ist`},{id:`NACH18`,label:`Erst nach dem 18. Stich`}],answer:`NACH9`,wrong:{SOFORT:`Nein. Zuerst spielst du den ersten Stapel ganz aus, dann kommt der zweite.`,NACH18:`Nach dem 18. Stich ist die Hand vorbei. Der zweite Stapel kommt nach dem 9. Stich dazu.`}},{t:`stack`,seat:`SUED`,text:`Tipp deinen zweiten Stapel an!`,tip:`Der Trumpf bleibt Schilte. Wer den 9. Stich gemacht hat, spielt den 10. aus – hier ist das {NORD}.`},{t:`stack`,seat:`NORD`},{t:`play`,seat:`NORD`,code:`SA`,text:`{NORD} hat den 9. Stich gemacht und spielt das Schellen-Ass aus. Dein zweiter Stapel hat keine Schellen – aber einen Trumpf!`},{t:`play`,seat:`SUED`,code:`LO`,riddle:!0,text:`Das Schellen-Ass liegt. Du hast keine Schellen. Welche Karte spielst du?`,tip:`Kannst du nicht bedienen, darfst du mit Trumpf stechen – auch ein Ass.`,wrong:{"*":`Das ist erlaubt, aber {NORD} holt den Stich mit dem Ass. Stich mit deinem Trumpf, dem Schilten-Ober.`}},e(`Gut gespielt. So geht es weiter bis zum 18. Stich. Der letzte Stich zählt 5 Punkte extra, wer alle 18 Stiche macht, bekommt 100 Punkte (Match) – eine Hand hat 157 Punkte. Danach wechselt der Geber. Wer zuerst die Zielpunktzahl (250, 500 oder 1000) erreicht, beendet die Partie: Gewonnen hat, wer dann mehr Punkte hat.`)]},{lesson:`Mitzählen`,ziele:[`Trumpf mit starken Karten ansagen`,`Die Trümpfe mitzählen`,`Ein sicheres Ass erkennen`],zielAt:[3,8,11],einstieg:`Zu zweit kannst du fast alles mitzählen. Probier es einfach aus.`,regionId:`ZWEIER`,kind:`trick`,title:`Schieber zu zweit`,order:[`SUED`,`NORD`],score:`duel`,blind:!0,hands:{SUED:`EU E9 EA E6 SA SK R7 R8 L10`,NORD:`E10 EO E8 S9 RA RK R9 L8 LK`},stacks:{SUED:`E7 S10 SU SO R10 RU L9 LU LO`,NORD:`EK S6 S7 S8 R6 RO L6 L7 LA`},steps:[e(`Zweite Hand zu zweit: Mitzählen. Es gibt nur neun Karten in einer Farbe, und weil {NORD} und du zusammen alle 36 Karten haben, weisst du immer ziemlich genau, was noch draussen ist.`,`Wer mitzählt, weiss, wann ein Ass sicher ist.`),{t:`stack`,seat:`SUED`,text:`Nimm einen deiner beiden Stapel auf. Den anderen kennst du erst nach dem 9. Stich.`},{t:`stack`,seat:`NORD`},{t:`choose`,text:`Dein Stapel: Eichel-Under, Nell und Ass, dazu die Sechs. Vier Eicheln, drei davon ganz oben. Was sagst du an?`,tip:`Mit Buur und Nell in der Farbe bist du fast immer richtig.`,options:r,answer:`EICHEL`,wrong:{SCHELLE:`Ass und König der Schellen sind nicht schlecht, aber die Eichel mit Buur und Nell sticht viel mehr.`,ROSE:`In den Rosen hast du die Sieben und die Acht. Das trägt nicht.`,SCHILTE:`Nur die Schilten 10. Sag Eichel an.`,OBENABE:`Für Obenabe hast du zu wenig Asse. Deine Stärke liegt im Trumpf, sag Eichel an.`,UNDENUFE:`Für Undenufe fehlen dir die tiefen Karten. Sag Eichel an.`},fx:{trump:`EICHEL`,bubbles:{SUED:`Eichel!`}}},{t:`play`,seat:`SUED`,code:`EU`,riddle:!0,text:`Du sagst an und spielst aus. Welche Karte spielst du?`,wrong:{E9:`Der Nell ist gut, aber der Buur ist besser. Die höchste Karte zuerst: Sie holt die gegnerischen Trümpfe heraus.`,EA:`Das Ass ist ein guter Trumpf, aber Buur und Nell sind stärker. Die holst du zuerst, solange {NORD} noch Trümpfe hat.`,"*":`Fang mit dem Trumpf an, und zwar mit dem höchsten: dem Buur.`},fx:{bubbles:{}}},{t:`play`,seat:`NORD`,code:`E8`,text:`{NORD} muss Eichel bedienen und gibt die Acht zu.`},{t:`play`,seat:`SUED`,code:`E9`,text:`Jetzt der Nell, der zweithöchste Trumpf.`,wrong:{"*":`Spiel den Nell, die Eichel 9.`}},{t:`play`,seat:`NORD`,code:`EO`,text:`{NORD} gibt den Ober zu. Er hätte auch die Zehn, aber die hebt er auf.`},{t:`choose`,text:`Zählen lohnt sich. Es gibt neun Eicheln, und vier sind gespielt: Buur, Nell, Acht und Ober. Wie viele Eicheln sind noch im Spiel?`,tip:`Neun minus vier. In deinem Stapel und bei {NORD} steckt davon noch einiges.`,options:[{id:`DREI`,label:`3 Eicheln`},{id:`FUENF`,label:`5 Eicheln`},{id:`SIEBEN`,label:`7 Eicheln`}],answer:`FUENF`,wrong:{DREI:`Das wären zu wenige. Neun Eicheln, vier sind weg: Fünf sind noch im Spiel.`,SIEBEN:`Zu viele. Neun Eicheln, vier sind weg: Fünf sind noch im Spiel: drei siehst du offen, zwei stecken in den verdeckten Stapeln.`}},{t:`play`,seat:`SUED`,code:`EA`,text:`Und jetzt dein Ass. {NORD} hat in diesem Stapel nur noch die Zehn, er kann es also nicht stechen.`,wrong:{"*":`Spiel das Eichel-Ass.`}},{t:`play`,seat:`NORD`,code:`E10`,text:`{NORD} muss die Zehn zugeben, Farbzwang: 21 Punkte für dich. Jetzt hat er in diesem Stapel keinen Trumpf mehr.`},{t:`play`,seat:`SUED`,code:`SA`,riddle:!0,text:`{NORD} hat in diesem Stapel keinen Trumpf mehr. Du spielst aus. Welche Karte?`,wrong:{SK:`Der König gewinnt auch, aber das Ass zuerst: Es holt den Stich und zeigt dir, was {NORD} an Schellen hat.`,E6:`Das ist dein letzter Trumpf im ersten Stapel. Heb ihn auf, er kann dir später den Stich retten.`,R7:`{NORD} hat das Rosen-Ass und den König. Mit einer Sieben verlierst du den Stich.`,R8:`{NORD} hat das Rosen-Ass und den König. Mit einer Acht verlierst du den Stich.`,L10:`{NORD} hat den Schilten-König und holt deine Zehn damit. Spiel dein Ass.`,"*":`Spiel das Schellen-Ass: Es ist sicher, weil {NORD} keinen Trumpf mehr hat.`}},{t:`play`,seat:`NORD`,code:`S9`},{t:`play`,seat:`SUED`,code:`SK`,text:`Und der König, jetzt die höchste Schelle.`,wrong:{"*":`Spiel den Schellen-König.`}},{t:`play`,seat:`NORD`,code:`L8`,text:`{NORD} hat weder Schelle noch Trumpf und kann nur abwerfen. Siehst du? Weil du den Trumpf zuerst gezogen hast, sind deine Asse jetzt sicher.`},e(`Die Hand geht noch weiter, aber du hast gesehen, worum es geht. Zähl mit: Neun Karten je Farbe, und was weg ist, kommt nicht wieder. Wer weiss, dass der Gegner keinen Trumpf mehr hat, spielt seine Asse ohne Angst.`,`Zuerst die Trümpfe herausholen, dann die Asse.`)]},{lesson:`Obenabe zu zweit`,ziele:[`Obenabe zu zweit ansagen`,`Die Asse mitzählen`,`Die Stichpunkte rechnen`,`Nur dort ausspielen, wo du sicher bist`],zielAt:[3,4,5,12],einstieg:`Ohne Trumpf, nur du und ein Gegner. Das ist ein ruhiges Spiel.`,regionId:`ZWEIER`,kind:`trick`,title:`Schieber zu zweit`,order:[`SUED`,`NORD`],score:`duel`,blind:!0,hands:{SUED:`EA EK EO RA R10 S8 S7 L6 L7`,NORD:`E10 E8 SA SK R9 RK L9 LA LK`},stacks:{SUED:`E6 E9 S6 S10 SO R6 R8 L8 LU`,NORD:`E7 EU S9 SU R7 RU RO L10 LO`},steps:[e(`Dritte Hand zu zweit: Obenabe. Ohne Trumpf zählt nur, wer in der Farbe die höchste Karte hat. Zu zweit bedeutet das: Du musst wissen, wo die Asse liegen.`,`Obenabe: Ass, König, Ober, Under, Zehn bis Sechs. Wer nicht bedienen kann, wirft ab.`),{t:`stack`,seat:`SUED`,text:`Nimm einen deiner beiden Stapel auf, Bub.`},{t:`stack`,seat:`NORD`},{t:`choose`,text:`Dein Stapel: Eichel-Ass, -König und -Ober, dazu das Rosen-Ass. Aber nur dieser eine Stapel – den zweiten kennst du noch nicht. Was sagst du an?`,tip:`Der Trumpf gilt für beide Stapel. Auch hier sagt man an, was der erste Stapel hergibt.`,options:r,answer:`OBENABE`,wrong:{EICHEL:`Ohne Under und Nell trägt Eichel als Trumpf nicht. Ass, König und Ober zählen im Obenabe voll.`,SCHELLE:`Du hast nur die Schellen 8 und 7. Das trägt nicht.`,ROSE:`Rosen-Ass und Zehn, mehr nicht. Sag Obenabe an.`,SCHILTE:`Du hast nur die Schilten 6 und 7. Sag Obenabe an.`,UNDENUFE:`Undenufe ist für tiefe Karten, du hast hohe. Sag Obenabe an.`},fx:{trump:`OBENABE`,bubbles:{SUED:`Obenabe!`}}},{t:`choose`,text:`Zählen hilft. Es gibt vier Asse. Du siehst dein Eichel-Ass und dein Rosen-Ass, und {NORD} hat das Schellen-Ass und das Schilten-Ass. Wie viele Asse stecken noch in den verdeckten zweiten Stapeln?`,tip:`Vier Asse, vier sichtbar.`,options:[{id:`NULL`,label:`Kein einziges`},{id:`ZWEI`,label:`Zwei`},{id:`VIER`,label:`Alle vier`}],answer:`NULL`,wrong:{ZWEI:`Vier Asse gibt es, und vier siehst du schon: zwei bei dir, zwei bei {NORD}.`,VIER:`Die vier Asse siehst du schon: zwei bei dir, zwei bei {NORD}. Im zweiten Stapel steckt keines mehr.`}},{t:`choose`,text:`Du spielst gleich das Eichel-Ass aus. {NORD} hat in der Eichel die Zehn und die Acht. Wie viele Punkte bringt dir der Stich, wenn er die Acht zugibt?`,tip:`Im Obenabe zählt die Acht 8 Punkte, das Ass 11.`,options:[{id:`ELF`,label:`11 Punkte`},{id:`NEUNZEHN`,label:`19 Punkte`},{id:`EINUNDZWANZIG`,label:`21 Punkte`}],answer:`NEUNZEHN`,wrong:{ELF:`Das Ass allein zählt 11, aber {NORD} gibt noch eine Karte dazu, und im Obenabe zählt die Acht 8 Punkte. 11 und 8 sind 19.`,EINUNDZWANZIG:`21 wären es mit der Zehn. Bei der Acht sind es 11 und 8, also 19.`}},{t:`play`,seat:`SUED`,code:`EA`,text:`Spiel das Eichel-Ass aus. Es kann dir niemand nehmen.`,wrong:{"*":`Spiel das Eichel-Ass.`},fx:{bubbles:{}}},{t:`play`,seat:`NORD`,code:`E8`,text:`{NORD} gibt die Acht zu: 19 Punkte für dich.`},{t:`play`,seat:`SUED`,code:`EK`,text:`Das Ass ist weg, jetzt ist der König die höchste Eichel.`,wrong:{"*":`Spiel den Eichel-König.`}},{t:`play`,seat:`NORD`,code:`E10`,text:`{NORD} hat nur noch die Zehn und muss sie zugeben, Farbzwang: 14 Punkte für dich.`},{t:`play`,seat:`SUED`,code:`EO`,text:`Jetzt der Ober, die letzte hohe Eichel in dieser Hand.`,wrong:{"*":`Spiel den Eichel-Ober.`}},{t:`play`,seat:`NORD`,code:`L9`,text:`{NORD} hat keine Eichel mehr und kann nicht stechen, es gibt ja keinen Trumpf. Er wirft die Schilten 9 ab.`},{t:`play`,seat:`SUED`,code:`RA`,riddle:!0,text:`Du hast wieder gewonnen und spielst aus. Dir bleiben Schellen, Rosen und Schilten. Welche Karte ist ein sicherer Stich?`,wrong:{S8:`{NORD} hat das Schellen-Ass und den König. Mit einer Acht verlierst du den Stich.`,S7:`{NORD} hat das Schellen-Ass und den König. Mit einer Sieben verlierst du den Stich.`,R10:`{NORD} hat den Rosen-König und holt deine Zehn. Spiel zuerst dein Ass.`,L6:`{NORD} hat das Schilten-Ass und den König. Mit einer Sechs verlierst du den Stich.`,L7:`{NORD} hat das Schilten-Ass und den König. Mit einer Sieben verlierst du den Stich.`,"*":`Spiel die Karte, die {NORD} nicht schlagen kann: das Rosen-Ass.`}},{t:`play`,seat:`NORD`,code:`R9`},e(`Die Hand geht noch weiter. Merk dir: In Obenabe spielst du nur dort aus, wo du sicher bist. Das Ass und was darunter noch das Höchste ist, bringt den Stich. Eine Zehn gegen einen König verliert, zähl also immer, was der andere hält.`,`Zähl die Asse, bevor du ausspielst.`)]}],d=[`SUED`,`NORD`,`WEST`],f=[{regionId:`AARAU`,kind:`trick`,title:`Bieter`,lesson:`Bieten und König werden`,ziele:[`Bieten und König werden`,`Talon aufnehmen und ablegen`,`Trumpf ansagen, Trümpfe ziehen`],zielAt:[3,5,13],einstieg:`Zu dritt wird es spannend. Komm, ich zeig dir, wie man König wird.`,order:d,score:`king`,target:620,hands:{SUED:`RU RA RO R6 EA EK S10 S8 L10 L7`,NORD:`EU E9 E7 SA SK SO R10 R7 LA LK`,WEST:`E10 E8 E6 SU S9 S6 R8 LO LU L9`},talon:`R9 RK EO S7 L8 L6`,steps:[e(`Nu, dann schau dir das an. Bieter jasst man zu dritt. Zuerst wird geboten: Wer am höchsten bietet, wird König und spielt allein gegen die beiden Bauern. Jeder hat 10 Karten, sechs weitere liegen als Talon in der Mitte. Hier siehst du ihn offen, am echten Tisch kennt ihn keiner.`,`Gespielt wird im Kreis: Du, dann {NORD}, dann {WEST}.`),{t:`choose`,text:`Du bietest zuerst. Das Mindestgebot ist 600 Punkte, dann geht es in 10er-Schritten. Du hast viele Rosen, und im Talon liegen der Nell und der König dazu. Bieten lohnt sich. Wie viel?`,tip:`Gebote sind Zielpunktzahlen: Als König musst du sie erreichen, bevor die Bauern 1000 Punkte haben.`,options:[{id:`B600`,label:`Bieten 600`},{id:`B700`,label:`Bieten 700`},{id:`FORT`,label:`Fort`}],answer:`B600`,wrong:{B700:`Fang mit dem Mindestgebot an: 600. Höher kannst du immer noch gehen.`,FORT:`Mit so einer Hand und diesem Talon steigst du nicht aus. Biete 600.`},fx:{badges:[`Gebot: 600`],bubbles:{SUED:`600`,NORD:`610`,WEST:`Fort`}}},{t:`choose`,text:`{NORD} hat auf 610 erhöht, {WEST} steigt aus («Fort»). Jetzt bist du wieder dran: überbieten oder aussteigen. Dein Blatt mit dem Talon ist stark. Wie weiter?`,tip:`Wer aussteigt, darf nicht mehr mitbieten. Es bleibt nur einer übrig: der König.`,options:[{id:`B620`,label:`Bieten 620`},{id:`FORT`,label:`Fort`}],answer:`B620`,wrong:{FORT:`Steig nicht aus: Mit dem Talon wird dein Blatt sehr stark.`},fx:{badges:[`Gebot: 620`],bubbles:{NORD:`Fort`}}},{t:`choose`,text:`{NORD} steigt aus, du bist König mit 620. Das ist deine Zielpunktzahl. Nimm den Talon auf.`,options:[{id:`TALON`,label:`Talon aufnehmen`}],answer:`TALON`,fx:{badges:[`König · Ziel 620`],takeTalon:!0}},{t:`choose`,text:`Jetzt hast du 16 Karten in der Hand. Wie viele musst du ablegen, damit du wieder bei 10 bist?`,options:[{id:`N3`,label:`3`},{id:`N6`,label:`6`},{id:`N10`,label:`10`}],answer:`N6`,wrong:{N3:`16 minus 3 sind 13. Du brauchst am Ende wieder 10 Karten.`,N10:`Dann bliebe dir nichts mehr. 16 minus 10 sind sechs: So viele legst du ab.`}},{t:`pick`,cards:`S10 S8 S7 L8 L7 L6`,text:`Behalte deine Rosen, die Eichel-Karten und die Schilte 10. Lege die Schellen 10, 8 und 7 sowie die Schilten 8, 7 und 6 ab. Tippe diese sechs Karten an.`,tip:`Lege ganze Farben ab, die du nicht brauchst. So kannst du später in diesen Farben stechen.`,wrong:{"*":`Diese Karte behältst du besser. Lege die markierten Karten ab (Schelle 10, 8, 7 und Schilte 8, 7, 6).`}},{t:`choose`,text:`Jetzt sagst du den Trumpf an. Du hast Rosen mit Under, Nell, Ass, König, Ober und Sechs. Welche Farbe?`,options:r,answer:`ROSE`,wrong:{"*":`Deine Rosen mit Under, Nell, Ass, König, Ober und Sechs sind unschlagbar. Sag Rose an.`},fx:{trump:`ROSE`,badges:[`König · Ziel 620`,`Trumpf Rose`],bubbles:{SUED:`Rose!`}}},{t:`play`,seat:`SUED`,code:`RU`,riddle:!0,text:`Du spielst aus. Die beiden Bauern spielen zusammen gegen dich. Welche Karte?`,wrong:{R9:`Auch Trumpf, aber der Nell steht hinter dem Under. Fang mit der stärksten an.`,RA:`Das Ass ist stark, aber im Trumpf stehen Under und Nell darüber. Die stärkste zuerst.`,EA:`Noch nicht, die Bauern haben Rosen und könnten dein Ass abstechen. Zieh zuerst die Trümpfe.`,"*":`Spiel die stärkste Rose, den Buur.`}},{t:`play`,seat:`NORD`,code:`R10`},{t:`play`,seat:`WEST`,code:`R8`},{t:`play`,seat:`SUED`,code:`R9`,riddle:!0,text:`Der Buur ist durch, du spielst wieder aus. Welche Karte?`,wrong:{RA:`Der Nell steht im Trumpf höher als das Ass. Spiel ihn zuerst.`,RK:`Der König ist kleiner als Nell und Ass. Nimm die stärkste Trumpfkarte.`,EA:`Noch nicht, erst die Trümpfe der Bauern ziehen.`,"*":`Zieh weiter Trumpf, mit der stärksten Karte.`}},{t:`play`,seat:`NORD`,code:`R7`},{t:`play`,seat:`WEST`,code:`S6`,text:`{WEST} hat keine Rosen mehr und darf abwerfen.`},{t:`play`,seat:`SUED`,code:`EA`,text:`Die Bauern haben keine Trümpfe mehr. Dein Eichel-Ass ist ein sicherer Stich.`,wrong:{"*":`Spiel das Eichel-Ass.`}},{t:`play`,seat:`NORD`,code:`E7`},{t:`play`,seat:`WEST`,code:`E6`},{t:`choose`,text:`Dein Ziel sind 620 Punkte. In einer Hand sind 157 Punkte zu holen. Etwa wie viele Hände musst du also spielen?`,options:[{id:`H1`,label:`Eine`},{id:`H4`,label:`Etwa vier`},{id:`H10`,label:`Zehn`}],answer:`H4`,wrong:{H1:`Eine Hand hat nur 157 Punkte. Für 620 brauchst du mehr.`,H10:`So lange nicht. 620 geteilt durch 157 sind knapp vier.`}},e(`Gut gemacht. Als König erreichst du dein Gebot, bevor die Bauern 1000 Punkte haben, in mehreren Händen hintereinander. Ein Match (alle Stiche) und der Bergpreis (als Erster die Hälfte des Ziels) bringen Zusatzpunkte. Merk dir: Biete nur so hoch, wie du es schaffst.`)]},{regionId:`AARAU`,kind:`trick`,title:`Bieter`,lesson:`Der Talon dreht das Blatt`,ziele:[`Den Talon ins Blatt einbauen`,`Sechs Karten richtig ablegen`,`Die Trumpffarbe neu wählen`,`Trümpfe ziehen, dann Asse spielen`],zielAt:[3,4,5,15],einstieg:`Der Talon kann alles ändern. Schau einfach mal, was er bringt.`,order:d,score:`king`,target:600,hands:{SUED:`EA EK EO E9 E7 S8 S7 S6 R10 L10`,NORD:`E10 EU S10 SK RA RK R8 LA LK L6`,WEST:`E6 E8 SO R6 R7 RU RO L9 LU LO`},talon:`SU S9 SA R9 L8 L7`,steps:[e(`Zweite Hand. Diesmal zeig ich dir, was der Talon alles anrichten kann. Schau zuerst auf deine zehn Karten, dann auf die sechs in der Mitte. Beides zusammen entscheidet.`),{t:`choose`,text:`Du bietest zuerst. In deinen Karten sehe ich Eichel mit Ass, König und Ober, sonst nur Kleinkram. Das wäre nicht viel. Aber im Talon liegen Buur, Nell und Ass der Schellen, und du hast schon drei Schellen. Wie fängst du an?`,options:[{id:`B600`,label:`Bieten 600`},{id:`B700`,label:`Bieten 700`},{id:`FORT`,label:`Fort`}],answer:`B600`,wrong:{B700:`Zu hoch für den Anfang. Fang mit dem Mindestgebot an: 600.`,FORT:`Ohne den Talon wäre Fort richtig. Aber schau, was dort liegt: Buur, Nell und Ass einer Farbe, in der du schon Karten hast. Bleib dabei.`},fx:{badges:[`Gebot: 600`],bubbles:{SUED:`600`,NORD:`Fort`,WEST:`Fort`}}},{t:`choose`,text:`{NORD} und {WEST} steigen aus. Du bist König mit 600. Nimm den Talon auf.`,options:[{id:`TALON`,label:`Talon aufnehmen`}],answer:`TALON`,fx:{badges:[`König · Ziel 600`],takeTalon:!0}},{t:`choose`,text:`Zähl deine Schellen: Wie viele hast du jetzt in der Hand?`,options:[{id:`N3`,label:`3`},{id:`N6`,label:`6`},{id:`N9`,label:`9`}],answer:`N6`,wrong:{N3:`Vorher waren es drei. Aber der Talon hat dir Under, Nell und Ass dazugegeben: Das macht sechs.`,N9:`Mehr als sechs wären zu viel: drei von vorher plus drei aus dem Talon.`}},{t:`pick`,cards:`E7 R10 R9 L10 L8 L7`,text:`Jetzt musst du sechs Karten ablegen. Behalte alle sechs Schellen und dazu Eichel-Ass, -König, -Ober und -9. Lege ab: Eichel 7, Rosen 10 und 9, Schilten 10, 8 und 7.`,tip:`Lege ab, was dir als Trumpf-Spieler nichts bringt: kleine Karten und Farben, in denen du nichts holst.`,wrong:{"*":`Die brauchst du noch. Lege ab: Eichel 7, Rosen 10 und 9, Schilten 10, 8 und 7.`}},{t:`choose`,text:`Und jetzt der Trumpf. Vorher hättest du wahrscheinlich Eichel genommen, mit Ass, König und Ober. Was sagst du jetzt an?`,options:r,answer:`SCHELLE`,wrong:{EICHEL:`Eichel hat Ass, König, Ober, aber weder Under noch Nell. Die Schellen haben jetzt beides plus das Ass.`,"*":`Zähl nach: Die Schellen haben Under, Nell und Ass. Das schlägt jede andere Farbe.`},fx:{trump:`SCHELLE`,badges:[`König · Ziel 600`,`Trumpf Schelle`],bubbles:{SUED:`Schelle!`}}},{t:`play`,seat:`SUED`,code:`SU`,text:`Du spielst aus, mit dem Buur. Jetzt müssen die Bauern ihre Trümpfe zugeben.`},{t:`play`,seat:`NORD`,code:`S10`,text:`{NORD} muss Schelle bedienen und gibt die Zehn zu.`},{t:`play`,seat:`WEST`,code:`SO`},{t:`play`,seat:`SUED`,code:`S9`,text:`Jetzt der Nell. {NORD} hat noch einen letzten Trumpf, {WEST} keinen mehr.`},{t:`play`,seat:`NORD`,code:`SK`},{t:`play`,seat:`WEST`,code:`L9`,text:`{WEST} hat keine Schellen mehr und wirft eine Schilte ab.`},{t:`choose`,text:`Zähl mit: Wie viele Trümpfe haben die Bauern jetzt noch?`,options:[{id:`T0`,label:`Keinen`},{id:`T1`,label:`Einen`},{id:`T2`,label:`Zwei`}],answer:`T0`,wrong:{T1:`Die Bauern hatten drei Schellen, S10, König und Ober. Alle drei sind schon gefallen.`,T2:`Es waren nur drei Schellen bei den Bauern, und alle liegen schon im Stich.`}},{t:`play`,seat:`SUED`,code:`EA`,text:`Die Bauern können nicht mehr stechen. Jetzt gehören dir die Asse.`,wrong:{"*":`Spiel das Eichel-Ass, es ist jetzt ein sicherer Stich.`}},{t:`play`,seat:`NORD`,code:`E10`},{t:`play`,seat:`WEST`,code:`E8`},e(`So fängt man den Talon ein. Merk dir: Schau den Talon an, bevor du die Farbe wählst. Er kann die Rangordnung deiner Farben auf den Kopf stellen. Und lege ganze Farben ab, die du nicht brauchst.`)]},{regionId:`AARAU`,kind:`trick`,title:`Bieter`,lesson:`Die Bauern halten zusammen`,ziele:[`Die Bauern verstehen`,`Eine Farbe leer ablegen`,`Einen starken Trumpf wählen`,`Mit der leeren Farbe stechen`],zielAt:[3,6,7,17],einstieg:`Jetzt lernst du die andere Seite kennen: die Bauern. Keine Hast.`,order:d,score:`king`,target:630,hands:{SUED:`LU L9 L7 EK EO E7 SK SO R8 R7`,NORD:`L6 LA EA E9 EU RA RK SA S6 SU`,WEST:`LO LK L10 E10 E6 RU RO R10 S10 S8`},talon:`R9 R6 L8 S9 E8 S7`,steps:[e(`Dritte Hand. Diesmal geht es um die Bauern. Sie sind zu zweit, und sie halten zusammen. Wenn du das weisst, spielst du als König viel klüger. Und ich zeig dir noch einen Kniff mit einer leeren Farbe.`),{t:`choose`,text:`Du bietest zuerst. Deine Hand: Buur und Nell in Schilte, dazu Könige. Ordentlich. Fang an.`,options:[{id:`B600`,label:`Bieten 600`},{id:`B700`,label:`Bieten 700`},{id:`FORT`,label:`Fort`}],answer:`B600`,wrong:{B700:`Zu hoch für den Anfang. Fang mit 600 an, so lässt du dir Luft.`,FORT:`Mit Buur und Nell in einer Farbe steigst du nicht aus. Biete 600.`},fx:{badges:[`Gebot: 600`],bubbles:{SUED:`600`,NORD:`610`,WEST:`620`}}},{t:`choose`,text:`Die Bauern bieten ordentlich mit: {NORD} 610, {WEST} sogar 620. Jetzt bist du wieder dran. Was tust du?`,tip:`Wer mitbietet, sucht Beute. Die Bauern halten nicht zufällig so hoch dagegen.`,options:[{id:`B630`,label:`Bieten 630`},{id:`FORT`,label:`Fort`}],answer:`B630`,wrong:{FORT:`Du hast den Buur und den Nell. Mit dem Talon wird das Blatt noch stärker, bleib im Spiel.`},fx:{badges:[`Gebot: 630`],bubbles:{NORD:`Fort`,WEST:`Fort`}}},{t:`choose`,text:`Beide steigen aus. Du bist König mit 630. Die Bauern brauchen für ihren Sieg 1000 Punkte. Warum ist dein Ziel kleiner?`,options:[{id:`ALLEIN`,label:`Weil du allein gegen zwei spielst`},{id:`GLUECK`,label:`Weil du Glück hast`},{id:`TALON`,label:`Weil der Talon zählt`}],answer:`ALLEIN`,wrong:{GLUECK:`Mit Glück hat das nichts zu tun. Der Ausgleich ist fest eingebaut.`,TALON:`Der Talon ändert nur die Karten, nicht das Ziel. Der Grund ist ein anderer.`}},{t:`choose`,text:`Nimm den Talon auf.`,options:[{id:`TALON`,label:`Talon aufnehmen`}],answer:`TALON`,fx:{badges:[`König · Ziel 630`],takeTalon:!0}},{t:`choose`,text:`Du musst sechs Karten ablegen. In Rosen hast du nur Kleinkram: Rosen 8, 7, 9 und 6. Wenn du die alle loswirst, bist du in dieser Farbe leer. Welche Farbe legst du ganz ab?`,tip:`Eine leere Farbe lässt dich später mit Trumpf stechen, wenn die Bauern sie ausspielen.`,options:[{id:`ROSE`,label:`Rose`},{id:`SCHELLE`,label:`Schelle`},{id:`EICHEL`,label:`Eichel`}],answer:`ROSE`,wrong:{SCHELLE:`In Schellen hast du König und Ober, die behältst du lieber.`,EICHEL:`In Eichel hast du König und Ober. Die Rosen sind dein Ballast.`}},{t:`pick`,cards:`R8 R7 R9 R6 S7 E8`,text:`Tippe die vier Rosen an, dazu die Schellen 7 und die Eichel 8. Lege ab: Rosen 8, 7, 9, 6, Schelle 7, Eichel 8.`,wrong:{"*":`Die behältst du besser. Lege die vier Rosen, die Schelle 7 und die Eichel 8 ab.`}},{t:`choose`,text:`Sag den Trumpf an. Buur, Nell und noch zwei Schilten, die haben das Sagen.`,options:r,answer:`SCHILTE`,wrong:{"*":`Deine Schilten mit Under und Nell sind die Trumpffarbe.`},fx:{trump:`SCHILTE`,badges:[`König · Ziel 630`,`Trumpf Schilte`],bubbles:{SUED:`Schilte!`}}},{t:`play`,seat:`SUED`,code:`LU`,text:`Du spielst aus, natürlich mit dem Buur.`},{t:`play`,seat:`NORD`,code:`L6`},{t:`play`,seat:`WEST`,code:`LO`},{t:`play`,seat:`SUED`,code:`EK`,text:`Jetzt gebe ich dir einen Kniff mit. Du spielst den Eichel-König, und das Ass sitzt bei {NORD}. Du gibst den Stich ab. Das ist Absicht: Danach muss {NORD} ausspielen, und du hast keine Rosen mehr.`},{t:`play`,seat:`NORD`,code:`EA`},{t:`choose`,text:`{WEST} muss Eichel bedienen. Er hat die Zehn und die Sechs. Welche legt er, wo sein Partner {NORD} den Stich sicher hat?`,options:[{id:`E10`,label:`Eichel 10`,code:`E10`},{id:`E6`,label:`Eichel 6`,code:`E6`}],answer:`E10`,wrong:{E6:`Die Bauern schmieren sich gegenseitig: Der Partner gewinnt sicher, also gibt {WEST} die Zehn dazu, 10 Punkte für die Bauern.`}},{t:`play`,seat:`WEST`,code:`E10`,text:`Siehst du? Die Bauern spielen zusammen. Der eine holt den Stich, der andere schmiert die Zehn dazu. Darum überlegst du genau, wem du einen Stich überlässt.`},{t:`play`,seat:`NORD`,code:`RA`,text:`{NORD} hat den Stich und spielt aus: sein Rosen-Ass. Rosen hast du keine mehr.`},{t:`play`,seat:`WEST`,code:`RU`},{t:`play`,seat:`SUED`,code:`L7`,riddle:!0,text:`Du bist als Letzter dran und hast keine Rosen. Welche Karte legst du?`,wrong:{L9:`Der Nell sticht auch, aber ein kleinerer Trumpf reicht, und den Nell brauchst du später.`,L8:`Die Acht sticht auch, aber die Sieben ist noch kleiner und reicht genauso.`,"*":`Du bist als Letzter dran und kannst das Ass der Bauern abstechen. Nimm dafür den kleinsten Trumpf, der reicht.`}},e(`Genau: Die leere Farbe machte das Rosen-Ass zu deiner Beute. Merk dir: Die Bauern spielen als Team und schmieren sich. Gib ihnen keine Stiche, ausser mit Absicht. Und lege eine ganze Farbe ab, dann kannst du ihre Asse stechen.`)]}],p=[{regionId:`ZUERICH`,kind:`trick`,title:`Molotow`,lesson:`Strafpunkte meiden`,ziele:[`Das Ziel kennen: wenig Punkte`,`Wissen, wie Trumpf entsteht`,`Strafpunkte meiden`],zielAt:[1,6,14],einstieg:`Beim Molotow gewinnt, wer wenig sammelt. Das kriegst du hin.`,order:t,score:`solo`,rules:{untertrumpfVerbot:!1},trump:null,hands:{SUED:`S6 SO RK R10 LA L7 EU E8 E6`,OST:`S8 S9 SU S10 L9 LO EK E10 E7`,NORD:`SA SK S7 EA E9 EO R9 R8 RO`,WEST:`R6 RA RU R7 LK LU L10 L8 L6`},steps:[e(`Molotow also. Hier spielt jeder für sich, und die Punkte sind Strafpunkte: Wer am Ende die wenigsten hat, gewinnt. Wer einen Stich macht, kassiert dessen Punkte und spielt als Nächster aus. Einen Trumpf gibt es zu Beginn nicht. Den macht gleich jemand, du wirst es sehen.`,`Gespielt wird gegen den Uhrzeigersinn: du, dann {OST}, {NORD}, {WEST}.`),{t:`choose`,text:`Erste Frage, damit ich weiss, ob du zugehört hast: Was willst du beim Molotow?`,options:[{id:`VIEL`,label:`Möglichst viele Punkte`},{id:`WENIG`,label:`Möglichst wenige Punkte`},{id:`STICHE`,label:`Möglichst viele Stiche`}],answer:`WENIG`,wrong:{VIEL:`Hmpf. Verkehrte Welt. Jeder Punkt ist hier eine Strafe: Je mehr du davon sammelst, desto schlechter für dich.`,STICHE:`Stiche sind hier eher eine Last: Wer sie macht, kassiert ihre Punkte. Du willst wenige Punkte, nicht viele Stiche.`}},{t:`play`,seat:`SUED`,code:`S6`,text:`Du spielst aus. Fang klein an, mit einer Karte ohne Punkte: die Schellen 6. Alle müssen Schellen bedienen, wenn sie können.`,tip:`Spiel aus, was dich nichts kostet: kleine Karten ohne Punkte.`,wrong:{"*":`Nimm die Schellen 6. Sie kostet dich nichts und gewinnt nichts.`}},{t:`play`,seat:`OST`,code:`S8`},{t:`play`,seat:`NORD`,code:`SA`,text:`{NORD} bedient mit dem Schellen-Ass. Elf Punkte liegen jetzt im Stich. Merk dir das.`},{t:`choose`,text:`Jetzt ist {WEST} dran, und er hat keine Schellen mehr. Was geschieht?`,options:[{id:`ABWERFEN`,label:`Er wirft ab, was er will, sonst nichts`},{id:`TRUMPF`,label:`Seine Karte macht den Trumpf, und er gewinnt den Stich`},{id:`AUSSETZEN`,label:`Er darf aussetzen`}],answer:`TRUMPF`,wrong:{ABWERFEN:`Nicht ganz. Beim Molotow hat das erste Nicht-Bedienen Folgen: Die Farbe seiner Karte wird Trumpf, für den Rest der Hand.`,AUSSETZEN:`Aussetzen gibt es nicht. Jeder legt eine Karte, und die erste, die nicht bedient, macht den Trumpf.`}},{t:`play`,seat:`WEST`,code:`R6`,text:`{WEST} legt die Rosen 6. Damit ist Rose Trumpf, für die ganze Hand. Und weil sie Trumpf ist, sticht sie das Schellen-Ass: {WEST} kassiert die 11 Punkte. Wer als Erster leer ist, hat also nicht nur Glück.`,fx:{trump:`ROSE`,badges:[`Trumpf: Rose`],bubbles:{WEST:`Rose ist Trumpf!`}}},{t:`play`,seat:`WEST`,code:`LK`,text:`{WEST} hat gewonnen und spielt aus: Schilten König.`,fx:{bubbles:{}}},{t:`play`,seat:`SUED`,code:`L7`,riddle:!0,text:`Schilten sind ausgespielt. Welche Karte legst du?`,tip:`Du willst diesen Stich nicht gewinnen.`,wrong:{LA:`Das Ass schlägt den König. Du gewinnst den Stich und kassierst 15 Punkte (König 4, Ass 11). Das willst du nicht.`,"*":`Rose ist jetzt Trumpf und sticht: Der Stich wäre deiner, samt dem König. Bedien lieber mit der kleinsten Schilten.`}},{t:`play`,seat:`OST`,code:`L9`},{t:`play`,seat:`NORD`,code:`E9`,text:`{NORD} hat keine Schilten und wirft die Eichel 9 ab. Stechen müsste er nicht: Trumpfen ist freiwillig.`},{t:`play`,seat:`WEST`,code:`RA`,text:`{WEST} gewinnt wieder und spielt Trumpf aus: das Rosen-Ass.`},{t:`play`,seat:`SUED`,code:`R10`,riddle:!0,text:`Trumpf ist ausgespielt, du musst Rose bedienen. Welche Karte legst du?`,tip:`Schau dir an, wer hier den Stich nimmt.`,wrong:{RK:`Der König zählt nur 4. Schau, wer den Nell hat: {NORD} gewinnt diesen Stich so oder so. Dann gehört die punktereichste Karte hinein: die Zehn. Die Strafe bekommt er, nicht du.`}},{t:`play`,seat:`OST`,code:`E7`,text:`{OST} hat keine Rosen und wirft eine wertlose Karte ab.`},{t:`play`,seat:`NORD`,code:`R9`,text:`{NORD} sticht mit dem Nell, dem zweithöchsten Trumpf, und kassiert 35 Strafpunkte. Du keinen einzigen.`},e(`Nach drei Stichen: du 0 Strafpunkte, {WEST} 15, {NORD} 35. Das ist das ganze Handwerk: klein ausspielen, nicht stechen, und Punkte in Stiche werfen, die ein anderer sowieso gewinnt.`,`Dazu gibt es Strafpunkte für den Tischweis und für Stöck. Hattest du König und Ober des Trumpfs auf der Hand, ziehst du dir am Ende 20 Punkte ab. Untertrumpfen ist erlaubt. Und wer alle Stiche macht (Tutti), dem werden seine Strafpunkte gestrichen, alle anderen bekommen je 257. Selten und riskant.`)]},{regionId:`ZUERICH`,kind:`trick`,title:`Molotow`,lesson:`Wer leer ist, kassiert`,ziele:[`Wissen, wer leer ist`,`Strafpunkte richtig zählen`,`Auf hohen Trumpf im Stich achten`],zielAt:[1,6,11],einstieg:`Jetzt wird es schlau. Schau gut hin, wer was nicht hat.`,order:t,score:`solo`,rules:{untertrumpfVerbot:!1},trump:null,hands:{SUED:`SA R10 RK R8 LA L9 L8 L7 L6`,OST:`EA E10 E9 S8 S9 S6 SK RU RO`,NORD:`E8 E7 EU R6 R7 R9 RA LK L10`,WEST:`E6 EO EK S10 SU SO S7 LU LO`},steps:[e(`Zweite Hand, und jetzt wird es schlau. Wer als Erster eine Farbe nicht bedienen kann, macht den Trumpf und nimmt den Stich. Das kann ein Segen sein oder eine Last. Und du kannst es jemandem aufhalsen.`,`Wir spielen wieder mit offenen Karten. Das gibt es am echten Tisch nicht, hier schon.`),{t:`choose`,text:`Schau dir die Karten von {NORD} an: keine einzige Schelle. Was geschieht, wenn jemand Schellen ausspielt?`,tip:`Denk an das, was du eben gelernt hast: Wer zuerst nicht bedienen kann, macht den Trumpf.`,options:[{id:`HOCH`,label:`Wer die höchste Schelle legt, kassiert`},{id:`LEER`,label:`Wer keine Schellen hat, macht den Trumpf und kassiert`},{id:`AUS`,label:`Der Ausspieler kassiert immer`}],answer:`LEER`,wrong:{HOCH:`So wäre es ohne Trumpf. Aber {NORD} hat keine Schellen, und seine Karte wird Trumpf. Dann sticht sie die höchste Schelle.`,AUS:`Nein, der Ausspieler kassiert nur, wenn niemand stechen kann. Hier kann {NORD}.`}},{t:`play`,seat:`SUED`,code:`SA`,riddle:!0,text:`Du spielst aus. Welche Karte?`,wrong:{LA:`Das Schilten-Ass gewinnt, und der Stich ist deiner: 11 Punkte, nichts als Ärger. Denk an {NORD}.`,"*":`Denk an {NORD}: Er hat keine Schellen. Du brauchst eine Schelle, damit er den Stich nehmen muss, und du hast genau eine.`}},{t:`play`,seat:`OST`,code:`S8`,text:`{OST} muss Schellen bedienen und legt die Acht, damit er keine Punkte verschenkt.`},{t:`play`,seat:`NORD`,code:`R6`,text:`{NORD} hat keine Schellen. Er muss etwas legen, und seine Rosen 6 macht Rose zum Trumpf. Sie sticht dein Ass, und {NORD} nimmt den Stich.`,fx:{trump:`ROSE`,badges:[`Trumpf: Rose`],bubbles:{NORD:`Muss ja...`}}},{t:`play`,seat:`WEST`,code:`S10`,text:`{WEST} sieht, dass {NORD} den Stich nimmt, und schiebt ihm die Schellen 10 zu. Das machen die anderen auch mit dir, wenn du nicht aufpasst.`,fx:{bubbles:{}}},{t:`choose`,text:`Rechne nach: Schellen-Ass, Schellen 8, Rosen 6 und Schellen 10. Wie viele Strafpunkte kassiert {NORD}?`,options:[{id:`P11`,label:`11 Punkte`},{id:`P21`,label:`21 Punkte`},{id:`P31`,label:`31 Punkte`}],answer:`P21`,wrong:{P11:`Das Ass allein sind 11. Die Zehn von {WEST} liegt auch drin.`,P31:`Zu viel. Die Acht und die Rosen 6 zählen hier nichts. Ass 11 plus Zehn 10 sind 21.`}},{t:`play`,seat:`NORD`,code:`E7`,text:`{NORD} hat gewonnen und spielt aus: die Eichel 7.`},{t:`play`,seat:`WEST`,code:`E6`},{t:`play`,seat:`SUED`,code:`LA`,riddle:!0,text:`Du hast keine Eichel, Rose ist Trumpf. Was legst du?`,tip:`Schau, wer den Stich nehmen wird.`,wrong:{R10:`Das ist Trumpf, und Trumpf sticht Eichel: Der Stich wäre deiner. Zehn plus Ass, das sind 21 Punkte für dich.`,RK:`Das ist Trumpf, und Trumpf sticht Eichel: Der Stich wäre deiner.`,R8:`Das ist Trumpf, und Trumpf sticht Eichel: Der Stich wäre deiner.`,"*":`Sicher, das kostet dich nichts. Aber du verschenkst die Gelegenheit: {OST} hat das Eichel-Ass und nimmt den Stich so oder so. Da gehört die punktereichste Karte hinein, die nicht sticht.`}},{t:`play`,seat:`OST`,code:`EA`,text:`{OST} nimmt den Stich mit dem Eichel-Ass: 22 Punkte, und dein Schilten-Ass ist weg. Ohne einen Punkt für dich.`},{t:`choose`,text:`Noch eine Regel, die es beim Schieber so nicht gibt. Liegt im Stich schon ein hoher Trumpf, darfst du trotzdem einen kleineren Trumpf legen («untertrumpfen»). Stimmt das?`,options:[{id:`JA`,label:`Ja, im Molotow ist das erlaubt`},{id:`NEIN`,label:`Nein, das ist verboten`}],answer:`JA`,wrong:{NEIN:`Beim Schieber hättest du recht. Im Molotow ist Untertrumpfen erlaubt. Es hilft dir, eine Trumpfkarte mit vielen Punkten in den Stich eines anderen zu legen.`}},{t:`replay`,tricks:[`SK EU SO L6`],text:`{OST} spielt Schellen-König aus. {NORD} wirft die Eichel Under ab, {WEST} legt den Schellen-Ober, du die Schilten 6. {OST} nimmt die 9 Punkte.`},e(`Stand nach drei Stichen: du 0 Strafpunkte, {NORD} 21, {OST} 31. Du hast nicht einmal gewonnen, und doch führst du. So geht Molotow.`,`Merk dir: Wer leer ist, nimmt den Stich. Hast du ein Ass oder eine Zehn, such den Leeren und spiel die Farbe an, in der er leer ist. Und wirf Punkte nur dann ab, wenn ein anderer den Stich sicher nimmt.`)]},{regionId:`ZUERICH`,kind:`trick`,title:`Molotow`,lesson:`Trumpf nach Mass`,ziele:[`Als Leerer den Trumpf machen`,`Den Trumpf nach Mass wählen`,`Punktekarten sicher loswerden`],zielAt:[4,5,14],einstieg:`Diesmal bestimmst du den Trumpf. Nimm dir Zeit dafür.`,order:t,firstLeader:`WEST`,score:`solo`,rules:{untertrumpfVerbot:!1},trump:null,hands:{SUED:`EK EO E6 SU S9 S8 RU R9 R6`,WEST:`L6 LK LU RA RK EA E7 S7 SK`,OST:`L8 L10 LO R7 R8 E8 E10 S6 SO`,NORD:`L7 L9 LA RO R10 EU E9 S10 SA`},steps:[e(`Dritte Hand. Diesmal bist du der Leere: {WEST} spielt Schilten aus, und du hast keine. Mit der Karte, die du legst, bestimmst du den Trumpf. Das ist deine Chance, einen guten zu wählen.`,`Der Trumpf bestimmt, welche Karten teuer werden: Trumpf-Under zählt 20 Punkte, der Nell 14.`),{t:`play`,seat:`WEST`,code:`L6`,text:`{WEST} spielt die Schilten 6 aus. Du hast keine Schilten, du machst den Trumpf.`},{t:`play`,seat:`SUED`,code:`E6`,riddle:!0,text:`Welche Karte legst du?`,tip:`Jede Farbe, die du hier legst, wird Trumpf. Schau dir an, was dann in deiner Hand teuer wird.`,wrong:{EK:`Eichel wäre richtig. Aber der König zählt 4 Punkte, und weil dein Trumpf den Stich sticht, wären sie deine. Nimm die kleine Eichel.`,EO:`Eichel wäre richtig. Aber der Ober zählt 3 Punkte, und weil dein Trumpf den Stich sticht, wären sie deine. Nimm die kleine Eichel.`,SU:`Schelle wird Trumpf, und dann sind dein Under und dein Nell Trumpf-Under (20) und Trumpf-Nell (14). 34 Strafpunkte in deiner Hand, das willst du nicht.`,S9:`Schelle wird Trumpf, und dann sind dein Under und dein Nell Trumpf-Under (20) und Trumpf-Nell (14). 34 Strafpunkte in deiner Hand, das willst du nicht.`,S8:`Schelle wird Trumpf, und dann sind dein Under und dein Nell Trumpf-Under (20) und Trumpf-Nell (14). 34 Strafpunkte in deiner Hand, das willst du nicht.`,RU:`Rose wird Trumpf, und dann sind dein Under und dein Nell Trumpf-Under (20) und Trumpf-Nell (14). 34 Strafpunkte in deiner Hand, das willst du nicht.`,R9:`Rose wird Trumpf, und dann sind dein Under und dein Nell Trumpf-Under (20) und Trumpf-Nell (14). 34 Strafpunkte in deiner Hand, das willst du nicht.`,R6:`Rose wird Trumpf, und dann sind dein Under und dein Nell Trumpf-Under (20) und Trumpf-Nell (14). 34 Strafpunkte in deiner Hand, das willst du nicht.`,"*":`Überleg: Welche Farbe soll Trumpf werden? Eine, in der du keinen Under und keinen Nell hältst.`},fx:{trump:`EICHEL`,badges:[`Trumpf: Eichel`],bubbles:{SUED:`Eichel ist Trumpf!`}}},{t:`play`,seat:`OST`,code:`L8`,fx:{bubbles:{}}},{t:`play`,seat:`NORD`,code:`L9`,text:`Deine Eichel 6 ist Trumpf und sticht alles: Der Stich ist deiner. Er hat aber keine Punkte, und das war ja der Sinn.`},{t:`choose`,text:`Du hast den Eichel-König und den Eichel-Ober gehalten, bevor der Trumpf feststand. Jetzt ist Eichel Trumpf. Was bringt dir das?`,options:[{id:`STOECK`,label:`20 Punkte Abzug am Ende (Stöck)`},{id:`NICHTS`,label:`Nichts, es sind nur Strafpunkte`},{id:`NOCHMAL`,label:`Ich darf gleich nochmals ausspielen`}],answer:`STOECK`,wrong:{NICHTS:`Im Gegenteil: König und Ober im selben Trumpf sind Stöck, und das gibt dir am Ende 20 Punkte Abzug.`,NOCHMAL:`Nochmals ausspielen darfst du, weil du den Stich gewonnen hast. Stöck ist etwas anderes: 20 Punkte Abzug am Schluss.`},fx:{status:`Stöck: 20 Punkte Abzug am Ende`}},{t:`choose`,text:`Du spielst gleich aus. Rose ist keine Trumpffarbe. Wie viele Punkte zählt dein Rosen-Under jetzt?`,options:[{id:`P20`,label:`20 Punkte`},{id:`P2`,label:`2 Punkte`},{id:`P0`,label:`0 Punkte`}],answer:`P2`,wrong:{P20:`Das wäre er als Trumpf. Die Rose ist aber keine Trumpffarbe, der Under zählt nur wie eine gewöhnliche Karte: 2 Punkte.`,P0:`Ganz so harmlos ist er nicht: Der Under zählt immer 2 Punkte, ausser er ist Trumpf.`}},{t:`play`,seat:`SUED`,code:`R6`,text:`Du hast gewonnen und spielst aus. Deine Rosen sind harmlos, also klein beginnen: die Rosen 6.`,tip:`Klein ausspielen, die Punkte lässt du die anderen holen.`,wrong:{"*":`Spiel die kleinste Karte: Rosen 6.`},fx:{badges:[`Trumpf: Eichel`,`Stöck -20`]}},{t:`play`,seat:`OST`,code:`R7`},{t:`play`,seat:`NORD`,code:`RO`},{t:`play`,seat:`WEST`,code:`RA`,text:`{WEST} gewinnt mit dem Rosen-Ass und kassiert 14 Punkte. Siehst du, deine Rosen waren wirklich harmlos.`},{t:`play`,seat:`WEST`,code:`RK`,text:`{WEST} spielt weiter Rosen aus: der König.`},{t:`play`,seat:`SUED`,code:`RU`,riddle:!0,text:`Rosen sind ausgespielt. Welche Karte legst du?`,tip:`Schau, wer den Stich nimmt. Und wer einen Under hat, ist ihn besser los.`,wrong:{R9:`Die Neun kostet nichts, das stimmt. Aber der Under ist höher als die Neun und könnte dich später zum Stich zwingen. Weg damit, solange {WEST} mit dem König sicher gewinnt.`,EK:`Das ist Trumpf und sticht: Der Stich wäre deiner, samt der Zehn von {NORD}.`,EO:`Das ist Trumpf und sticht: Der Stich wäre deiner, samt der Zehn von {NORD}.`,"*":`Bedien Rose. Der Stich gehört {WEST}, wirf den Under hinein.`}},{t:`play`,seat:`OST`,code:`R8`},{t:`play`,seat:`NORD`,code:`R10`,text:`{NORD} schiebt {WEST} die Rosen 10 zu. {WEST} nimmt 16 Punkte, du null.`},e(`Gut gemacht. Du hast den Trumpf nach deinem Mass gewählt: eine Farbe ohne Under und Nell, mit König und Ober für den Stöck. Stand: du 0, {WEST} 30, am Ende minus 20 für den Stöck.`,`Merk dir: Bist du leer, wähl die Farbe, in der du Under und Nell nicht hältst. Hast du König und Ober einer Farbe, ist das der Fingerzeig. Und leg dazu die kleinste Karte, damit du den Stich billig nimmst.`)]}],m={regionId:`LUZERN`,kind:`trick`,title:`Differenzler`,order:t,score:`differenz`,rules:{untertrumpfVerbot:!1}},h=[{...m,lesson:`Die Ansage`,ziele:[`Eine Ansage machen`,`Trümpfe ziehen, Punkte holen`,`Die eigenen Punkte zählen`],zielAt:[1,10,14],einstieg:`Beim Differenzler sagst du an und zielst dann genau. Wir üben es zusammen.`,target:80,trump:`ROSE`,hands:{SUED:`EA E7 SA S8 LA L9 RU R9 R6`,OST:`EK EO E8 SK SO LK LO R10 R7`,NORD:`EU E10 SU S10 S9 LU L10 R8 RK`,WEST:`E9 E6 S7 S6 L8 L7 L6 RO RA`},steps:[e(`Nu, dann schau dir das an. Beim Differenzler spielt jeder für sich. Die unterste Karte des gemischten Stapels bestimmt den Trumpf: Hier ist es das Rosen-Ass bei {WEST}, also ist Rose Trumpf. Vor der Runde sagt jeder an, wie viele Punkte er machen wird. Gewonnen hat am Ende, wer seiner Ansage am nächsten kommt. Nicht, wer die meisten Punkte holt.`,`Gespielt wird gegen den Uhrzeigersinn: Du, dann {OST}, {NORD}, {WEST}.`,{trump:`ROSE`,badges:[`Trumpf: Rose`]}),{t:`choose`,text:`Deine Hand: Trumpf-Under (20 Punkte), Nell (14 Punkte), drei Asse (33 Punkte). Dazu holst du Punkte aus den Stichen der Gegner. Wie viele Punkte sagst du an?`,tip:`Zähl die sicheren Stiche und ihre Punkte. Ein Spiel hat 157 Punkte, verteilt auf alle vier Spieler.`,options:[{id:`A50`,label:`50`},{id:`A65`,label:`65`},{id:`A80`,label:`80`},{id:`A100`,label:`100`}],answer:`A80`,wrong:{A50:`Du hast Under, Nell und drei Asse. Das sind allein schon 67 Punkte. 50 ist zu tief.`,A65:`Dazu kommen noch die Punkte, die die Gegner in deine Stiche werfen. Etwas mehr: Sag 80 an.`,A100:`So viel holst du nicht. Im ganzen Spiel sind nur 157 Punkte, und die verteilen sich auf vier. Sag 80.`},fx:{badges:[`Trumpf: Rose`,`Ansage: 80`]}},{t:`play`,seat:`SUED`,code:`RU`,riddle:!0,text:`Du spielst aus. Welche Karte?`,wrong:{R9:`Der Nell ist stark, aber der Under steht noch darüber. Beginn mit der stärksten.`,EA:`Noch nicht, die Gegner haben noch Rosen und könnten dein Ass abstechen. Zieh zuerst die Trümpfe.`,"*":`Beginn mit dem Buur, dem Rosen-Under: 20 Punkte und garantiert dein Stich.`}},{t:`play`,seat:`OST`,code:`R10`,text:`{OST} muss Trumpf bedienen und gibt die Zehn dazu: 10 Punkte für dich.`},{t:`play`,seat:`NORD`,code:`R8`},{t:`play`,seat:`WEST`,code:`RO`},{t:`play`,seat:`SUED`,code:`R9`,riddle:!0,text:`Der Buur ist durch. Du hast den Stich und spielst wieder aus. Welche Karte jetzt?`,wrong:{EA:`Noch nicht. Die Gegner haben noch Rosen. {WEST} hat sogar das Ass.`,R6:`Mit der Sechs verschenkst du den Stich. Spiel die stärkste Trumpfkarte, die du noch hast.`,"*":`Spiel den Nell, die zweitstärkste Karte im Trumpf.`}},{t:`play`,seat:`OST`,code:`R7`},{t:`play`,seat:`NORD`,code:`RK`},{t:`play`,seat:`WEST`,code:`RA`,text:`{WEST} muss das Rosen-Ass bedienen: 11 Punkte für dich. Mit {NORD}s König sind es 29.`},{t:`play`,seat:`SUED`,code:`EA`,text:`Kein Gegner hat mehr Trumpf. Jetzt holst du mit dem Eichel-Ass 11 Punkte.`,tip:`Im Differenzler gilt der «eingeschränkte Farbzwang»: Man darf auch trumpfen, obwohl man die Farbe hat. Untertrumpfen ist erlaubt.`,wrong:{"*":`Spiel das Eichel-Ass.`}},{t:`play`,seat:`OST`,code:`E8`},{t:`play`,seat:`NORD`,code:`EU`},{t:`play`,seat:`WEST`,code:`E6`},{t:`choose`,text:`Rechne nach: Deine drei Stiche brachten 33, 29 und 13 Punkte. Wie viele hast du jetzt?`,options:[{id:`P62`,label:`62`},{id:`P75`,label:`75`},{id:`P80`,label:`80`},{id:`P89`,label:`89`}],answer:`P75`,wrong:{P62:`Das waren die ersten beiden Stiche. Dazu kommen die 13 aus dem dritten.`,P80:`Das ist deine Ansage, nicht dein Stand. 33 plus 29 plus 13 sind weniger.`,P89:`Zu viel. 33 plus 29 plus 13 gibt weniger.`}},e(`Du hast 75 von 80 Punkten. Jetzt musst du genau zielen: Mit dem Schilten- und dem Schellen-Ass könntest du über deine Ansage kommen. Du darfst also auch bewusst Stiche abgeben. Der letzte Stich bringt 5 Punkte extra. Am Ende zählt die Differenz zwischen Ansage und erreichten Punkten, und wer die kleinste hat, gewinnt.`)]},{...m,lesson:`Ansage abschätzen`,ziele:[`Sichere Punkte zählen`,`Gegner-Punkte dazuschätzen`,`Asse einsammeln`,`Die Punkte nachzählen`],zielAt:[1,2,16,20],einstieg:`Schätzen ist die halbe Kunst. Ich helf dir dabei.`,target:90,trump:`SCHELLE`,hands:{SUED:`SU S7 SA EA EO RA R9 L10 L8`,OST:`S9 E10 EK R10 R7 R6 LA L9 L6`,NORD:`S10 S8 E9 E8 EU RK RU LK L7`,WEST:`SK SO S6 E7 E6 R8 RO LU LO`},steps:[e(`Zweite Hand. Diesmal geht es ums Schätzen, denn das ist beim Differenzler die halbe Kunst. Die unterste Karte ist die Schellen 8 bei {NORD}, also sind Schellen Trumpf. Schau dein Blatt an und rechne.`,null,{trump:`SCHELLE`,badges:[`Trumpf: Schelle`]}),{t:`choose`,text:`Fang mit dem Sicheren an: Du hast den Buur (20), das Trumpf-Ass (11) und zwei Neben-Asse, Eichel und Rose (je 11). Wie viele Punkte sind diese vier Karten wert?`,options:[{id:`P42`,label:`42`},{id:`P53`,label:`53`},{id:`P64`,label:`64`}],answer:`P53`,wrong:{P42:`Da fehlt ein Ass: 20 plus 11 plus 11 plus 11 sind mehr.`,P64:`Zu viel. 20 plus drei Asse zu je 11 gibt weniger.`}},{t:`choose`,text:`Das sind 53 sichere Punkte. Dazu kommen die Punkte, die dir die Gegner in die Stiche werfen müssen: der Nell zum Beispiel, wenn du den Buur spielst, oder eine Zehn. Wie viele Punkte sagst du an?`,tip:`Sichere Punkte plus die Beute aus den Stichen. Nicht gierig und nicht zu zaghaft.`,options:[{id:`A60`,label:`60`},{id:`A90`,label:`90`},{id:`A120`,label:`120`}],answer:`A90`,wrong:{A60:`Das wäre nur ein bisschen mehr als das Sichere. Aber du holst auch Beute: Alles, was die Gegner zu deinen Stichen legen, zählt für dich.`,A120:`Das ist zu gierig. Es gibt nur 157 Punkte im Spiel und drei Mitspieler, die auch etwas wollen.`},fx:{badges:[`Trumpf: Schelle`,`Ansage: 90`]}},{t:`play`,seat:`SUED`,code:`SU`,text:`Du spielst aus, mit dem Buur.`},{t:`choose`,text:`{OST} hat nur noch eine Schelle, den Nell. Was muss er auf deinen Buur legen?`,options:[{id:`ZUGEBEN`,label:`Den Nell zugeben`},{id:`ABWERFEN`,label:`Eine andere Karte abwerfen`},{id:`STECHEN`,label:`Mit einer anderen Farbe stechen`}],answer:`ZUGEBEN`,wrong:{ABWERFEN:`Abwerfen darf nur, wer die Farbe nicht hat. {OST} hat noch eine Schelle, also muss er sie zugeben.`,STECHEN:`Schelle ist Trumpf. Es gibt nichts, womit man ihn mit einer anderen Farbe stechen könnte.`}},{t:`play`,seat:`OST`,code:`S9`,text:`So ist es. Der Nell muss zugeben, und das sind 14 Punkte, die für dich zählen.`},{t:`play`,seat:`NORD`,code:`S8`},{t:`play`,seat:`WEST`,code:`S6`},{t:`play`,seat:`SUED`,code:`SA`,text:`Weiter mit dem Trumpf-Ass. {OST} hat keine Schellen mehr, {NORD} und {WEST} haben nur noch tiefere. Das Ass sticht sicher.`,tip:`Hast du Under und Ass im Trumpf, ziehst du die anderen Trümpfe heraus. Das ist Beute.`,wrong:{"*":`Spiel das Schellen-Ass, es ist jetzt der höchste Trumpf.`}},{t:`play`,seat:`OST`,code:`L6`,text:`{OST} hat keinen Trumpf mehr und wirft eine kleine Schilte ab.`},{t:`play`,seat:`NORD`,code:`S10`},{t:`play`,seat:`WEST`,code:`SO`},{t:`play`,seat:`SUED`,code:`EA`,text:`Alle Trümpfe der Gegner sind aus dem Spiel. Jetzt hol dir die Asse: das Eichel-Ass.`,wrong:{"*":`Spiel das Eichel-Ass, es ist jetzt ein sicherer Stich.`}},{t:`play`,seat:`OST`,code:`E10`,text:`{OST} muss Eichel bedienen und gibt die Zehn zu: 10 Punkte für dich.`},{t:`play`,seat:`NORD`,code:`E8`},{t:`play`,seat:`WEST`,code:`E6`},{t:`play`,seat:`SUED`,code:`RA`,text:`Und das Rosen-Ass.`},{t:`play`,seat:`OST`,code:`R6`},{t:`play`,seat:`NORD`,code:`RU`},{t:`play`,seat:`WEST`,code:`R8`},{t:`choose`,text:`Zähl nach: Deine vier Stiche brachten 34, 24, 21 und 13 Punkte. Wie viele hast du jetzt?`,options:[{id:`P79`,label:`79`},{id:`P92`,label:`92`},{id:`P101`,label:`101`}],answer:`P92`,wrong:{P79:`Das wären erst drei Stiche. Der vierte brachte noch 13.`,P101:`Zu viel. 34 plus 24 plus 21 plus 13 gibt weniger.`}},e(`Du stehst bei 92, angesagt hast du 90. Das hast du also genau geschätzt. Aber Vorsicht: Du hast noch fünf Karten, und jeder weitere Stich bringt Punkte. Wie du das in den Griff kriegst, zeig ich dir in der nächsten Hand. Merk dir: Sichere Punkte zählen, die Beute dazurechnen, nicht zu gierig sein.`)]},{...m,lesson:`Punktgenau landen`,ziele:[`Fehlende Punkte ausrechnen`,`Genau bis zur Ansage sammeln`,`Danach Stiche abgeben`,`Differenz null erreichen`],zielAt:[1,5,11,12],einstieg:`Jetzt wird es fein: genau auf den Punkt. Ganz ohne Druck.`,target:30,trump:`SCHILTE`,hands:{SUED:`LU L10 LO E8 SU R10 R6 E6 S6`,OST:`L8 L9 LK E9 S10 R7 RK E7 S9`,NORD:`L7 EK S7 SO RO R8 RU EA SK`,WEST:`L6 LA EU SA E10 R9 RA EO S8`},prelude:[`LU L8 L7 L6`,`E8 E9 EK EU`,`S7 SA SU S10`,`LA L10 L9 SO`,`LK RO E10 LO`],steps:[e(`Dritte Hand, und jetzt wird es fein. Fünf Stiche sind schon gespielt. Du hast mit dem Buur 20 Punkte geholt und stehst jetzt bei 20. Angesagt hast du 30, dir fehlen also noch ein paar Punkte. Jeder hat noch vier Karten. Jetzt wird nicht mehr gejagt, jetzt wird gezielt.`,null,{badges:[`Trumpf: Schilte`,`Ansage: 30`]}),{t:`choose`,text:`Wie viele Punkte fehlen dir noch bis zur Ansage?`,options:[{id:`F5`,label:`5`},{id:`F10`,label:`10`},{id:`F20`,label:`20`}],answer:`F10`,wrong:{F5:`Du stehst bei 20, die Ansage ist 30. Das sind mehr als 5.`,F20:`Du stehst schon bei 20, nicht bei null. Es fehlen weniger.`}},{t:`play`,seat:`OST`,code:`R7`,text:`{OST} hat den letzten Stich gewonnen und spielt aus: eine kleine Rose. Du hast die Rosen 10 und die Rosen 6, dazu je eine Sechs in Eichel und Schelle. Das sind deine letzten vier Karten.`},{t:`play`,seat:`NORD`,code:`R8`},{t:`play`,seat:`WEST`,code:`R9`},{t:`play`,seat:`SUED`,code:`R10`,riddle:!0,text:`Du bist als Letzter dran und musst Rosen bedienen. Welche Karte legst du?`,wrong:{R6:`Dann holt {WEST} den Stich, und du bleibst bei 20. Du verfehlst die Ansage um 10. Die Zehn ist genau das, was dir fehlt.`,"*":`Du musst Rose bedienen. Die Rosen 10 holt dir genau die fehlenden Punkte.`}},{t:`choose`,text:`Du stehst jetzt genau bei 30. Was ist ab sofort dein Ziel?`,options:[{id:`KEINEN`,label:`Keinen Stich mehr gewinnen`},{id:`MEHR`,label:`Noch so viele Punkte wie möglich holen`},{id:`EGAL`,label:`Egal, das passt schon`}],answer:`KEINEN`,wrong:{MEHR:`Dann liegst du über deiner Ansage. Jeder Punkt mehr kostet dich einen Punkt Differenz.`,EGAL:`Nein. Du hast die Ansage getroffen, jetzt musst du sie auch halten. Ein einziger weiterer Stich verdirbt sie dir.`}},{t:`play`,seat:`SUED`,code:`R6`,text:`Du hast den Stich und spielst aus. Spiel die Rosen 6. Sie verliert gegen jede höhere Rose, genau das, was du jetzt brauchst.`,tip:`Tiefe Karten sind jetzt deine Freunde: Sie gewinnen keine Stiche.`,wrong:{"*":`Auch eine Sechs, aber spiel hier die Rosen 6.`}},{t:`play`,seat:`OST`,code:`RK`},{t:`play`,seat:`NORD`,code:`RU`},{t:`play`,seat:`WEST`,code:`RA`,text:`{WEST} holt den Stich mit dem Ass, nicht du. Genau so soll es sein.`},{t:`replay`,tricks:[`EO E6 E7 EA`,`SK S8 S6 S9`],text:`Die letzten beiden Stiche gehen ohne dich weg. Deine Sechsen sind die tiefsten Karten und gewinnen nichts. Den letzten Stich holt {NORD} mit dem Schellen-König, samt den 5 Extrapunkten.`},{t:`choose`,text:`Die Hand ist fertig. Wie gross ist deine Differenz, bei 30 angesagt und 30 gemacht?`,options:[{id:`D0`,label:`0`},{id:`D10`,label:`10`},{id:`D20`,label:`20`}],answer:`D0`,wrong:{D10:`Du hast genau 30 gemacht und 30 angesagt. Das ist keine Differenz.`,D20:`Du stehst bei 30, die Ansage ist 30. Da fehlt nichts.`}},e(`Punktgenau, Differenz null. Das ist die Königsdisziplin: Erst holst du, was dir fehlt, dann gibst du alles ab. Tiefe Karten sind dabei dein Handwerk. Und denk an den letzten Stich: Er zählt 5 Zusatzpunkte, du darfst ihn nicht aus Versehen gewinnen.`)]}],g=[{regionId:`GRAUBUENDEN`,kind:`trick`,title:`Sidi Barrani`,lesson:`Das Ansage-System`,ziele:[`Gebote der anderen lesen`,`Mit dem Partner zusammen bieten`,`Kontern, Trümpfe ziehen`,`Die Punkte abrechnen`],zielAt:[5,6,16,20],einstieg:`Sidi Barrani hat eine eigene Sprache beim Bieten. Ich übersetz sie dir.`,order:t,score:`teams`,target:100,hands:{SUED:`E6 E8 EU L8 LK LA R6 RO SU`,OST:`S7 S9 S10 SK R9 R10 L6 LO E7`,NORD:`E9 EO EA S6 S8 R8 RU L10 LU`,WEST:`R7 RK RA SO SA E10 EK L7 L9`},steps:[e(`Sidi Barrani. Du spielst mit {NORD} gegen {OST} und {WEST}. Wer den Trumpf will, muss Punkte bieten. Die Zahl ist aber mehr als ein Versprechen: Sie verrät deinem Partner, was du in der Hand hast. Das ist das Ansage-System.`,`Gespielt wird gegen den Uhrzeigersinn: du, dann {OST}, {NORD}, {WEST}.`),e(`Geboten wird reihum, ab 50 in 5er-Schritten bis 155. Das höchste Gebot ist der Matsch: 157, alle Punkte. Wer «fort» sagt, bleibt draussen. Sagen alle vier «fort», wird neu gegeben.`,`Weis und Stöck zählen für die Partie, aber nicht beim Bieten: Das Gebot holt ihr allein mit Kartenpunkten.`),{t:`choose`,text:`Du bist Vorhand und bietest zuerst. Du hast Eichel-Under, Eichel 8 und Eichel 6: den Puur zu dritt. Was sagst du?`,tip:`Puur zu dritt 60, zu viert 80, zu fünft 100, zu sechst 120. Der Puur zählt mit. Mit dem Nell statt dem Puur sind es zehn weniger: 50, 70, 90, 110.`,options:[{id:`E60`,label:`Eichel 60`,suit:`EICHEL`},{id:`E80`,label:`Eichel 80`,suit:`EICHEL`},{id:`L65`,label:`Schilte 65`,suit:`SCHILTE`}],answer:`E60`,wrong:{E80:`80 hiesse Puur zu viert. Du hast drei Eicheln: Das ist die 60. Jede weitere Karte wäre 20 mehr.`,L65:`Ein Fünfer zeigt ein Ass, nicht deinen Trumpf. Eröffne mit deiner Trumpffarbe, und zwar ehrlich: Als Erster wird nicht geblufft.`},fx:{badges:[`Gebot: Eichel 60`],bubbles:{SUED:`Eichel 60`,OST:`Schelle 70`}}},{t:`choose`,text:`{OST} bietet Schelle 70. Was weisst du jetzt über seine Karten?`,tip:`Wer den Puur hat, sagt ihn an. Die Nell-Reihe heisst also auch: Der Puur fehlt mir.`,options:[{id:`NELL4`,label:`Er hat das Nell und drei weitere Schellen, aber nicht den Puur`},{id:`PUUR4`,label:`Er hat den Puur zu viert`},{id:`ASS`,label:`Er hat das Schellen-Ass`}],answer:`NELL4`,wrong:{PUUR4:`Puur zu viert wäre 80. Die 70 steht in der Nell-Reihe: 50, 70, 90, 110.`,ASS:`Ein Ass zeigt man mit einem Fünfer, zum Beispiel 75. Die 70 ist ein Zehner.`},fx:{bubbles:{NORD:`Eichel 90`}}},{t:`choose`,text:`Dein Partner {NORD} bietet Eichel 90, in deiner Farbe. Was sagt er dir damit?`,tip:`In der Farbe des Partners heisst ein Zehner «Hilfe». Zählen tun die beiden kleinsten Zehner über dem laufenden Gebot, hier 80 und 90: der kleinere heisst «zu zweit», der grössere «zu dritt oder mehr».`,options:[{id:`HILFE3`,label:`Ich habe das Eichel-Nell und mindestens zwei Eicheln dazu`},{id:`HILFE2`,label:`Ich habe das Eichel-Nell und eine Eichel dazu`},{id:`NELL5`,label:`Ich habe das Nell zu fünft`}],answer:`HILFE3`,wrong:{HILFE2:`Das wäre die 80, der kleinere der beiden Zehner über der 70 von {OST}. Die 90 ist der grössere: Nell zu dritt oder mehr.`,NELL5:`So zählt nur die Eröffnung. Eichel hast aber du eröffnet, und zwar mit dem Puur. Darum meldet {NORD} mit seiner Hilfe das Nell. Wer mit dem Nell eröffnet, bekommt umgekehrt den Puur gemeldet.`},fx:{bubbles:{WEST:`Rose 95`}}},{t:`choose`,text:`{WEST} sagt Rose 95. Was heisst ein Fünfer?`,tip:`Zehner eröffnen und helfen, Fünfer zeigen ein Ass.`,options:[{id:`ASS`,label:`Ich habe das Rosen-Ass, als Trumpf meine ich eine andere Farbe`},{id:`ROSE`,label:`Ich will Rose als Trumpf`},{id:`NIX`,label:`Nichts, nur 5 mehr`}],answer:`ASS`,wrong:{ROSE:`Dafür würde er einen Zehner bieten. Der Fünfer zeigt seinem Partner das Rosen-Ass. Bleibt die 95 aber stehen, muss er mit Rose als Trumpf 95 holen. Er rechnet also damit, dass ihr weiterbietet.`,NIX:`Am Tisch heisst jede Zahl etwas. Die 95 sagt {OST}: Ich halte das Rosen-Ass.`}},{t:`choose`,text:`Du bist wieder dran. Zusammen habt ihr Puur und Nell und mindestens sechs Eicheln, dazu hast du Schilten-Ass und Schilten-König. Was bietest du?`,tip:`Zähl, was ihr sicher holt: fast alle 62 Trumpfpunkte, Ass und König in Schilten, den letzten Stich. Das sind rund 80. Den Rest muss {NORD} bringen, und den kennst du nicht.`,options:[{id:`E100`,label:`Eichel 100`,suit:`EICHEL`},{id:`E130`,label:`Eichel 130`,suit:`EICHEL`},{id:`L105`,label:`Schilte 105`,suit:`SCHILTE`},{id:`FORT`,label:`Fort`}],answer:`E100`,wrong:{E130:`Zu hoch. Sicher sind rund 80 Punkte, für 130 müsste {NORD} noch 50 bringen. Biete die höchste Zahl, der du traust, aber nicht mehr.`,L105:`Damit verrätst du dein Schilten-Ass auch den Gegnern, und Eichel müsstest du danach mit einem noch höheren Gebot zurückholen.`,FORT:`Dann bleibt die 95 von {WEST} stehen, und die Gegner spielen. Mit dieser Eichel-Stärke bietest du weiter.`},fx:{badges:[`Gebot: Eichel 100`],bubbles:{SUED:`Eichel 100`,OST:`Fort`,NORD:`Fort`,WEST:`Fort`}}},e(`Alle anderen sagen «fort»: Eichel ist Trumpf, und ihr müsst 100 Kartenpunkte holen. Jetzt dürfen die Gegner doppeln, und {WEST} tut es. Er hat Rosen-Ass, Rosen-König und das Schellen-Ass und glaubt nicht an eure 100.`,`Doppeln verdoppelt nur die Zielpunkte, also das Gebot: Holt ihr die 100, schreibt ihr 200 zu euren Kartenpunkten. Verfehlt ihr sie, schreiben die Gegner die 200.`,{trump:`EICHEL`,badges:[`Ansage: Eichel 100`,`Doppel · x2`],bubbles:{WEST:`Doppel!`}}),{t:`choose`,text:`Du darfst jetzt kontern. Dann zählen die Zielpunkte vierfach: 400. Was machst du?`,options:[{id:`PASS`,label:`Stehen lassen (x2)`},{id:`KONTER`,label:`Kontern (x4)`}],answer:`PASS`,wrong:{KONTER:`Rund 20 Punkte deiner Rechnung kennst du nicht. Geht es schief, schreiben die Gegner 400. Für die 100 als Gebot reicht deine Rechnung, für 400 Zielpunkte ist sie zu unsicher.`},fx:{bubbles:{SUED:`Stehen lassen`}}},{t:`play`,seat:`SUED`,code:`EU`,riddle:!0,text:`Als Spielübernehmer spielst du aus. Welche Karte?`,wrong:{"*":`Zuerst gehört der Trumpf auf den Tisch: Mit dem Puur ziehst du den Gegnern ihre Eicheln aus der Hand.`},fx:{bubbles:{}}},{t:`play`,seat:`OST`,code:`E7`},{t:`play`,seat:`NORD`,code:`EO`},{t:`play`,seat:`WEST`,code:`EK`,text:`{WEST} muss den Eichel-König hergeben: 27 Punkte für euch.`},{t:`play`,seat:`SUED`,code:`E8`,text:`Zieh nochmals Trumpf. {NORD} hat das Nell, er übernimmt den Stich.`,wrong:{"*":`Spiel nochmals Trumpf, die Eichel 8.`}},{t:`play`,seat:`OST`,code:`S7`},{t:`play`,seat:`NORD`,code:`E9`},{t:`play`,seat:`WEST`,code:`E10`,text:`Nach zwei Trumpfrunden haben die Gegner keine Eicheln mehr. Alle Trumpfpunkte gehen an euch.`},{t:`replay`,tricks:[`LU L7 LK L6`,`LA LO L10 L9`,`L8 R9 RU R7`],text:`Die Schilten, über die beim Bieten niemand geredet hat, bringen euch alle ihre Punkte. Nach fünf Stichen habt ihr 83.`},{t:`replay`,tricks:[`R6 R10 R8 RA`,`RK RO S9 EA`],text:`{WEST} holt mit dem Rosen-Ass, was er angesagt hat. Seinen Rosen-König aber sticht {NORD} mit dem Eichel-Ass: 101 Punkte, die 100 sind geschafft.`},{t:`replay`,tricks:[`S8 SA SU S10`,`SO E6 SK S6`],text:`Das Schellen-Ass holt {WEST} noch. Den letzten Stich machst du mit dem letzten Trumpf, samt den 5 Punkten dafür.`},{t:`choose`,text:`Ihr habt 113 Kartenpunkte (108 aus den Stichen und 5 für den letzten), die Gegner 44. Was schreibt dein Team?`,options:[{id:`P213`,label:`213`},{id:`P313`,label:`313`},{id:`P426`,label:`426`}],answer:`P313`,wrong:{P213:`Das wäre ohne Doppeln. {WEST} hat gedoppelt, darum zählen die Zielpunkte doppelt: 200 und eure 113.`,P426:`Gedoppelt werden nur die Zielpunkte, nie die Kartenpunkte: 200 und 113.`}},e(`Die Tafel: Ihr schreibt 313, die Gegner 44. Hättet ihr die 100 verfehlt, hätten die Gegner die 200 zu ihren Kartenpunkten bekommen. So hat das Doppeln {WEST} 100 Punkte gekostet. Gespielt wird bis 1500.`,`Merksatz: Zehner eröffnen und helfen, Fünfer zeigen ein Ass. Und biete die höchste Zahl, der du traust: Geschrieben wird genau das Gebot.`)]},{regionId:`GRAUBUENDEN`,kind:`trick`,title:`Sidi Barrani`,lesson:`Bieten und Kontern`,ziele:[`Das Mindestgebot kennen`,`Mit starkem Blatt bieten`,`Kontern, wenn die Gegner doppeln`,`Trümpfe ziehen, dann Asse spielen`],zielAt:[1,2,4,16],einstieg:`Mit einem grossen Blatt darfst du mutig sein. Probier es aus.`,order:t,score:`teams`,target:100,hands:{SUED:`EA E8 SA S7 RU R9 RA RK R7`,NORD:`E6 EK S9 SK L7 L9 LA R6 R8`,WEST:`E10 E7 S6 SU S10 L6 L8 L10 LO`,OST:`E9 EO EU S8 SO LK LU R10 RO`},steps:[e(`Zweite Hand. Wieder bist du Vorhand, und diesmal hast du ein grosses Trumpfblatt. Wer aussteigt, sagt «Fort» und darf nicht mehr mitbieten.`,`Gespielt wird gegen den Uhrzeigersinn: du, dann {OST}, {NORD}, {WEST}.`),{t:`choose`,text:`Fangen wir mit dem Bieten an. Wie hoch muss das erste Gebot mindestens sein?`,options:[{id:`B40`,label:`40`},{id:`B50`,label:`50`},{id:`B60`,label:`60`}],answer:`B50`,wrong:{B40:`Zu tief. Das erste Gebot beginnt bei 50, dann geht es in 5er-Schritten.`,B60:`Mutig, aber nicht nötig: Schon 50 ist erlaubt. Danach geht es in 5er-Schritten weiter.`}},{t:`choose`,text:`Schau dir deine Hand an: Under, Nell, Ass, König und Sieben in Rose, dazu Eichel-Ass und Schellen-Ass. Was bietest du nach dem Ansage-System?`,tip:`Puur zu dritt 60, zu viert 80, zu fünft 100. Geschrieben wird bei Erfolg genau das Gebot: Zu tief bieten verschenkt Punkte.`,options:[{id:`ROSE100`,label:`Rose 100`,suit:`ROSE`},{id:`ROSE60`,label:`Rose 60`,suit:`ROSE`},{id:`OBEN60`,label:`Obenabe 60`}],answer:`ROSE100`,wrong:{ROSE60:`60 hiesse Puur zu dritt. Du hast fünf Rosen mit dem Puur: Das ist die 100. Mit 60 verschenkst du Punkte, und dein Partner weiss nicht, wie stark du bist.`,OBEN60:`Für Obenabe fehlen dir die Asse in Rose und Schilte. Deine Stärke ist Rose.`},fx:{badges:[`Gebot: Rose 100`],bubbles:{SUED:`Rose 100`,OST:`Fort`,NORD:`Fort`,WEST:`Fort`}}},e(`Alle sagen «fort», du bist Spielübernehmer mit Rose 100. Jetzt dürfen die Gegner doppeln: Sie glauben nicht, dass ihr 100 holt. {OST} tut es.`,`Gedoppelt zählen die Zielpunkte doppelt: 200 statt 100. Holen müsst ihr weiterhin 100 Kartenpunkte.`,{trump:`ROSE`,badges:[`Ansage: Rose 100`,`Doppel · x2`],bubbles:{OST:`Doppel!`}}),{t:`choose`,text:`{OST} hat gedoppelt. Du darfst jetzt kontern, dann zählen die Zielpunkte vierfach: 400. Fünf Trümpfe mit Puur und Nell, dazu zwei Asse. Was machst du?`,tip:`Holt ihr die 100, schreibt ihr 400 zu euren Kartenpunkten. Verfehlt ihr sie, schreiben die Gegner die 400.`,options:[{id:`RE`,label:`Kontern (x4)`},{id:`PASS`,label:`Stehen lassen (x2)`}],answer:`RE`,wrong:{PASS:`Du hast ein riesiges Blatt: Puur und Nell ziehen die Trümpfe, dann kommen deine Asse. Hier lohnt sich das Kontern.`},fx:{badges:[`Ansage: Rose 100`,`Konter · x4`],bubbles:{SUED:`Konter!`}}},{t:`play`,seat:`SUED`,code:`RU`,riddle:!0,text:`Als Ansager spielst du aus. Welche Karte?`,wrong:{RA:`Das Ass ist nicht der höchste Trumpf. Zuerst muss der Puur kommen: Er holt dir Stich und Zehn der Gegner.`,R9:`Das Nell ist stark, aber der Puur ist stärker. Fang mit dem Rosen-Under an.`,"*":`Zuerst gehört der Trumpf auf den Tisch, und zwar der höchste: der Puur, das Rosen-Under.`}},{t:`play`,seat:`OST`,code:`R10`},{t:`play`,seat:`NORD`,code:`R8`,text:`{NORD} bedient mit der Rosen 8. Der Puur gewinnt: 30 Punkte für euch.`},{t:`play`,seat:`WEST`,code:`S6`,text:`{WEST} hat keine Rosen mehr und wirft ab.`},{t:`play`,seat:`SUED`,code:`R9`,riddle:!0,text:`Du hast den Stich gemacht und spielst wieder aus. Welche Karte?`,wrong:{EA:`Die Gegner haben noch Trümpfe. Spielst du jetzt das Eichel-Ass, kann dich einer stechen. Zuerst müssen die Trümpfe weg, und der nächste ist das Nell.`,"*":`Zieh weiter Trumpf: Nach dem Puur ist das Nell der höchste Trumpf.`}},{t:`play`,seat:`OST`,code:`RO`},{t:`play`,seat:`NORD`,code:`R6`},{t:`play`,seat:`WEST`,code:`L8`,text:`{WEST} wirft eine wertlose Karte ab. Jetzt hat keiner der Gegner mehr Trumpf.`},{t:`play`,seat:`SUED`,code:`EA`,text:`Kein Gegner hat mehr Trumpf, also sind deine Asse sicher. Das Eichel-Ass gewinnt.`,tip:`Bei Sidi Barrani darfst du auch trumpfen, obwohl du die Farbe hast («eingeschränkter Farbzwang»).`,wrong:{"*":`Spiel das Eichel-Ass.`}},{t:`play`,seat:`OST`,code:`E9`},{t:`play`,seat:`NORD`,code:`E6`},{t:`play`,seat:`WEST`,code:`E7`},e(`Dein Team hat schon 58 Punkte. Holt ihr die 100, schreibt ihr die Zielpunkte zu euren Kartenpunkten, gekontert 400. Verfehlt ihr sie, schreiben die Gegner die 400. Die Kartenpunkte selbst werden nie vervielfacht. Gespielt wird bis 1500.`,`Merksatz: Erst ehrlich bieten, dann Trumpf ziehen, dann die Asse kassieren.`)]},{regionId:`GRAUBUENDEN`,kind:`trick`,title:`Sidi Barrani`,lesson:`Gegen die Ansage: Doppeln`,ziele:[`Das Doppeln abwägen`,`Aus dem Gebot Karten erraten`,`Den Nell mit dem Puur fangen`,`Abrechnen, wenn die Ansage fällt`],zielAt:[3,8,12,25],einstieg:`Als Gegner hast du es gar nicht schlecht. Schau, was du tun kannst.`,order:t,firstLeader:`OST`,score:`teams`,target:70,hands:{SUED:`RU R7 EA E9 SA S8 LA L8 L6`,OST:`R9 RA RK R10 E6 EO LU R8 R6`,NORD:`L9 L7 S9 LO S7 S6 L10 RO E7`,WEST:`S10 EK EU SK SU E10 E8 LK SO`},steps:[e(`Dritte Hand. Diesmal bist du nicht Spielübernehmer, sondern Gegner, und das ist keine schlechtere Rolle. {OST} hat als Erster geboten: Rose 70.`,`Rose 70 steht in der Nell-Reihe: das Nell und mindestens vier Rosen, aber nicht der Puur. Wer den Puur hat, sagt ihn an.`,{badges:[`Gebot: Rose 70`],bubbles:{OST:`Rose 70`}}),{t:`choose`,text:`Du bist dran. Du hast den Puur und die Rosen 7, dazu drei Asse (Eichel, Schelle, Schilte). Was machst du?`,tip:`Zwei Rosen sind kein Trumpfblatt. Aber der Puur ist eine Karte, an der niemand vorbeikommt.`,options:[{id:`ROSE75`,label:`Rose 75`,suit:`ROSE`},{id:`OBEN75`,label:`Obenabe 75`},{id:`FORT`,label:`Fort`}],answer:`FORT`,wrong:{ROSE75:`Mit zwei Rosen überbietest du niemanden. Der Puur allein macht kein Trumpfblatt.`,OBEN75:`Drei Asse sind schön, aber für Obenabe 75 reicht das nicht. Dein Blatt hat zu viele kleine Karten.`},fx:{bubbles:{SUED:`Fort`,NORD:`Fort`,WEST:`Fort`}}},e(`Alle steigen aus, {OST} ist Ansager mit Rose 70. Jetzt dürfen die Gegner doppeln. Zuerst ist {NORD} dran. Er lässt es bleiben.`,null,{trump:`ROSE`,badges:[`Ansage: Rose 70`],bubbles:{NORD:`Kein Doppel`}}),{t:`choose`,text:`Jetzt du. Aus seinem Gebot weisst du: {OST} hat das Nell, aber nicht den Puur. Den Puur hast du. Doppeln?`,tip:`Ein Doppel verdoppelt die Zielpunkte. Der Spielübernehmer darf dann kontern.`,options:[{id:`DOPPEL`,label:`Doppeln (x2)`},{id:`PASS`,label:`Kein Doppel`}],answer:`DOPPEL`,wrong:{PASS:`Überleg: Der Puur zählt 20 Punkte und schlägt jeden Trumpf, auch das Nell von {OST}. Wer 70 verspricht und den Puur nicht hat, braucht viel Glück. Doppeln lohnt sich.`},fx:{badges:[`Ansage: Rose 70`,`Doppel · x2`],bubbles:{SUED:`Doppel!`,OST:`Hmpf. Stehen lassen.`}}},e(`Vor dem ersten Stich wird gewiesen. {OST} zeigt einen Dreiblatt in Rose (8, 9, 10): 20. {WEST} zeigt einen Vierblatt in Schelle (10 bis König): 50. Der stärkere Weis gewinnt, die 50 gehen an euch.`,`Weis zählt für die Partie, aber nicht fürs Gebot: {OST} braucht weiterhin 70 Kartenpunkte, und eure 50 helfen ihm nicht beim Verfehlen.`,{bubbles:{OST:`Dreiblatt`,WEST:`Vierblatt!`}}),{t:`play`,seat:`OST`,code:`R9`,text:`{OST} spielt aus und eröffnet mit dem Nell. Er hofft, dass der Puur nicht bei dir sitzt.`,fx:{bubbles:{}}},{t:`play`,seat:`NORD`,code:`RO`,text:`{NORD} muss Rose bedienen und hat nur den Ober.`},{t:`play`,seat:`WEST`,code:`S10`,text:`{WEST} glaubt, das Nell seines Partners gewinnt, und schiebt ihm die Schellen 10 zu. Das nennt man schmieren.`},{t:`play`,seat:`SUED`,code:`RU`,riddle:!0,text:`Der Stich liegt offen vor dir. Welche Karte spielst du?`,wrong:{R7:`Mit der Sieben schenkst du {OST} den Stich samt Zehn. Du hast doch den Puur: Er schlägt das Nell.`,"*":`Du kannst Rose bedienen, und dein Puur schlägt jede Karte in diesem Stich. Spiel ihn.`}},{t:`choose`,text:`Gewonnen! Rechne nach: Nell 14, Ober 3, Zehn 10 und dein Puur 20. Wie viele Punkte bringt der Stich?`,options:[{id:`P37`,label:`37`},{id:`P47`,label:`47`},{id:`P57`,label:`57`}],answer:`P47`,wrong:{P37:`Da fehlen 10. Zähl die Zehn der Schellen noch mit.`,P57:`Zu viel. 14 plus 3 plus 10 plus 20 sind 47.`}},{t:`choose`,text:`Du spielst gleich das Eichel-Ass aus. {OST} hat noch zwei Eicheln auf der Hand. Darf er trotzdem trumpfen?`,options:[{id:`JA`,label:`Ja, bei Sidi Barrani darf man trumpfen, auch wenn man die Farbe hat`},{id:`NEIN`,label:`Nein, Farbe bedienen geht vor`}],answer:`JA`,wrong:{NEIN:`Doch. Wer die Farbe hat, darf trotzdem trumpfen, wenn er will. Verboten ist nur das Untertrumpfen: Wer trumpft, muss höher trumpfen als der Stich.`}},{t:`play`,seat:`SUED`,code:`EA`,text:`Probier es aus. Du spielst das Eichel-Ass.`,tip:`Hier geht es nicht um die beste Karte, sondern um die Regel.`,wrong:{"*":`Spiel das Eichel-Ass.`}},{t:`play`,seat:`OST`,code:`R6`,text:`Siehst du? {OST} hat Eicheln, trumpft trotzdem mit der Rosen 6 und sticht dein Ass.`},{t:`play`,seat:`NORD`,code:`E7`},{t:`play`,seat:`WEST`,code:`E10`,text:`{WEST} schmiert seinem Partner wieder die Zehn zu. 21 Punkte für {OST}. Lehre: Gegen einen Ansager mit vielen Trümpfen sind Asse nicht sicher.`},{t:`replay`,tricks:[`RA L9 EK R7`,`RK L7 SK E9`],text:`{OST} zieht Trümpfe: Rosen-Ass und Rosen-König. Du musst bedienen und gibst die Rosen 7, dann wirfst du die Eichel 9 ab. Die Stiche gehen an {OST}.`},{t:`replay`,tricks:[`R10 S6 LK L6`,`R8 S7 SO L8`,`EO S9 EU S8`],text:`{OST} spielt seine letzten Trümpfe aus. {WEST} wirft Punkte ab, ihr werft Kleinzeug. Die Stiche gehen alle an {OST}. Bis jetzt hat er 66 Punkte gemacht. Ihm fehlen noch vier.`},{t:`play`,seat:`OST`,code:`LU`,text:`{OST} hat keine Trümpfe mehr und spielt den Schilten-Under aus.`},{t:`play`,seat:`NORD`,code:`L10`,text:`{NORD} legt die Zehn zu deinem Ass.`},{t:`play`,seat:`WEST`,code:`SU`},{t:`play`,seat:`SUED`,code:`LA`,text:`Dein Schilten-Ass fängt Under, Zehn und den Schellen-Under ein: 25 Punkte.`},{t:`play`,seat:`SUED`,code:`SA`,text:`Den letzten Stich spielst du mit dem Schellen-Ass aus. Er bringt 5 Punkte extra.`},{t:`play`,seat:`OST`,code:`E6`},{t:`play`,seat:`NORD`,code:`LO`},{t:`play`,seat:`WEST`,code:`E8`},{t:`choose`,text:`{OST} hat 66 Punkte gemacht, er hatte aber 70 versprochen. Wem schreibt man die Ansage gut?`,options:[{id:`ANSAGER`,label:`Dem Ansager, er hat ja geboten`},{id:`GEGNER`,label:`Den Gegnern des Ansagers, also dir und deinem Partner`}],answer:`GEGNER`,wrong:{ANSAGER:`Verfehlt der Ansager sein Gebot, bekommen es die Gegner. Der Ansager behält nur die Punkte, die er erspielt hat.`}},e(`Abrechnung: Dein Team hat 91 Kartenpunkte (86 und 5 für den letzten Stich). Dazu kommen die Zielpunkte, gedoppelt 140, und der Vierblatt von {WEST}, 50: zusammen 281. {OST} schreibt nur seine 66. Es war knapp, nur vier Punkte, aber der Puur hat es entschieden.`,`Merksatz: Hör beim Bieten genau hin. Wer in der Nell-Reihe eröffnet, hat den Puur nicht, und hast du ihn, lohnt sich das Doppeln oft. Eine Garantie ist es nie.`)]},{regionId:`GRAUBUENDEN`,kind:`trick`,title:`Sidi Barrani`,lesson:`Obenabe ansagen`,ziele:[`Ein Obenabe-Blatt einschätzen`,`Wissen, was die Acht zählt`,`Mit den Assen beginnen`,`Die Abrechnung verstehen`],zielAt:[2,5,10,23],einstieg:`Ganz ohne Trumpf, nur Asse und Mut. Das macht Spass.`,order:t,score:`teams`,target:75,hands:{SUED:`EA EK E10 SA S10 RA R8 LA L6`,OST:`RO EU EO L7 LU L9 L10 R9 R7`,NORD:`E6 SO E9 L8 E8 LK SU S7 S9`,WEST:`E7 RU S6 S8 SK RK R6 LO R10`},steps:[e(`Vierte Hand. Statt Trumpf kannst du auch «Obenabe» bieten: Dann gibt es keinen Trumpf, und in jeder Farbe ist das Ass die höchste Karte. Das Ansage-System kennt Obenabe nicht, die Zahl sagt hier nur, was du dir zutraust.`,`Bei Obenabe zählt die Acht 8 Punkte. Sonst gelten die gewohnten Werte: Ass 11, Zehn 10, König 4, Ober 3, Under 2.`),{t:`choose`,text:`Schau dir deine Hand an: Vier Asse, nämlich Eichel, Schelle, Rose und Schilte. Wie viele Punkte bringen dir die Asse, wenn du sie ausspielst?`,options:[{id:`A33`,label:`33`},{id:`A44`,label:`44`},{id:`A55`,label:`55`}],answer:`A44`,wrong:{A33:`Vier Asse, jedes 11: Das sind 44. Dazu kommen die Karten, die die anderen dazulegen.`,A55:`Zu viel. Jedes Ass ist 11 Punkte wert: 4 mal 11 sind 44. Mehr kommt von den Karten, die die anderen dazulegen.`}},{t:`choose`,text:`Was bietest du?`,tip:`Das erste Gebot muss 50 oder mehr sein, danach geht es in 5er-Schritten.`,options:[{id:`OB55`,label:`Obenabe 55`},{id:`OB75`,label:`Obenabe 75`},{id:`OB100`,label:`Obenabe 100`}],answer:`OB75`,wrong:{OB55:`Das schaffst du im Schlaf, aber du verschenkst Punkte: Geschrieben wird genau das Gebot. Trau dir mehr zu.`,OB100:`Hoch gegriffen. 100 von 157 Punkten schaffen auch gute Blätter selten. Biete, was du sicher holst, plus ein bisschen Mut.`},fx:{badges:[`Gebot: Obenabe 75`],bubbles:{SUED:`Obenabe 75`,OST:`Fort`,NORD:`Fort`,WEST:`Fort`}}},e(`Alle steigen aus, du bist Spielübernehmer mit Obenabe 75. Die Gegner dürfen doppeln. Sie trauen sich nicht. Dann spielst du aus.`,null,{trump:`OBENABE`,badges:[`Ansage: Obenabe 75`],bubbles:{OST:`Kein Doppel`,WEST:`Kein Doppel`}}),e(`Vor dem ersten Stich wird gewiesen: {OST} hat einen Dreiblatt in Schilte (9, 10, Under) und schreibt 20. Für dein Gebot ändert das nichts: Die 75 müsst ihr mit Kartenpunkten holen, und der Weis der Gegner zählt nicht dagegen.`,null,{bubbles:{OST:`Dreiblatt`}}),{t:`choose`,text:`Kurz zur Regel: Wie viele Punkte zählt die Acht bei Obenabe?`,options:[{id:`A0`,label:`0 Punkte`},{id:`A8`,label:`8 Punkte`},{id:`A10`,label:`10 Punkte`}],answer:`A8`,wrong:{A0:`Beim Farbtrumpf zählt sie nichts. Bei Obenabe aber 8 Punkte, merk dir das.`,A10:`Die Zehn zählt 10. Die Acht zählt 8.`}},{t:`play`,seat:`SUED`,code:`EA`,text:`Du spielst aus. Fang mit den Assen an: Ohne Trumpf kann dir keiner ein Ass stechen.`,tip:`Asse und Könige zuerst, solange die anderen die Farbe noch bedienen müssen.`,wrong:{"*":`Spiel das Eichel-Ass.`},fx:{bubbles:{}}},{t:`play`,seat:`OST`,code:`EU`},{t:`play`,seat:`NORD`,code:`E8`,text:`{NORD} ist dein Partner und schiebt dir die Eichel 8 zu: 8 Punkte, denn die Acht zählt hier etwas.`},{t:`play`,seat:`WEST`,code:`E7`},{t:`replay`,tricks:[`SA L7 SO S6`,`RA R9 L8 R6`,`LA L9 LK LO`],text:`Schelle, Rose und Schilte gehen genauso: Du spielst jeweils das Ass, {NORD} legt Punkte dazu. Nach vier Stichen hat dein Team 72 Punkte.`},{t:`play`,seat:`SUED`,code:`EK`,riddle:!0,text:`Du hast noch fünf Karten: Eichel-König, Eichel 10, Schellen 10, Rosen 8 und Schilten 6. Welche spielst du aus?`,tip:`Schau, was in den anderen Händen noch steckt.`,wrong:{E10:`Der Eichel-Ober von {OST} schlägt die Zehn. Zuerst muss der König ran.`,S10:`Der Schellen-König von {WEST} schlägt die Zehn. Verschenk sie nicht.`,R8:`Der Ober von {OST} schlägt die Acht, und die Acht zählt 8 Punkte. Verschenk sie nicht.`,"*":`Mit der 6 holst du nichts. Der Eichel-König ist ein sicherer Stich, und er räumt den Ober von {OST} weg.`}},{t:`play`,seat:`OST`,code:`EO`,text:`{OST} muss den Eichel-Ober legen. Jetzt ist die Zehn die höchste Eichel!`},{t:`play`,seat:`NORD`,code:`E9`},{t:`play`,seat:`WEST`,code:`RU`},{t:`play`,seat:`SUED`,code:`E10`,text:`Die Eichel 10 gewinnt den nächsten Stich.`,wrong:{"*":`Spiel jetzt die Eichel 10: Sie ist die höchste Eichel.`}},{t:`play`,seat:`OST`,code:`R7`},{t:`play`,seat:`NORD`,code:`E6`},{t:`play`,seat:`WEST`,code:`RK`,text:`{WEST} hat keine Eichel mehr und wirft den Rosen-König ab.`},{t:`play`,seat:`SUED`,code:`L6`,riddle:!0,text:`Dir bleiben drei Karten: Schellen 10, Rosen 8 und Schilten 6. Alle drei verlieren. Welche gibst du zuerst her?`,tip:`Wenn du verlierst, verlier so wenig wie möglich.`,wrong:{S10:`Die Zehn ist 10 Punkte wert und verliert gegen den Schellen-König von {WEST}. Behalt sie lieber noch.`,R8:`Die Acht ist 8 Punkte wert. Die Schilten 6 ist wertlos: Gib die zuerst her.`}},{t:`play`,seat:`OST`,code:`L10`,text:`{OST} gewinnt mit der Schilten 10 den Stich, und {WEST} schiebt ihm die Rosen 10 zu.`},{t:`play`,seat:`NORD`,code:`S7`},{t:`play`,seat:`WEST`,code:`R10`},{t:`replay`,tricks:[`RO S9 S8 R8`,`LU SU SK S10`],text:`Die letzten zwei Stiche gehen an {OST}: Du musstest die Rosen 8 und die Schellen 10 hergeben. Der letzte Stich bringt 5 Punkte extra, und die hat {OST}.`},e(`Abrechnung: Dein Team hat 95 Kartenpunkte, mehr als die gebotenen 75. Also schreibt ihr 75 plus 95: 170. Die Gegner schreiben 62 und ihren Weis, 82. Hinter den vier Assen kam nicht mehr viel, drei Stiche gingen verloren. Aber es hat gereicht.`,`Merksatz: Bei Obenabe zuerst die Asse, dann die Könige, wenn der Ober noch draussen ist. Und achte auf die Acht: Sie zählt hier 8 Punkte.`)]}],_=[{regionId:`THURGAU`,kind:`hoseabe`,title:`Hose-Abe`,lesson:`Tauschen und zählen`,ziele:[`Die Hand zählen`,`Eine Karte gezielt tauschen`,`Die Hand verbessern`,`Wissen, wer ein Leben verliert`],zielAt:[2,5,11,12],einstieg:`Hose-Abe ist ein flottes Spiel. Drei Karten, rasch gelernt.`,order:t,score:`none`,hands:{SUED:`RK L9 E6`,OST:`LK LU E8`,NORD:`LA L7 E7`,WEST:`EA E9 S6`},middle:`RA R10 L8`,steps:[e(`Hose-Abe, auf Thurgauer Art. Jeder hat drei Karten, drei weitere liegen offen in der Mitte. Reihum tauschst du mit der Mitte und willst möglichst nah an 31 Punkte heran. Zählen darfst du aber nur Karten derselben Farbe.`,`Es geht gegen den Uhrzeigersinn: du, dann {OST}, {NORD}, {WEST}.`),e(`Die Werte sind schnell gelernt: Ass 11, König, Ober, Under und Zehn je 10, die Neun 9, die Acht 8, die Sieben 7, die Sechs 6. Ass und zwei Zehner-Werte in einer Farbe, das macht 31, mehr gibt es nicht. Dann zähl einmal deine Hand.`),{t:`choose`,text:`Du hast Rosen König, Schilte 9 und Eichel 6. Wie viele Punkte hat deine Hand?`,tip:`Nur die beste Farbe zählt, die anderen Karten bringen nichts.`,options:[{id:`P10`,label:`10 Punkte`},{id:`P25`,label:`25 Punkte`},{id:`P9`,label:`9 Punkte`}],answer:`P10`,wrong:{P25:`Hmpf, nicht alles zusammenzählen. 10 + 9 + 6 sind zwar 25, aber es sind drei verschiedene Farben. Nur Karten gleicher Farbe zählen, und von den Rosen hast du bloss den König: 10.`,P9:`Die Schilte 9 ist zwar eine hohe Einzelkarte, aber der Rosen König ist mit 10 Punkten deine beste.`}},e(`Genau. Und in der Mitte liegen Rosen Ass (11) und Rosen Zehn (10). Das passt zu deinem König, siehst du es?`),{t:`choose`,text:`Du bist am Zug. Du darfst eine Karte tauschen, alle drei tauschen oder schieben. Was machst du?`,tip:`Alle drei tauschen lohnt sich nur, wenn die ganze Mitte besser ist als deine Hand. Wer schiebt, löst die letzte Runde aus: Alle anderen haben dann noch genau einen Zug.`,options:[{id:`ONE`,label:`Eine Karte tauschen`},{id:`ALL`,label:`Alle drei tauschen`},{id:`PASS`,label:`Schieben`}],answer:`ONE`,wrong:{ALL:`Die Mitte hat Rosen Ass, Rosen Zehn und die Schilte 8. Nähmst du alle drei, bekämst du zwar zwei Rosen, aber du gäbest deinen Rosen König her und bekämst dafür die nutzlose Schilte 8. Behalte den König und tausche nur eine Karte.`,PASS:`Mit 10 Punkten schieben? Dann hast du die schlechteste Hand am Tisch und gibst allen anderen noch einen Zug. Tausche lieber.`}},{t:`swap`,seat:`SUED`,hand:`L9`,mid:`RA`,text:`Gib die Schilte 9 weg, die nützt dir nichts. Tippe sie an und nimm dann das Rosen-Ass aus der Mitte.`,tip:`Tausche immer eine Karte, die nicht zu deiner besten Farbe gehört.`,wrong:{"*":`Tausche die Schilte 9 gegen das Rosen-Ass.`}},{t:`swap`,seat:`OST`,hand:`E8`,mid:`L9`,text:`{OST} hat Schilten König und Under, das sind 20 Punkte. Er tauscht seine Eichel 8 gegen die Schilte 9, die du eben abgelegt hast, und steht bei 29. Merk dir: Was du weggibst, kann der Nächste brauchen.`},{t:`swap`,seat:`NORD`,hand:`E7`,mid:`L8`},{t:`swap`,seat:`WEST`,hand:`S6`,mid:`E8`,text:`{WEST} sammelt Eicheln: Ass, Neun und Acht, das sind 28 Punkte.`},e(`Wieder du. Rosen König und Ass bringen dir 21 Punkte. In der Mitte liegt noch eine Karte, die dich zum Ziel bringt.`),{t:`choose`,text:`Welche Karte aus der Mitte brauchst du für die volle Hand?`,tip:`Die Mitte: Rosen Zehn, Eichel 7, Schelle 6.`,options:[{id:`R10`,label:`Rosen Zehn`,code:`R10`},{id:`E7`,label:`Eichel 7`,code:`E7`},{id:`S6`,label:`Schelle 6`,code:`S6`}],answer:`R10`,wrong:{E7:`Die Eichel 7 ist keine Rose, sie zählt zu deinem Ass und König gar nicht. Du suchst eine Rose.`,S6:`Eine Schelle bringt dir bei den Rosen nichts. Du brauchst eine Rose, und zwar eine mit 10 Punkten.`}},{t:`swap`,seat:`SUED`,hand:`E6`,mid:`R10`,text:`Gib die Eichel 6 her und nimm die Rosen Zehn: König, Ass und Zehn, macht 31.`,tip:`31 Punkte in einer Farbe heissen «Hose-Abe» und beenden die Runde sofort.`,wrong:{"*":`Tausche die Eichel 6 gegen die Rosen Zehn.`}},{t:`choose`,text:`Hose-Abe, die Runde ist aus. Wer von den anderen hat am wenigsten Punkte und verliert ein Leben?`,tip:`Zähl die beste Farbe jedes Mitspielers.`,options:[{id:`OST`,label:`{OST}`,sub:`Schilten König, Under, 9`},{id:`NORD`,label:`{NORD}`,sub:`Schilten Ass, 8, 7`},{id:`WEST`,label:`{WEST}`,sub:`Eichel Ass, 9, 8`}],answer:`NORD`,wrong:{OST:`{OST} hat 10 + 10 + 9, das sind 29. Das ist ordentlich.`,WEST:`{WEST} hat 11 + 9 + 8 = 28. Knapp, aber es gibt noch einen Tieferen.`}},e(`Bei {NORD} sind es 11 + 8 + 7, also 26, und das ist das Wenigste. {NORD} verliert ein Leben. Wer das letzte Leben verliert, muss «schwimmen». Merk dir: Zähl nur die beste Farbe, tausche, was nicht dazugehört, und gib dem Nächsten nichts, was er braucht.`)]},{regionId:`THURGAU`,kind:`hoseabe`,title:`Hose-Abe`,lesson:`Alle tauschen, schieben`,ziele:[`Den Handwert ausrechnen`,`Alle drei Karten tauschen`,`Schieben, wenn die Hand gut ist`,`Wissen, wer ein Leben verliert`],zielAt:[2,4,10,12],einstieg:`Manchmal hilft nur ein grosser Tausch. Ich zeig dir wann.`,order:t,score:`none`,hands:{SUED:`R6 S7 L8`,OST:`SK S8 L6`,NORD:`RK RO R7`,WEST:`LA L10 R9`},middle:`EA E10 E9`,steps:[e(`Zweite Hand, zweite Lehre. Manchmal hilft ein einzelner Tausch nicht weiter. Dann tauschst du gleich alle drei Karten, oder du schiebst, wenn du vorne liegst. Schau dir an, woran du das merkst.`),{t:`choose`,text:`Deine Hand: Rose 6, Schelle 7, Schilte 8. Wie viele Punkte hast du?`,tip:`Drei verschiedene Farben: Es zählt nur die beste Karte.`,options:[{id:`P8`,label:`8 Punkte`},{id:`P21`,label:`21 Punkte`},{id:`P6`,label:`6 Punkte`}],answer:`P8`,wrong:{P21:`Das sind drei verschiedene Farben, die darfst du nicht zusammenzählen. Es zählt nur die beste einzelne Karte: die Schilte 8.`,P6:`Die Sechs ist deine schwächste Karte. Es zählt die stärkste, und das ist die Schilte 8.`}},{t:`choose`,text:`In der Mitte liegen Eichel Ass, Eichel Zehn und Eichel Neun. Wie viele Punkte wären das, wenn du alle drei nähmst?`,tip:`Alle drei sind Eicheln: Die zählen zusammen.`,options:[{id:`P30`,label:`30 Punkte`},{id:`P11`,label:`11 Punkte`},{id:`P19`,label:`19 Punkte`}],answer:`P30`,wrong:{P11:`Das Ass allein ja, aber alle drei sind Eicheln und zählen zusammen: 11 + 10 + 9.`,P19:`10 + 9 hast du, aber das Ass fehlt in deiner Rechnung. 11 + 10 + 9.`}},{t:`choose`,text:`Mit einer einzelnen Karte tauschen kämst du auf 11, mit allen dreien auf 30. Und schieben? Was tust du?`,tip:`Wenn die ganze Mitte zusammenpasst und besser ist als alles, was du hast, nimm sie ganz.`,options:[{id:`ONE`,label:`Eine Karte tauschen`},{id:`ALL`,label:`Alle drei tauschen`},{id:`PASS`,label:`Schieben`}],answer:`ALL`,wrong:{ONE:`Ein Tausch bringt dir das Ass, aber deine beiden anderen Karten sind keine Eicheln. Du stündest bei 11. Nimm die ganze Mitte.`,PASS:`Schieben mit 8 Punkten? Dann bist du der Schwächste am Tisch und schenkst den anderen noch einen Zug.`}},{t:`swapall`,seat:`SUED`,text:`Tippe auf «Alle tauschen»: Deine drei Karten gehen in die Mitte, die drei Eicheln gehören dir.`,tip:`Alle tauschen heisst nur: ein einziger Zug, aber du holst dir die beste Mitte.`},{t:`swap`,seat:`OST`,hand:`L6`,mid:`S7`,text:`{OST} hat Schellen König und Acht. Er tauscht die Schilte 6 gegen die Schelle 7, die du eben hineingelegt hast, und kommt auf 25.`},{t:`pass`,seat:`NORD`,text:`{NORD} hat Rosen König, Ober und Sieben, das sind 27 Punkte, und schiebt. Zufrieden mit der Hand löst er die letzte Runde aus.`},{t:`choose`,text:`{NORD} hat geschoben. Wer darf jetzt noch einmal ziehen?`,tip:`Es zählen alle, die nicht geschoben haben, auch wer vorhin schon dran war.`,options:[{id:`ALL`,label:`Jeder der anderen noch einmal`},{id:`ME`,label:`Nur du`},{id:`NONE`,label:`Niemand mehr`}],answer:`ALL`,wrong:{ME:`Nicht nur du. Wer schiebt, schenkt allen anderen noch genau einen Zug.`,NONE:`Doch, jeder bekommt noch einen letzten Zug. Darum schiebt man erst, wenn man vorne liegt.`}},{t:`swap`,seat:`WEST`,hand:`R9`,mid:`L8`,text:`{WEST} nutzt den letzten Zug: Schilten Ass und Zehn plus die Schilte 8 aus der Mitte machen 29.`},{t:`choose`,text:`Das ist dein letzter Zug. Du hast 30 Punkte, {WEST} 29, {NORD} 27, {OST} 25. Was machst du?`,tip:`In der Mitte liegen jetzt Rose 6, Schilte 6 und Rose 9.`,options:[{id:`PASS`,label:`Schieben`},{id:`ONE`,label:`Eine Karte tauschen`},{id:`ALL`,label:`Alle drei tauschen`}],answer:`PASS`,wrong:{ONE:`In der Mitte liegt nichts Gutes mehr für deine Eicheln. Du würdest dich nur verschlechtern.`,ALL:`Deine Hand ist die beste am Tisch, gib sie nicht her.`}},{t:`pass`,seat:`SUED`,text:`Dann schieb. Dein Blatt bleibt, wie es ist.`,tip:`Auch im letzten Zug darfst du schieben.`,wrong:{"*":`Hier schiebst du am besten: Tippe auf «Schieben».`}},{t:`pass`,seat:`OST`,text:`{OST} findet nichts Besseres und schiebt ebenfalls. Damit ist die letzte Runde zu Ende.`},e(`Abgerechnet: Du 30, {WEST} 29, {NORD} 27, {OST} 25. {OST} hat am wenigsten und verliert ein Leben. Merk dir: Passt die ganze Mitte, tausch alle drei. Und liegst du vorne, schieb.`)]},{regionId:`THURGAU`,kind:`hoseabe`,title:`Hose-Abe`,lesson:`Gegner lesen`,ziele:[`Die Hände der Gegner mitlesen`,`Dem Gegner Karten wegnehmen`,`Den Dreiling kennen`,`Mit 31 Punkten sofort gewinnen`],zielAt:[2,4,6,10],einstieg:`Jetzt denkst du mit. Schau, was die anderen vorhaben.`,order:t,score:`none`,hands:{SUED:`RK R7 L6`,OST:`EK SK E8`,NORD:`EA SA L7`,WEST:`SO S10 L9`},middle:`RA R10 LK`,steps:[e(`Dritte Hand, jetzt wird mitgedacht. Alle Karten liegen offen, nutz das aus: Schau nicht nur auf deine Hand, sondern auch, was die anderen vorhaben. Es gibt nämlich zwei Sonderfälle: den Dreiling und die drei Asse.`),{t:`choose`,text:`Wer von den dreien hat schon zwei Asse in der Hand?`,tip:`Schau auf die Karten der Mitspieler.`,options:[{id:`OST`,label:`{OST}`},{id:`NORD`,label:`{NORD}`},{id:`WEST`,label:`{WEST}`}],answer:`NORD`,wrong:{OST:`{OST} hat zwei Könige, aber kein Ass.`,WEST:`{WEST} hat Schelle Ober, Schelle Zehn und Schilte 9. Kein einziges Ass.`}},{t:`choose`,text:`In der Mitte liegt das Rosen-Ass. Was passiert, wenn {NORD} es bekommt und damit drei Asse hält?`,tip:`Drei Asse sind eine Sonderregel.`,options:[{id:`ALLOTHERS`,label:`Alle anderen verlieren ein Leben`},{id:`LOWEST`,label:`Nur der mit der tiefsten Hand verliert`},{id:`POINTS`,label:`Er hat 33 Punkte`}],answer:`ALLOTHERS`,wrong:{LOWEST:`Nicht nur der Schwächste. Drei Asse beenden die Runde sofort, und alle anderen am Tisch verlieren ein Leben, du auch.`,POINTS:`33 Punkte gibt es nicht. Drei Asse sind eine Sonderregel: Die Runde ist sofort aus, und alle anderen zahlen ein Leben.`}},{t:`choose`,text:`Du hast Rosen König, Rosen 7 und Schilte 6. Welche Karte aus der Mitte nimmst du, damit {NORD} keine drei Asse bekommt?`,tip:`Du bist vor {NORD} am Zug. Wenn du ein Ass liegen lässt, nimmt {NORD} es sich vielleicht.`,options:[{id:`RA`,label:`Rosen Ass`,code:`RA`},{id:`R10`,label:`Rosen Zehn`,code:`R10`},{id:`LK`,label:`Schilten König`,code:`LK`}],answer:`RA`,wrong:{R10:`Die Zehn passt gut zu deinem Rosen König, schon. Aber dann liegt das Ass noch da, und {NORD} nimmt es und hat drei Asse. Du verlierst ein Leben, ohne dass du etwas dagegen tun kannst.`,LK:`Der Schilten König bringt dir nichts, und das Rosen-Ass bleibt für {NORD} liegen. Das wäre ein teurer Fehler.`}},{t:`swap`,seat:`SUED`,hand:`L6`,mid:`RA`,text:`Gib die Schilte 6 her und nimm das Ass. Du verbesserst dich auf 28 und lässt {NORD} mit leeren Händen stehen. Zwei Fliegen mit einer Klappe.`,tip:`Die beste Tauschkarte ist oft die, die dem Gegner fehlt.`,wrong:{"*":`Tausche die Schilte 6 gegen das Rosen-Ass.`}},{t:`swap`,seat:`OST`,hand:`E8`,mid:`LK`,text:`{OST} tauscht seine Eichel 8 gegen den Schilten König. Jetzt hat er König, König, König: einen Dreiling.`},{t:`choose`,text:`Wie viele Punkte zählt ein Dreiling, also drei gleiche Werte in drei Farben?`,tip:`Er liegt knapp unter der Bestmarke.`,options:[{id:`D30`,label:`30 Punkte`},{id:`D305`,label:`30,5 Punkte`},{id:`D31`,label:`31 Punkte`}],answer:`D305`,wrong:{D30:`Fast: Der Dreiling hat einen halben Punkt mehr.`,D31:`31 gibt es nur in einer Farbe, das ist Hose-Abe. Der Dreiling bleibt knapp darunter: 30,5 Punkte.`}},{t:`swap`,seat:`NORD`,hand:`L7`,mid:`E8`,text:`{NORD} hat ausgespielt: Das dritte Ass fehlt ihm, dank dir. Er nimmt noch die Eichel 8 und steht bei 19.`},{t:`pass`,seat:`WEST`,text:`{WEST} hat Schelle Ober und Zehn, 20 Punkte, und schiebt. Jetzt hat jeder der anderen noch einen letzten Zug, und du bist der Erste.`},{t:`choose`,text:`Du hast 28 Punkte, {OST} den Dreiling mit 30,5. Wie kommst du an ihm vorbei?`,tip:`Hose-Abe, also 31 Punkte in einer Farbe, schlägt alles, auch den Dreiling.`,options:[{id:`R10`,label:`Rosen 7 gegen Rosen Zehn tauschen`},{id:`ALL`,label:`Alle drei tauschen`},{id:`PASS`,label:`Schieben`}],answer:`R10`,wrong:{ALL:`Die Mitte besteht aus Rosen Zehn, Schilte 6 und Schilte 7. Das ist weniger als deine Hand. Tausche nur die Sieben.`,PASS:`Schieben ginge, du wärst nicht der Letzte. Aber du hast 31 in Reichweite, und Hose-Abe schlägt jeden Dreiling.`}},{t:`swap`,seat:`SUED`,hand:`R7`,mid:`R10`,text:`Gib die Rosen 7 her und nimm die Zehn: König, Ass und Zehn, macht 31.`,tip:`Hose-Abe beendet die Runde sofort, die anderen kommen nicht mehr dran.`,wrong:{"*":`Tausche die Rosen 7 gegen die Rosen Zehn.`}},e(`Hose-Abe! Du hast 31 und die Runde ist sofort aus. {OST} bleibt mit dem Dreiling bei 30,5, {WEST} hat 20, {NORD} 19. Am wenigsten hat {NORD}, er verliert ein Leben. Merk dir: Schau, was die Mitspieler brauchen. Und nimm ihnen die Karte weg, bevor sie sie sich holen.`)]}],v=[{regionId:`WALLIS`,kind:`tschausepp`,title:`Tschau Sepp`,lesson:`Farbe oder Wert`,ziele:[`Farbe oder Wert bedienen`,`Strafkarte mit Sieben oder Sechs kontern`,`Ass: gleich nochmals legen`,`«Tschau» sagen`],zielAt:[2,6,14,19],einstieg:`Zuerst das Einfache, Sepp: Farbe oder Wert, mehr brauchst du nicht.`,order:t,score:`none`,hands:{SUED:`R9 LU EA E6 SO`,OST:`R7 E8 EO LK RK`,NORD:`L7 EK L9 S10 RA`,WEST:`L6 E10 E9 S8 RO`},top:`S9`,pile:15,drawn:[`L8`],steps:[e(`Tschau Sepp, wie man es im Wallis spielt. Jeder hat fünf Karten, und wer sie zuerst alle los ist, gewinnt die Runde. Auf die oberste Karte legst du eine, die zur Farbe oder zum Wert passt. Oben liegt die Schellen 9, und du bist dran.`,`Die Sonderkarten lernst du unterwegs: 7 = Strafkarten, 8 = aussetzen, 10 = Richtungswechsel, Ass = nochmals legen, Under = Farbe wünschen.`),{t:`choose`,text:`Oben liegt die Schellen 9. Welche dieser Karten passt?`,tip:`Entweder die Farbe oder der Wert muss stimmen.`,options:[{id:`R9`,label:`Rosen 9`,code:`R9`},{id:`EA`,label:`Eichel Ass`,code:`EA`},{id:`E6`,label:`Eichel 6`,code:`E6`}],answer:`R9`,wrong:{EA:`Das Eichel-Ass ist weder eine Schelle noch eine 9. Es passt weder zur Farbe noch zum Wert.`,E6:`Die Eichel 6 ist weder eine Schelle noch eine 9. Such eine Karte, bei der die Farbe oder der Wert stimmt.`}},{t:`play`,seat:`SUED`,code:`R9`,text:`Gleicher Wert, andere Farbe, das geht. Mit der Rosen 9 bestimmst du die neue Farbe: Jetzt gilt Rose.`,tip:`Mit gleichem Wert kannst du die Farbe wechseln.`,wrong:{"*":`Diese Karte passt nicht: Es muss Schelle oder eine 9 sein. Lege die Rosen 9.`}},{t:`play`,seat:`OST`,code:`R7`,text:`{OST} legt die Rosen 7. Gleiche Farbe, und eine Sieben ist eine Strafkarte: {NORD} muss 2 Karten ziehen. Es sei denn, er hat selbst eine Sieben oder die Sechs der Farbe, die gerade gilt.`},{t:`choose`,text:`Gegen die Strafe darf {NORD} nur eine Sieben oder die Sechs der geltenden Farbe legen. Was hat er davon?`,tip:`Seine Karten: Schilten 7, Eichel König, Schilten 9, Schellen 10, Rosen Ass.`,options:[{id:`L7`,label:`Schilten 7`,code:`L7`},{id:`L9`,label:`Schilten 9`,code:`L9`},{id:`RA`,label:`Rosen Ass`,code:`RA`}],answer:`L7`,wrong:{L9:`Eine Neun hilft gegen eine Strafkarte nicht, da ist nur eine Sieben oder die Sechs erlaubt.`,RA:`Das Rosen-Ass hat zwar die Farbe, aber gegen eine Strafkarte zählt die Farbe nicht, nur Sieben oder Sechs.`}},{t:`play`,seat:`NORD`,code:`L7`,text:`{NORD} gibt die Strafe mit der Schilten 7 weiter. Für {WEST} wären es jetzt schon 4 Karten.`},{t:`play`,seat:`WEST`,code:`L6`,text:`{WEST} hat die Schilten 6, die Sechs der Farbe, die gerade gilt, und stoppt die ganze Kette. Niemand muss ziehen. Eine Sechs in einer anderen Farbe hätte nichts genützt.`},{t:`play`,seat:`SUED`,code:`LU`,color:`E`,riddle:!0,text:`Du bist am Zug, oben liegt die Schilten 6. Deine Hand: Eichel Ass, Eichel 6, Under, Schellen Ober. Welche Karte spielst du?`,wrong:{EA:`Das Eichel-Ass passt nicht auf die Schilten 6: weder Farbe noch Wert.`,E6:`Die Eichel 6 passt, ja, gleicher Wert. Aber du hast eine Karte, die dir die Farbe schenkt. Probier die andere.`,SO:`Der Schellen Ober hat weder die Farbe noch den Wert der Schilten 6.`,"*":`Das passt nicht auf die Schilten 6.`}},{t:`play`,seat:`OST`,code:`E8`,text:`Der Under darf auf jede Farbe, und du hast dir die Eichel gewünscht: Dort hast du Ass und Sechs. {OST} legt die Eichel 8. Eine Acht: {NORD} muss aussetzen, {WEST} ist gleich dran.`},{t:`play`,seat:`WEST`,code:`E10`,text:`{WEST} legt die Eichel 10. Eine Zehn dreht die Richtung um: Jetzt geht es andersherum weiter, {NORD}, {OST}, dann du.`},{t:`play`,seat:`NORD`,code:`EK`},{t:`play`,seat:`OST`,code:`EO`},{t:`choose`,text:`Du bist dran, oben liegt der Eichel Ober. Du hast Eichel Ass, Eichel 6 und Schellen Ober. Mit welcher Karte kommst du am weitesten?`,tip:`Jede dieser Karten passt: Zwei davon auf die Farbe, eine auf den Wert.`,options:[{id:`EA`,label:`Eichel Ass`,code:`EA`},{id:`E6`,label:`Eichel 6`,code:`E6`},{id:`SO`,label:`Schellen Ober`,code:`SO`}],answer:`EA`,wrong:{E6:`Das geht, aber du wirst damit nur eine Karte los. Mit dem Ass legst du zwei auf einmal.`,SO:`Der Schellen Ober passt zum Wert, aber die Farbe wechselt dann auf Schelle, und deine Eicheln stecken fest.`}},{t:`play`,seat:`SUED`,code:`EA`,text:`Das Ass: Du darfst gleich noch eine Karte legen, entweder derselben Farbe oder ein weiteres Ass. Das spart dir einen ganzen Umlauf.`,tip:`Hast du keine passende zweite Karte, musst du eine vom Stapel ziehen.`,wrong:{"*":`Lege das Eichel-Ass: Es passt zur Farbe und bringt dich gleich zwei Karten weiter.`}},{t:`play`,seat:`SUED`,code:`E6`,text:`Jetzt noch eine Eichel nachlegen: die Eichel 6.`,wrong:{"*":`Nach dem Ass muss eine Eichel-Karte folgen: Lege die Eichel 6.`}},{t:`play`,seat:`WEST`,code:`E9`},{t:`play`,seat:`NORD`,code:`L9`,text:`{NORD} legt eine Neun: Sie passt zum Wert der obersten Karte, die Farbe wechselt auf Schilte.`},{t:`play`,seat:`OST`,code:`LK`},{t:`draw`,seat:`SUED`,code:`L8`,text:`Du hast nur noch den Schellen Ober, und der passt nicht auf den Schilten König. Dann musst du eine Karte vom Stapel ziehen. Tippe auf den Nachziehstapel.`,tip:`Kannst du nicht legen, ziehst du eine Karte. Passt sie, darfst du sie sofort legen.`,wrong:{"*":`Diese Karte passt nicht: Es muss Schilte oder ein König sein. Tippe auf den Nachziehstapel.`}},{t:`play`,seat:`SUED`,code:`L8`,fx:{bubbles:{SUED:`Tschau!`}},text:`Die gezogene Schilten 8 passt zur Farbe, du darfst sie gleich legen. Jetzt hast du nur noch eine Karte, darum sagst du «Tschau!».`,wrong:{"*":`Lege die gezogene Schilten 8.`}},e(`So geht es weiter, bis einer keine Karten mehr hat. Wer zuerst fertig ist, gewinnt die Runde. Wer zuletzt noch Karten hält, verliert ein Leben, und sind alle Leben weg, wird «geschwommen». Merk dir: Farbe oder Wert, und kein Under ohne Grund.`)]},{regionId:`WALLIS`,kind:`tschausepp`,title:`Tschau Sepp`,lesson:`Strafkarten`,ziele:[`Die Sieben als Strafkarte kennen`,`Mit der Sechs der Farbe schützen`,`Aussetzen bei der Acht verstehen`,`Strafkarten zusammenzählen`],zielAt:[1,3,5,12],einstieg:`Die Sieben ist gemein, aber mit der Sechs im Ärmel bist du gewappnet.`,order:t,score:`none`,hands:{SUED:`S6 E6 EA LU SK`,OST:`S8 RK R9 E8 LA`,NORD:`R7 EK E10 L8 RA`,WEST:`S7 S9 L7 LO E9`},top:`S10`,pile:17,steps:[e(`Zweite Hand: die Strafkarten. Die Sieben ist die gemeinste Karte im Spiel, und die Sechs dein Schutzschild. Schau, wie eine Kette entsteht und wie du ihr entkommst.`,`Die Hand endet mit der Strafe: Hier wird gezogen, nicht mehr gelegt.`),{t:`choose`,text:`Was bewirkt eine gelegte Sieben?`,tip:`Die Acht, die Zehn und die Sieben sind drei verschiedene Sonderkarten.`,options:[{id:`STRAFE`,label:`Der Nächste zieht 2 Karten, wenn er nicht kontern kann`},{id:`AUSSETZEN`,label:`Der Nächste setzt aus`},{id:`RICHTUNG`,label:`Die Richtung wechselt`}],answer:`STRAFE`,wrong:{AUSSETZEN:`Aussetzen ist die Acht. Die Sieben ist die Strafkarte.`,RICHTUNG:`Den Richtungswechsel macht die Zehn. Die Sieben bedeutet Strafe: 2 Karten ziehen.`}},{t:`play`,seat:`WEST`,code:`S7`,text:`{WEST} legt die Schellen 7 auf die Schellen 10. Gleiche Farbe, erlaubt. Und jetzt kommst du, mit 2 Strafkarten vor der Nase.`},{t:`play`,seat:`SUED`,code:`S6`,riddle:!0,text:`Du hast keine Sieben. Deine Hand: Schellen 6, Eichel 6, Eichel Ass, Under, Schellen König. Wie kommst du ungeschoren davon?`,wrong:{E6:`Die Eichel 6 hilft nicht: Die Sechs muss die Farbe haben, die gerade gilt, und das ist Schelle.`,EA:`Gegen eine Strafkarte ist ein Ass nicht erlaubt. Da zählt nur Sieben oder die Sechs der Farbe.`,LU:`Der Under darf sonst überall hin, nur nicht auf eine Strafkarte.`,SK:`Die Schellen passt zwar zur Farbe, aber gegen die Sieben zählt nur Sieben oder die Sechs.`,"*":`Gegen die Sieben hilft nur eine Sieben oder die Sechs der Farbe.`}},{t:`play`,seat:`OST`,code:`S8`,text:`Die Schellen 6 fängt die Strafe ab: Sie musste die Farbe haben, die gerade gilt. Deine Eichel 6 hätte dich nicht gerettet. Jetzt geht es normal weiter, {OST} legt die Schellen 8. Eine Acht: Der Nächste setzt aus.`},{t:`choose`,text:`{OST} hat die Acht gelegt. Wer setzt jetzt aus?`,tip:`Die Reihenfolge ist: du, {OST}, {NORD}, {WEST}.`,options:[{id:`NORD`,label:`{NORD}`},{id:`WEST`,label:`{WEST}`},{id:`ME`,label:`Du`}],answer:`NORD`,wrong:{WEST:`{WEST} kommt als Nächster dran, weil {NORD} übersprungen wird.`,ME:`Du bist erst nach {WEST} wieder dran. Die Acht trifft den Nächsten nach {OST}.`}},{t:`play`,seat:`WEST`,code:`S9`,text:`{WEST} spielt weiter und legt die Schellen 9: gleiche Farbe, kein Problem.`},{t:`play`,seat:`SUED`,code:`SK`,text:`Du bist dran. Lege den Schellen König, gleiche Farbe, und deine Hand wird kleiner.`,tip:`Den Under spar dir besser auf, solange du nicht musst.`,wrong:{"*":`Spiele den Schellen König: Er passt zur Farbe, und den Under hebst du dir besser auf.`}},{t:`play`,seat:`OST`,code:`RK`,text:`{OST} legt den Rosen König. Gleicher Wert, andere Farbe: Das ist der Trick, mit dem man die Farbe wechselt, ohne den Under zu opfern.`},{t:`play`,seat:`NORD`,code:`R7`,text:`Und jetzt der Haken: {NORD} legt die Rosen 7 und startet eine neue Kette. 2 Karten Strafe für {WEST}.`},{t:`play`,seat:`WEST`,code:`L7`,text:`{WEST} hat selbst eine Sieben und gibt weiter. Jetzt sind es 4 Karten, und die Kette läuft auf dich zu.`},{t:`choose`,text:`Du hast Eichel 6, Eichel Ass und den Under. Was darfst du gegen die Kette legen?`,tip:`Gegen die Sieben zählt nur eine Sieben oder die Sechs der geltenden Farbe, und das ist Schilte.`,options:[{id:`NONE`,label:`Nichts davon`},{id:`UNDER`,label:`Den Under`,code:`LU`},{id:`E6`,label:`Die Eichel 6`,code:`E6`}],answer:`NONE`,wrong:{UNDER:`Der Under gilt sonst überall, nur gegen eine Strafkarte nicht. Da bleibt er stumm.`,E6:`Die Sechs rettet dich nur in der Farbe, die gerade gilt, und das ist Schilte. Deine Eichel 6 ist die falsche.`}},{t:`choose`,text:`Dann musst du die Strafe ziehen. Wie viele Karten sind es?`,tip:`Die Sieben von {NORD} hat 2 gebracht, die von {WEST} noch einmal 2.`,options:[{id:`N2`,label:`2 Karten`},{id:`N4`,label:`4 Karten`},{id:`N6`,label:`6 Karten`}],answer:`N4`,wrong:{N2:`Das war die erste Sieben. {WEST} hat noch eine draufgelegt: 2 + 2.`,N6:`Zwei Siebner liegen, also 2 + 2, nicht 6.`}},{t:`draw`,seat:`SUED`,code:`R8`,text:`Tippe auf den Nachziehstapel. Vier Mal.`,tip:`Die ganze Strafe zieht man in einem Zug.`,wrong:{"*":`Du kannst nichts legen: Tippe auf den Nachziehstapel.`}},{t:`draw`,seat:`SUED`,code:`L9`,wrong:{"*":`Noch ziehen: Tippe auf den Nachziehstapel.`}},{t:`draw`,seat:`SUED`,code:`SO`,wrong:{"*":`Noch ziehen: Tippe auf den Nachziehstapel.`}},{t:`draw`,seat:`SUED`,code:`EU`,wrong:{"*":`Noch eine: Tippe auf den Nachziehstapel.`}},e(`Vier Karten Strafe, weil niemand die Kette mit der richtigen Sechs gebrochen hat. Merk dir: Eine Sieben gibst du immer weiter, und die Sechs der geltenden Farbe stoppt die ganze Kette. Heb dir Siebner und Sechser für den Ernstfall auf.`)]},{regionId:`WALLIS`,kind:`tschausepp`,title:`Tschau Sepp`,lesson:`Der Schluss und Tschau`,ziele:[`Zwei Asse hintereinander legen`,`Den Under für den Schluss sparen`,`«Tschau» nicht vergessen`,`Mit dem Under zum Sieg`],zielAt:[4,8,9,13],einstieg:`Gut gespielt ist halb gewonnen. Jetzt lernst du, wie man sauber fertig wird.`,order:t,score:`none`,hands:{SUED:`RA EA E9 EK LU`,OST:`E8 RK S10 SA L9`,NORD:`R6 SK SO L8 L6`,WEST:`EO R9 S9 LA E10`},top:`R8`,pile:15,steps:[e(`Dritte Hand: der Schluss. Wer seine Karten geschickt loswird, gewinnt. Du siehst, wie zwei Asse die Hand abkürzen, warum der Under dein Joker fürs Ende ist und was es mit «Tschau» auf sich hat.`),{t:`choose`,text:`Oben liegt die Rosen 8. Du hast Rosen Ass, Eichel Ass, Eichel 9, Eichel König und Under. Mit welcher Karte kommst du am weitesten?`,tip:`Welche Karten passen überhaupt auf die Rosen 8?`,options:[{id:`RA`,label:`Rosen Ass`,code:`RA`},{id:`LU`,label:`Under`,code:`LU`},{id:`E9`,label:`Eichel 9`,code:`E9`}],answer:`RA`,wrong:{LU:`Der Under passt immer, richtig. Aber genau deshalb hebst du ihn auf: Er ist dein Joker, wenn sonst nichts geht, und gehört ans Ende.`,E9:`Die Eichel 9 passt nicht auf die Rosen 8: weder Farbe noch Wert.`}},{t:`play`,seat:`SUED`,code:`RA`,text:`Das Rosen-Ass. Danach darfst du gleich noch eine Karte legen, entweder derselben Farbe oder ein weiteres Ass.`,tip:`Hast du keine zweite passende, ziehst du eine Karte.`,wrong:{"*":`Lege das Rosen-Ass: Es passt zur Farbe.`}},{t:`play`,seat:`SUED`,code:`EA`,riddle:!0,text:`Und jetzt? Du darfst nochmals legen. Welche Karte bringt dich am weitesten?`,wrong:{E9:`Nach einem Ass musst du Rose legen oder ein weiteres Ass. Die Eichel 9 passt dazu nicht.`,EK:`Nach einem Ass musst du Rose legen oder ein weiteres Ass. Der Eichel König ist weder das eine noch das andere.`,LU:`Der Under ginge, aber den spar dir. Schau, ob du nicht noch ein Ass hast.`,"*":`Nach einem Ass musst du Rose legen oder ein weiteres Ass.`}},{t:`play`,seat:`SUED`,code:`E9`,text:`Das zweite Ass hat die Farbe auf Eichel gedreht. Jetzt noch eine Eichel dazu: die 9. Drei Karten in einem Zug, nicht schlecht, gäll?`,wrong:{EK:`Der König ginge auch. Aber den brauchst du später, damit du auch auf andere Könige legen kannst. Nimm die Neun.`,"*":`Nach dem Ass legst du eine Eichel nach. Nimm die Eichel 9.`}},{t:`play`,seat:`OST`,code:`E8`,text:`{OST} legt die Eichel 8. Eine Acht: {NORD} setzt aus.`},{t:`play`,seat:`WEST`,code:`EO`,text:`{WEST} ist als Nächster dran und legt den Eichel Ober.`},{t:`choose`,text:`Du hast noch den Eichel König und den Under. Welche Karte spielst du zuerst?`,tip:`Überleg: Welche Karte ist am Schluss sicherer?`,options:[{id:`EK`,label:`Eichel König`,code:`EK`},{id:`LU`,label:`Under`,code:`LU`}],answer:`EK`,wrong:{LU:`Der Under geht immer, deshalb wäre er dein Joker. Spielst du ihn jetzt, bleibt dir der Eichel König als letzte Karte, und der passt nur auf Eichel oder auf einen König. Machst du es umgekehrt, kann dir am Schluss nichts mehr dazwischenkommen.`}},{t:`play`,seat:`SUED`,code:`EK`,fx:{bubbles:{SUED:`Tschau!`}},text:`Spiel den König. Jetzt hast du nur noch eine Karte, den Under. Das musst du ansagen: «Tschau!»`,wrong:{"*":`Spiele den Eichel König: Er passt zur Farbe.`}},{t:`choose`,text:`Du hast nur noch eine Karte. Was passiert, wenn du «Tschau» vergisst?`,tip:`Zeit hast du, bis der Nächste seinen Zug beendet hat.`,options:[{id:`STRAFE`,label:`Du ziehst eine Strafkarte`},{id:`NICHTS`,label:`Nichts`},{id:`AUSSETZEN`,label:`Du setzt eine Runde aus`}],answer:`STRAFE`,wrong:{NICHTS:`Doch: Wer nach dem Zug des Nächsten kein «Tschau» gesagt hat, muss eine Karte ziehen.`,AUSSETZEN:`Aussetzen musst du nicht. Aber du ziehst eine Strafkarte, und dann hast du schon wieder zwei.`}},{t:`play`,seat:`OST`,code:`RK`,text:`{OST} legt den Rosen König. Gleicher Wert wie dein König, aber die Farbe wechselt auf Rose.`},{t:`play`,seat:`NORD`,code:`R6`},{t:`play`,seat:`WEST`,code:`R9`,text:`{WEST} legt die Rosen 9. Du bist wieder dran: Mit dem Under geht der Rest von selbst.`},{t:`play`,seat:`SUED`,code:`LU`,color:`E`,text:`Jetzt der Under, deine letzte Karte. Er passt auch auf die Rose. Wünsch dir die Eichel, und du bist fertig.`,tip:`Der Under darf als letzte Karte fallen, nur gegen eine Siebner-Strafe nicht.`,wrong:{"*":`Spiele den Under: Er passt auf jede Farbe.`}},e(`Fertig, du gewinnst die Runde. Die anderen spielen weiter, bis nur noch einer Karten hat, und der verliert ein Leben. Merk dir: Asse hintereinander legen, den Under bis zum Schluss aufbewahren, und bei der vorletzten Karte «Tschau» nicht vergessen.`)]}],y=[{regionId:`LAUSANNE`,kind:`arschloechle`,title:`Arschlöchle`,lesson:`Höher oder passen`,ziele:[`Die Rangfolge der Karten kennen`,`Knapp überbieten, nicht verschwenden`,`Ein Paar auf einmal legen`,`Passen, wenn nichts reicht`],zielAt:[1,7,11,16],einstieg:`Du musst nichts können, nur höher legen oder passen.`,order:t,score:`none`,hands:{SUED:`E6 L7 E8 L8 E9 R10 RO LK SA`,OST:`S7 RU SU R9 E7 LO RK LA S10`,NORD:`SK EO EA E10 EU S6 R6 R7 L9`,WEST:`S9 SO EK RA S8 R8 L6 L10 LU`},steps:[e(`Arschlöchle, Lausanner Art. Keine Farben, kein Trumpf, nur der Wert zählt: 6, 7, 8, 9, 10, Under, Ober, König, Ass, von klein nach gross. Du legst eine Karte oder mehrere gleiche, die Nächsten legen gleich viele höhere, oder sie passen. Du beginnst.`,`Es geht gegen den Uhrzeigersinn: du, dann {OST}, {NORD}, {WEST}.`),{t:`choose`,text:`Probier die Rangfolge aus. Welche dieser drei Karten ist die höchste?`,tip:`Von unten nach oben: 6, 7, 8, 9, 10, Under, Ober, König, Ass.`,options:[{id:`LK`,label:`Schilten König`,code:`LK`},{id:`RO`,label:`Rosen Ober`,code:`RO`},{id:`E9`,label:`Eichel 9`,code:`E9`}],answer:`LK`,wrong:{RO:`Der Ober ist stark, aber der König steht noch eine Stufe darüber.`,E9:`Die Neun ist weit unten, vier Stufen unter dem Ober.`}},{t:`play`,seat:`SUED`,cards:`E6`,text:`Zum Anfang spielst du eine kleine Karte aus: die Sechs. Deine hohen Karten brauchst du später.`,tip:`Mit kleinen Karten ausspielen, grosse für später aufheben.`,wrong:{"*":`Beginne mit der kleinen Sechs, deine hohen Karten brauchst du später.`}},{t:`play`,seat:`OST`,cards:`S7`,text:`{OST} überbietet mit der Sieben. Höher als eine Sechs, das darf er.`},{t:`pass`,seat:`NORD`,text:`{NORD} passt. Das ist immer erlaubt, auch wenn er überbieten könnte. Ein Pass gilt nur für diesen Zug.`},{t:`play`,seat:`WEST`,cards:`S9`,text:`{WEST} legt eine Neun.`},{t:`choose`,text:`Jetzt bist du dran. Du musst strikt höher als die Neun legen. Welche Karte nimmst du, wenn du sparsam sein willst?`,tip:`Gleicher Wert genügt nicht, und die kleinste, die reicht, ist die beste.`,options:[{id:`E9`,label:`Eichel 9`,code:`E9`},{id:`R10`,label:`Rosen 10`,code:`R10`},{id:`LK`,label:`Schilten König`,code:`LK`}],answer:`R10`,wrong:{E9:`Eine Neun auf eine Neun geht nicht, der Wert muss höher sein.`,LK:`Der König schlägt die Neun, aber er ist dein bestes Stück dafür. Es reicht die Zehn, und die ist kleiner.`}},{t:`play`,seat:`SUED`,cards:`R10`,text:`Die Zehn, genau knapp darüber.`,tip:`Gleicher Wert genügt nicht: Es muss strikt höher sein.`,wrong:{E9:`Eine Neun auf eine Neun geht nicht, der Wert muss höher sein. Lege die Zehn.`,"*":`Dieser Wert ist nicht höher als die Neun. Lege die Zehn.`}},{t:`pass`,seat:`OST`,text:`{OST} hätte Ober, König oder Ass, passt aber trotzdem. Er spart die hohen Karten.`},{t:`pass`,seat:`NORD`},{t:`pass`,seat:`WEST`,text:`{WEST} passt. Alle drei haben gepasst: Du hast den Stich gewonnen und spielst wieder aus.`},{t:`play`,seat:`SUED`,cards:`E8 L8`,text:`Jetzt ein Mehrling: Du hast zwei Achten. Tippe beide an. Die anderen müssen dann auch zwei Karten mit höherem Wert legen, oder sie passen.`,tip:`Paare, Drillinge und Vierlinge gleichen Werts darfst du zusammen legen.`,wrong:{"*":`Tippe die beiden Achten an, um sie gemeinsam zu legen.`}},{t:`play`,seat:`OST`,cards:`RU SU`,text:`{OST} hat zwei Under und überbietet mit dem Paar.`},{t:`pass`,seat:`NORD`,text:`{NORD} hat kein Paar und passt.`},{t:`pass`,seat:`WEST`},{t:`choose`,text:`{OST} hat dein Paar mit zwei Under überboten. Du hast kein Paar mit höherem Wert. Was machst du?`,tip:`Eine einzelne hohe Karte kann ein Paar nicht schlagen.`,options:[{id:`PASS`,label:`Passen`},{id:`SINGLE`,label:`Einen Ober legen`},{id:`MIX`,label:`Zwei verschiedene hohe Karten legen`}],answer:`PASS`,wrong:{SINGLE:`Auf ein Paar musst du zwei Karten legen, eine allein genügt nicht.`,MIX:`Ein Mehrling besteht aus gleichen Werten. Zwei verschiedene Karten gelten nicht.`}},{t:`pass`,seat:`SUED`,text:`Dann bleibt dir nur das Passen. Tippe auf «Passen».`,tip:`Passen ist immer erlaubt, nur wer einen neuen Stich beginnt, muss ausspielen.`,wrong:{"*":`Du hast kein höheres Paar: Tippe auf «Passen».`}},{t:`play`,seat:`OST`,cards:`R9`,text:`{OST} hat den Stich gewonnen und spielt eine Neun aus.`},{t:`play`,seat:`NORD`,cards:`SK`,text:`{NORD} legt einen König.`},{t:`pass`,seat:`WEST`},{t:`play`,seat:`SUED`,cards:`SA`,riddle:!0,text:`Du bist dran, {NORD} hat einen König gelegt. Deine Hand: Schilten 7, Eichel 9, Rosen Ober, Schilten König, Schellen Ass. Was spielst du?`,wrong:{L7:`Die Sieben ist viel tiefer als der König.`,E9:`Die Neun ist viel tiefer als der König.`,RO:`Der Ober liegt eine Stufe unter dem König.`,LK:`Ein König auf einen König geht nicht, der Wert muss höher sein.`,"*":`Nur eine Karte in deiner Hand schlägt den König. Passen wäre schade.`}},e(`Das Ass kann niemand überbieten, der Stich ist sofort deiner, und du spielst wieder aus. So geht es weiter, bis fast alle Karten abgelegt sind. Wer zuerst keine mehr hat, wird Präsi, wer übrig bleibt, ist das Ar***. Das Ar*** verteilt die nächste Hand und muss seine besten Karten abgeben. Merk dir: knapp überbieten, hohe Karten sparen.`)]},{regionId:`LAUSANNE`,kind:`arschloechle`,title:`Arschlöchle`,lesson:`Paare und Drillinge`,ziele:[`Ein Paar legen`,`Ein Paar mit einem höheren Paar schlagen`,`Einen Drilling wagen`,`Gleich viele Karten antworten`],zielAt:[2,7,12,16],einstieg:`Zu zweit und zu dritt geht es schneller. Probier es aus.`,order:t,score:`none`,hands:{SUED:`E6 S6 E8 E9 S9 R9 EK SK LA`,OST:`R7 L7 EU SU RU L6 L10 RA LO`,NORD:`S7 E7 R10 S8 SO LU RK EA R6`,WEST:`EO RO E10 S10 SA L8 L9 LK R8`},steps:[e(`Zweite Hand: Mehrlinge. Wer zwei, drei oder vier gleiche Karten hält, kann sie auf einmal legen und wird sie schneller los. Dafür verlangt der Mehrling auch von den anderen etwas.`),{t:`choose`,text:`Was brauchst du, um ein Paar zu überbieten?`,tip:`Anzahl und Wert müssen stimmen.`,options:[{id:`PAIR`,label:`Ein höheres Paar, also zwei gleiche Karten`},{id:`TWO`,label:`Zwei beliebige höhere Karten`},{id:`ONE`,label:`Eine einzelne hohe Karte`}],answer:`PAIR`,wrong:{TWO:`Beliebig geht nicht: Es müssen zwei Karten gleichen Werts sein, und der Wert muss höher liegen.`,ONE:`Auf ein Paar musst du zwei Karten legen. Eine einzelne, und wäre es ein Ass, genügt nicht.`}},{t:`play`,seat:`SUED`,cards:`E6 S6`,text:`Fang mit dem tiefsten Paar an, den beiden Sechsen. Tippe beide an.`,tip:`Tiefe Paare los zu werden ist leicht, hohe heb dir auf.`,wrong:{"*":`Tippe die beiden Sechsen an, Eichel und Schelle.`}},{t:`play`,seat:`OST`,cards:`R7 L7`,text:`{OST} hat zwei Siebner und überbietet mit dem Paar.`},{t:`pass`,seat:`NORD`,text:`{NORD} hat zwar eine Zehn, eine Acht und noch mehr, aber kein Paar höher als zwei Siebner. Er muss passen. Mit lauter einzelnen Karten kommt er nicht weiter.`},{t:`play`,seat:`WEST`,cards:`EO RO`,text:`{WEST} hat zwei Ober und schlägt das Siebnerpaar.`},{t:`choose`,text:`Jetzt liegen zwei Ober auf dem Tisch. Du hast Eichel König, Schellen König, Eichel 9, Schellen 9, Rosen 9 und das Ass. Welches Paar schlägt sie?`,tip:`Du brauchst zwei gleiche Karten, und beide müssen höher als der Ober sein.`,options:[{id:`K`,label:`Das Königspaar`,code:`EK`},{id:`N`,label:`Zwei Neunen`,code:`E9`},{id:`A`,label:`Das Ass`,code:`LA`}],answer:`K`,wrong:{N:`Zwei Neunen sind tiefer als zwei Ober. Der Wert muss höher sein.`,A:`Ein Ass allein ist keine zwei Karten. Auf ein Paar braucht es ein Paar.`}},{t:`play`,seat:`SUED`,cards:`EK SK`,text:`Tippe die beiden Könige an. Über dem Ober ist nur noch das Ass.`,wrong:{"*":`Tippe Eichel König und Schellen König an.`}},{t:`pass`,seat:`OST`},{t:`pass`,seat:`NORD`},{t:`pass`,seat:`WEST`,text:`{WEST} hat kein Asspaar und passt. Du hast den Stich und spielst wieder aus.`},{t:`choose`,text:`Du hast jetzt drei Neunen in der Hand. Wenn du sie zusammen ausspielst, wer kann sie schlagen?`,tip:`Für einen Drilling braucht es wieder einen Drilling.`,options:[{id:`THREE`,label:`Nur drei gleiche höhere Karten`},{id:`ACE`,label:`Ein einzelnes Ass`},{id:`PAIR`,label:`Zwei Under`}],answer:`THREE`,wrong:{ACE:`Auch ein Ass muss in der gleichen Anzahl kommen. Bei einem Drilling brauchst du drei Karten, also drei Asse.`,PAIR:`Es muss die gleiche Anzahl sein: Drei Karten gleichen Werts, und höher als die Neun.`}},{t:`play`,seat:`SUED`,cards:`E9 S9 R9`,text:`Wag es: Spiel die drei Neunen zusammen aus. Drei Karten auf einen Streich.`,tip:`Ein Drilling macht dich schnell klein, kostet aber das Risiko eines höheren Drillings.`,wrong:{"*":`Tippe alle drei Neunen an: Eichel, Schelle, Rose.`}},{t:`play`,seat:`OST`,cards:`EU SU RU`,text:`Hoppla: {OST} hat gleich drei Under und schlägt deinen Drilling.`},{t:`pass`,seat:`NORD`},{t:`pass`,seat:`WEST`},{t:`pass`,seat:`SUED`,text:`Du hast nur noch die Acht und das Ass, keinen Drilling. Passen.`,tip:`Das Wagnis hat sich nicht ausgezahlt, aber ein Mehrling bleibt sinnvoll, wenn du ihn bei dir hast.`,wrong:{"*":`Du hast keinen Drilling: Tippe auf «Passen».`}},{t:`play`,seat:`OST`,cards:`L6`,text:`{OST} spielt als Gewinner des Stichs eine Sechs aus.`},{t:`play`,seat:`NORD`,cards:`R10`,text:`{NORD} legt eine Zehn.`},{t:`pass`,seat:`WEST`,text:`{WEST} könnte mit einem Ober höher gehen, aber er will sein Ober-Paar nicht trennen und passt.`},{t:`play`,seat:`SUED`,cards:`LA`,riddle:!0,text:`Du bist dran, {NORD} hat eine Zehn gelegt. Du hast nur noch die Eichel 8 und das Schilten Ass. Was spielst du?`,wrong:{E8:`Die Acht liegt unter der Zehn, das geht nicht.`,"*":`Die Acht reicht nicht gegen die Zehn. Es gibt eine Karte, die immer reicht.`}},e(`Das Ass gewinnt den Stich sofort. Merk dir: Ein Mehrling braucht als Antwort gleich viele höhere Karten. Tiefe Paare spielst du früh aus, hohe sparst du, und wer einen Drilling hält, sollte wissen, dass auch ein anderer einen haben kann. Ein einzelnes Ass schlägt nie ein Paar.`)]},{regionId:`LAUSANNE`,kind:`arschloechle`,title:`Arschlöchle`,lesson:`Sparen und Ass-Paar`,ziele:[`Die kleinste passende Karte nehmen`,`Mit der tiefsten Karte beginnen`,`Asse sparen und lieber passen`,`Das Ass-Paar zusammen spielen`],zielAt:[5,10,15,19],einstieg:`Geduld macht den Präsi. Wer spart, gewinnt.`,order:t,score:`none`,hands:{SUED:`S6 E7 R8 S9 E10 SU RO EA LA`,OST:`R7 EU EK E8 S7 R10 L6 EO SA`,NORD:`L9 E9 R9 S8 S10 R6 LU RA L7`,WEST:`SK RK LK E6 SO RU L8 L10 LO`},steps:[e(`Dritte Hand: Sparen. Wer in dieser Runde Präsi werden will, braucht Geduld. Du übst heute, die kleinste Karte zu nehmen, die reicht, einmal zu passen, obwohl du könntest, und zwei Asse zusammen zu spielen. {OST} beginnt.`),{t:`play`,seat:`OST`,cards:`R7`,text:`{OST} spielt eine Sieben aus.`},{t:`play`,seat:`NORD`,cards:`L9`,text:`{NORD} überbietet mit der Neun.`},{t:`pass`,seat:`WEST`,text:`{WEST} passt, obwohl er Könige hätte. Er spart sie. Jetzt bist du dran.`},{t:`choose`,text:`Du musst höher als die Neun legen. Deine Hand: Eichel 10, Schellen Under, Rosen Ober, Eichel Ass, Schilten Ass. Welche Karte nimmst du?`,tip:`Die kleinste, die reicht.`,options:[{id:`E10`,label:`Eichel 10`,code:`E10`},{id:`RO`,label:`Rosen Ober`,code:`RO`},{id:`EA`,label:`Eichel Ass`,code:`EA`}],answer:`E10`,wrong:{RO:`Der Ober schlägt die Neun auch, ist aber viel mehr Karte, als du brauchst. Die Zehn reicht.`,EA:`Das Ass verbrauchst du hier für nichts. Die Zehn reicht, und das Ass bleibt dir.`}},{t:`play`,seat:`SUED`,cards:`E10`,text:`Die Zehn, knapp drüber. Mehr braucht es nicht.`,wrong:{"*":`Spiele die Eichel 10: Sie schlägt die Neun gerade eben.`}},{t:`pass`,seat:`OST`},{t:`pass`,seat:`NORD`},{t:`pass`,seat:`WEST`,text:`Alle drei passen, der Stich gehört dir, und du spielst aus.`},{t:`choose`,text:`Du beginnst den nächsten Stich. Womit?`,tip:`Was spielst du am liebsten los?`,options:[{id:`S6`,label:`Schellen 6`,code:`S6`},{id:`RO`,label:`Rosen Ober`,code:`RO`},{id:`EA`,label:`Eichel Ass`,code:`EA`}],answer:`S6`,wrong:{RO:`Hohe Karten gewinnen Stiche, aber du hast sie nur wenige Male. Die Ausspielkarte ist die tiefste, die du loswerden willst.`,EA:`Das Ass ist dein Joker, den spielst du nicht als Erstes.`}},{t:`play`,seat:`SUED`,cards:`S6`,text:`Die Sechs. Tiefer geht es nicht.`,wrong:{"*":`Beginne mit der tiefsten Karte: der Schellen 6.`}},{t:`play`,seat:`OST`,cards:`EU`,text:`{OST} überbietet mit dem Under.`},{t:`pass`,seat:`NORD`},{t:`play`,seat:`WEST`,cards:`SK`,text:`{WEST} legt den ersten König.`},{t:`choose`,text:`Du hast Eichel Ass und Schilten Ass. Eines davon schlägt den König. Ass legen oder passen?`,tip:`Zwei Asse zusammen sind etwas, das niemand schlägt.`,options:[{id:`PASS`,label:`Passen`},{id:`ACE`,label:`Ein Ass legen`}],answer:`PASS`,wrong:{ACE:`Das Ass würde dich den Stich gewinnen lassen, aber du verschwendest damit einen deiner beiden Joker. Zwei Asse zusammen schlagen jedes Paar. Lass die beiden zusammen.`}},{t:`pass`,seat:`SUED`,text:`Gut. Der König bleibt liegen, du passt.`,tip:`Auch mit einem Ass in der Hand ist Passen oft klüger.`,wrong:{"*":`Spare die Asse: Tippe auf «Passen».`}},{t:`pass`,seat:`OST`},{t:`pass`,seat:`NORD`,text:`Alle haben gepasst, {WEST} hat den Stich und spielt aus.`},{t:`play`,seat:`WEST`,cards:`RK LK`,text:`{WEST} spielt ein Paar Könige aus, die beiden anderen.`},{t:`play`,seat:`SUED`,cards:`EA LA`,riddle:!0,text:`{WEST} hat zwei Könige gelegt. Du hast Rosen Ober, Schellen Under und deine zwei Asse. Wie bleibst du am Drücker?`,wrong:{RO:`Der Ober ist tiefer als ein König, und es müssten zwei Karten sein.`,SU:`Der Under ist tiefer als ein König, und es müssten zwei Karten sein.`,"*":`Auf ein Paar braucht es ein höheres Paar. Welche zwei Karten sind das?`}},e(`Das Ass-Paar kann niemand mehr überbieten, der Stich ist dein. Jetzt bist du wieder dran und hast nur noch fünf Karten. Merk dir: Die kleinste Karte nehmen, die reicht, hohe Karten und Asse sparen und zwei Asse für den entscheidenden Moment aufheben.`)]}],b=[{id:`CHRATZE`,label:`Chräbele`},{id:`DABEI`,label:`Dabei`},{id:`WEG`,label:`Weg`}],x=[{regionId:`CHRATZE`,kind:`trick`,title:`Chräbele`,lesson:`Hand lesen`,ziele:[`Die eigene Hand lesen und ansagen`,`Farbe bedienen, sonst trumpfen`,`Mit Nell und Under stechen`,`Den Pot-Anteil ausrechnen`],zielAt:[5,12,14,20],einstieg:`Vier Karten, drei Ansagen. Du schaust deine Hand an und entscheidest in Ruhe.`,order:t,out:[`NORD`],firstLeader:`OST`,score:`chratze`,target:2,rules:{chratze:!0},trump:`ROSE`,upcard:`R8`,hands:{SUED:`RU R9 RA SA`,OST:`EA S8 L10 LA`,NORD:`E6 S6 S7 L9`,WEST:`R6 S10 L7 L8`},steps:[e(`Chräbele, das Spiel für Mutige. Jeder legt den Einsatz in den Pot und bekommt nur vier Karten. Die aufgedeckte Karte bestimmt den Trumpf: hier die Rosen 8, also ist Rose Trumpf. Dann sagt jeder an, wie viele Stiche er macht: «Chräbele» (2 Stiche), «Dabei» (1 Stich) oder «Weg».`,`Du siehst hier alle Karten offen. Am echten Tisch sind die Hände der anderen verdeckt.`,{badges:[`Trumpf: Rose`]}),{t:`choose`,text:`Wir üben zuerst das Hand lesen. Aufgabe 1: Du hast Under, Nell und Ass im Trumpf und noch ein Schellen-Ass. {OST} hat «Chräbele» gesagt, {NORD} «Dabei», {WEST} «Weg». Was sagst du an?`,tip:`Die höchsten Trümpfe (Under, Nell, Ass) gewinnen ihren Stich fast immer.`,options:b,answer:`CHRATZE`,wrong:{DABEI:`«Dabei» ist nicht falsch: Du machst sicher mehrere Stiche. Aber mit «Chräbele» zählen deine Stiche doppelt, und du bekommst beim Teilen des Pots mehr. Sag «Chräbele».`,WEG:`Mit dieser Hand bleibst du doch nicht draussen! Dein Einsatz liegt schon im Pot, und mit dem Trumpf-Under gewinnst du Stiche.`},fx:{sued:`E8 E9 SU LO`}},{t:`choose`,text:`Aufgabe 2: Kein Trumpf, kein Ass, nur tiefe und mittlere Karten. {OST} hat «Chräbele» gesagt, {NORD} und {WEST} «Dabei». Was sagst du an?`,tip:`Wer verfehlt, legt in den nächsten Pot nach. Wer «Weg» sagt, verliert nur den Einsatz, der ohnehin im Pot liegt. Anders ist es, wenn alle vor dir «Weg» sagen: Dann teilen sich nur wenige den Pot, und «Dabei» lohnt sich auch mit einer schwachen Hand.`,options:b,answer:`WEG`,wrong:{CHRATZE:`Zwei Stiche ohne Trumpf und ohne Ass? Das geht fast sicher schief, und wer «Chräbele» verfehlt, zahlt das Doppelte des Einsatzes nach.`,DABEI:`Drei sind schon dabei, und ohne Trumpf und ohne Ass ist ein Stich unwahrscheinlich. Wer verfehlt, legt einen Einsatz nach. Besser: «Weg».`},fx:{sued:`RK SA EK E10`}},{t:`choose`,text:`Aufgabe 3: Ein Trumpf-König, dazu das Schellen-Ass und ein paar mittlere Karten. {OST} hat «Chräbele» gesagt, {NORD} und {WEST} «Dabei». Was sagst du an?`,tip:`Zwei Stiche sind hier zu viel verlangt, einer ist gut möglich. «Dabei» ist das sichere Mittelmass.`,options:b,answer:`DABEI`,wrong:{CHRATZE:`Das Ass bringt einen Stich, aber ein zweiter ist unsicher. Ein verfehltes «Chräbele» kostet doppelt. Sag lieber «Dabei».`,WEG:`Mit einem Ass und einem Trumpf machst du fast sicher einen Stich. Mit «Dabei» bist du im Spiel.`},fx:{sued:`E7 R9 RU L6`}},e(`Gut. Jetzt eine ganze Hand. Der Einsatz liegt im Pot, die Karten sind verteilt. Wer links vom Geber sitzt, sagt zuerst an: {OST} sagt «Chräbele» und will zwei Stiche. {NORD} hat nur tiefe Karten und geht «Weg». {WEST} sagt «Dabei».`,`Wer «Weg» sagt, spielt nicht mit. Sein Einsatz bleibt im Pot.`,{badges:[`Trumpf: Rose`],bubbles:{OST:`Chräbele!`,NORD:`Weg`,WEST:`Dabei`}}),{t:`choose`,text:`Du sprichst zuletzt. Du hältst Under und Nell im Trumpf, die zwei höchsten Karten überhaupt. Zwei Stiche hast du sicher. Was sagst du an?`,tip:`Du kennst jetzt die Ansagen der anderen: {OST} chratzt, {WEST} ist dabei. Mit den zwei besten Trümpfen darfst du chratzen.`,options:b,answer:`CHRATZE`,wrong:{DABEI:`Du hast Under und Nell, du machst sicher zwei Stiche. Mit «Chräbele» zählen sie doppelt, und du bekommst beim Pot-Teilen doppelt so viel pro Stich.`,WEG:`Mit Under und Nell? Du gibst den Einsatz her und verschenkst zwei sichere Stiche. Sag «Chräbele».`},fx:{badges:[`Trumpf: Rose`,`Du: Chräbele`],bubbles:{SUED:`Chräbele!`}}},{t:`choose`,text:`Bevor es losgeht: Wer spielt den ersten Stich aus?`,options:[{id:`GEBER`,label:`Der Geber`},{id:`CHRATZER`,label:`Der erste, der «Chräbele» gesagt hat`},{id:`DU`,label:`Du, weil du zuletzt gesprochen hast`}],answer:`CHRATZER`,wrong:{GEBER:`Nein. Es eröffnet der erste Chräbeler in der Reihenfolge der Ansagen. Gibt es keinen, der erste «Dabei».`,DU:`Du hast zuletzt gesprochen, aber eröffnen tut der erste Chräbeler. Das ist {OST}.`},fx:{bubbles:{}}},{t:`play`,seat:`OST`,code:`EA`,text:`{OST} eröffnet mit dem Eichel-Ass. Das Spiel geht gegen den Uhrzeigersinn weiter. {NORD} ist weg und wird übersprungen.`},{t:`choose`,text:`{WEST} hat keine Eichel mehr. Was darf er tun?`,options:[{id:`TRUMPFEN`,label:`Er muss trumpfen`},{id:`FREI`,label:`Trumpfen oder abwerfen, wie er will`}],answer:`FREI`,wrong:{TRUMPFEN:`Nein, wie im Schieber gibt es keinen Trumpfzwang: Wer die Farbe nicht hat, darf trumpfen, muss aber nicht.`}},{t:`play`,seat:`WEST`,code:`R6`,text:`{WEST} entscheidet sich zu trumpfen: Die Rosen 6 sticht das Eichel-Ass. Man darf trumpfen, wenn die Farbe fehlt, aber nicht unter einen Trumpf, der schon liegt.`},{t:`play`,seat:`SUED`,code:`E7`,text:`Du hast eine Eichel und musst sie bedienen (Farbzwang). Du verlierst diesen Stich, aber das macht nichts: Du brauchst nur zwei von vier.`,tip:`Farbe bedienen kommt zuerst. Trumpfen darfst du erst, wenn du die Farbe nicht hast (oder mit einem höheren Trumpf).`,wrong:{"*":`Farbzwang: Es wurde Eichel ausgespielt. Spiel deine Eichel 7.`}},{t:`play`,seat:`WEST`,code:`S10`,text:`{WEST} hat den Stich gewonnen und spielt die Schellen 10 aus.`},{t:`play`,seat:`SUED`,code:`R9`,text:`Du hast keine Schelle und darfst trumpfen. Du hast Under und Nell: Nimm den Nell, er sticht, und den Under sparst du dir auf.`,tip:`Spiel nur so viel Trumpf, wie nötig.`,wrong:{"*":`Spiel den Nell (Rosen 9): Er sticht die Schellen 10 und der Under bleibt dir für später.`}},{t:`play`,seat:`OST`,code:`S8`,text:`{OST} bedient die Schelle mit der 8. Dein Nell gewinnt den Stich: das ist dein erster.`},{t:`play`,seat:`SUED`,code:`RU`,text:`Jetzt der Under, der höchste Trumpf: Er schlägt alles. {OST} und {WEST} haben keinen Trumpf mehr und werfen ab.`,wrong:{"*":`Spiel den Under (Rosen Under), den höchsten Trumpf.`}},{t:`play`,seat:`OST`,code:`L10`,text:`{OST} muss nichts bedienen und wirft die Schilten 10 ab.`},{t:`play`,seat:`WEST`,code:`L8`},{t:`play`,seat:`SUED`,code:`L6`,text:`Zwei Stiche, dein Ziel ist erreicht! Die letzte Karte musst du trotzdem ausspielen: die Schilten 6.`,tip:`Ist dein Ziel erreicht, sind weitere Stiche Zugabe. Sie bringen beim Teilen noch etwas mehr Pot.`,fx:{badges:[`Trumpf: Rose`,`Du: Chräbele`,`Ziel erreicht`]}},{t:`play`,seat:`OST`,code:`LA`,text:`Das Schilten-Ass gewinnt den letzten Stich für {OST}. Es ist sein erster und einziger Stich.`},{t:`play`,seat:`WEST`,code:`L7`},{t:`choose`,text:`Abrechnung. Im Pot liegen 4 Batzen (4 mal 1). Deine zwei Stiche zählen doppelt, also vier Teile. {WEST} hat einen Stich, einen Teil. Wie viel bekommst du?`,options:[{id:`R20`,label:`2 Batzen`},{id:`R32`,label:`3.20 Batzen`},{id:`R40`,label:`4 Batzen`}],answer:`R32`,wrong:{R20:`Das wäre die Hälfte. Du hast aber 4 von 5 Teilen: 4 Batzen geteilt durch 5 mal 4.`,R40:`Den ganzen Pot bekommst du nur, wenn sonst keiner sein Ziel erreicht. {WEST} hat seines: einen Stich.`}},e(`Du bekommst also 3.20 Batzen, {WEST} 80 Rappen. {OST} hat «Chräbele» verfehlt (nur ein Stich) und legt das Doppelte des Einsatzes in den nächsten Pot: 2 Batzen. {NORD} hat nur seinen Einsatz verloren.`,`Verfehlst du bei «Dabei», legst du einen Einsatz nach, bei «Chräbele» zwei. Mit «Weg» verlierst du höchstens den Einsatz.`),e(`Merksatz: Je weiter hinten du ansagst, desto mehr weisst du über die anderen. Starke Karten, besonders Under und Nell, kann man schätzen; ein verfehltes «Chräbele» kostet doppelt.`,`Gespielt wird eine feste Zahl Hände. Wer am Schluss am meisten Geld hat, gewinnt, und wer den Einsatz nicht mehr zahlen kann, scheidet aus.`)]},{regionId:`CHRATZE`,kind:`trick`,title:`Chräbele`,lesson:`Schwache Hand: Dabei oder Weg?`,ziele:[`Schwache Hand richtig ansagen`,`Mit kleinem Trumpf ein Ass stechen`,`Billig abwerfen, wenn das Ziel steht`,`Den Pot-Anteil kennen`],zielAt:[1,5,9,12],einstieg:`Auch mit schwachen Karten kann man klug spielen.`,order:t,out:[`OST`,`WEST`],firstLeader:`NORD`,score:`chratze`,target:1,rules:{chratze:!0},trump:`EICHEL`,upcard:`E9`,hands:{SUED:`E6 R7 L8 L6`,NORD:`SA S10 RK L9`,OST:`S8 R9 L7 E8`,WEST:`S7 SU R6 L10`},steps:[e(`Zweite Hand: Nicht jede Hand ist ein Geschenk. Hier hast du eine schwache. Die Frage ist: «Weg» oder «Dabei»? Aufgedeckt liegt die Eichel 9, den Nell. Also ist Eichel Trumpf, und der Nell steckt in keiner Hand.`,`Die Ansagen vor dir: {OST} «Weg», {NORD} «Dabei», {WEST} «Weg».`,{badges:[`Trumpf: Eichel`],bubbles:{OST:`Weg`,NORD:`Dabei`,WEST:`Weg`}}),{t:`choose`,text:`Du sprichst zuletzt. Du hast die Eichel 6, also einen Trumpf, und sonst nur Kleinzeug. Nur {NORD} ist dabei, die anderen beiden sind weg. Was sagst du an?`,tip:`Überleg dir, wie viele Stiche es gibt und wie viele Spieler sie sich teilen.`,options:b,answer:`DABEI`,wrong:{CHRATZE:`Zwei Stiche mit dieser Hand? Hmpf. Verfehlst du, zahlst du das Doppelte nach.`,WEG:`Überleg: Nur du und {NORD} spielen. Vier Stiche für zwei Spieler, da fällt für dich fast sicher einer ab. Mit «Weg» verlierst du den Einsatz sicher, mit «Dabei» holst du ihn vermutlich zurück.`},fx:{bubbles:{OST:`Weg`,NORD:`Dabei`,WEST:`Weg`,SUED:`Dabei`}}},{t:`choose`,text:`Niemand hat gechratzt. Wer spielt den ersten Stich aus?`,options:[{id:`NORD`,label:`Der erste, der «Dabei» gesagt hat`},{id:`SUED`,label:`Du, weil du zuletzt gesprochen hast`},{id:`GEBER`,label:`Der Geber`}],answer:`NORD`,wrong:{SUED:`Nein. Gibt es keinen Chräbeler, eröffnet der erste, der «Dabei» gesagt hat.`,GEBER:`Nein. Gibt es keinen Chräbeler, eröffnet der erste, der «Dabei» gesagt hat.`},fx:{bubbles:{}}},{t:`play`,seat:`NORD`,code:`SA`,text:`{NORD} eröffnet mit dem Schellen-Ass. Er kann ja nicht in deine Karten sehen. Er denkt, das ist sein sicherer Stich.`},{t:`choose`,text:`Du hast keine Schelle. Was ist hier am besten?`,options:[{id:`TRUMPFEN`,label:`Trumpfen, ich habe ja Eichel`},{id:`ABWERFEN`,label:`Abwerfen, was ich will`}],answer:`TRUMPFEN`,wrong:{ABWERFEN:`Erlaubt wäre es, aber du holst mit dem kleinen Trumpf das Ass: Das ist dein Stich und damit dein Ziel.`}},{t:`play`,seat:`SUED`,code:`E6`,text:`Deine Eichel 6 sticht das Ass. Das ist dein Stich, dein Ziel ist erreicht. Mit der schlechtesten Karte im Spiel.`,tip:`Ein kleiner Trumpf sticht jedes Ass: Das ist die beste Freundin der schwachen Hand.`,wrong:{"*":`Trumpf die Eichel 6: Sie sticht das Schellen-Ass.`},fx:{badges:[`Trumpf: Eichel`,`Du: Dabei`,`Ziel erreicht`],bubbles:{}}},{t:`play`,seat:`SUED`,code:`R7`,text:`Du hast gewonnen und spielst aus. Mehr als einen Stich holst du nicht mehr: Spiel einfach die kleinste Karte, die Rosen 7.`,tip:`Das Ziel ist erreicht. Jetzt verlierst du billig.`,wrong:{"*":`Spiel die Rosen 7.`}},{t:`play`,seat:`NORD`,code:`RK`,text:`{NORD} bedient mit dem König und gewinnt.`},{t:`play`,seat:`NORD`,code:`S10`,text:`{NORD} spielt die Schellen 10 aus.`},{t:`play`,seat:`SUED`,code:`L6`,text:`Du hast keine Schelle und keinen Trumpf mehr: Du darfst abwerfen, was du willst. Wirf die kleinere Karte ab, die Schilten 6.`,wrong:{"*":`Wirf die Schilten 6 ab.`}},{t:`play`,seat:`NORD`,code:`L9`,text:`Zum Schluss spielt {NORD} die Schilten 9.`},{t:`play`,seat:`SUED`,code:`L8`,text:`Du bedienst Schilten mit der 8 und verlierst. Drei Stiche für {NORD}, einer für dich.`},{t:`choose`,text:`Abrechnung. Im Pot liegen 4 Batzen. {NORD} hat 3 Stiche, drei Teile, du einen: ein Teil. Wie viel bekommst du?`,options:[{id:`R0`,label:`Nichts`},{id:`R10`,label:`1 Batzen`},{id:`R20`,label:`2 Batzen`}],answer:`R10`,wrong:{R0:`Wer sein Ziel erreicht, bekommt seinen Anteil: ein Viertel von 4 Batzen ist 1 Batzen.`,R20:`Das wäre die Hälfte. Du hast einen von vier Stichen gemacht.`}},{t:`choose`,text:`Noch ein Gedankenspiel: Wenn {OST}, {NORD} und {WEST} alle «Weg» gesagt hätten und du allein «Dabei», was wäre geschehen?`,options:[{id:`ALLEIN`,label:`Ich bekomme den ganzen Pot, ohne einen Stich zu spielen`},{id:`ALLE4`,label:`Ich muss alle vier Stiche machen`},{id:`NEU`,label:`Die Hand wird neu gegeben`}],answer:`ALLEIN`,wrong:{ALLE4:`Nein, wer als Einziger übrig bleibt, spielt gar nicht: Er kassiert den Pot ohne Spiel und ohne Strafe.`,NEU:`Neu gegeben wird nur, wenn alle «Weg» sagen. Bleibt einer übrig, kassiert er den Pot.`}},e(`Du hast den Einsatz zurück: null zu null. Mit «Weg» hättest du 1 Batzen verloren, und {NORD} hätte den ganzen Pot kassiert. So lohnt sich «Dabei» auch mit einer Hand, die nach nichts aussieht.`,`Merksatz: Je weniger Mitspieler dabei sind, desto leichter sind die Stiche. Schwache Hand und wenig Konkurrenz: «Dabei». Schwache Hand und viele Mitspieler: «Weg».`)]},{regionId:`CHRATZE`,kind:`trick`,title:`Chräbele`,lesson:`Ziel verfehlt`,ziele:[`Mit einem Ass vorsichtig ansagen`,`Den Nell als Gefahr erkennen`,`Einen Pot mit Übertrag teilen`,`Die Strafe fürs Verfehlen kennen`],zielAt:[1,14,15,16],einstieg:`Eine Ansage ist ein Versprechen. Schau, was es kostet, wenn man es nicht hält.`,order:t,out:[`NORD`],firstLeader:`OST`,score:`chratze`,target:1,rules:{chratze:!0},trump:`SCHELLE`,upcard:`S8`,hands:{SUED:`E6 RK LK SA`,OST:`EA RA R10 L9`,WEST:`E7 S6 L8 S9`,NORD:`R6 R7 L6 L7`},steps:[e(`Dritte Hand: Was kostet es, wenn einer sein Ziel verfehlt? Aufgedeckt liegt die Schellen 8, also ist Schelle Trumpf. Und im Pot liegen schon 2 Batzen mehr als sonst: {OST} hat letztes Mal «Chräbele» verfehlt und diese 2 Batzen in den nächsten Pot nachgelegt. Mit den frischen Einsätzen sind es 6 Batzen.`,`Verfehlt einer, wächst der nächste Pot. Erreicht keiner sein Ziel, bleibt der Pot ganz stehen.`,{badges:[`Trumpf: Schelle`,`Pot: 60 Rp`],bubbles:{NORD:`Weg`,OST:`Chräbele!`,WEST:`Dabei`}}),{t:`choose`,text:`{NORD} geht «Weg», {OST} chratzt, {WEST} sagt «Dabei». Jetzt bist du dran. Du hast das Schellen-Ass (Trumpf), zwei Könige und eine kleine Eichel. Was sagst du an?`,tip:`Zähl, wie viele sichere Stiche du hast. Das Trumpf-Ass ist stark, aber nicht der höchste Trumpf.`,options:b,answer:`DABEI`,wrong:{CHRATZE:`Zwei Stiche? Das Trumpf-Ass ist nicht sicher: Der Nell steckt noch bei {WEST}, und der schlägt es. Mit den zwei Königen holst du kaum zwei Stiche, und verfehlt kostet doppelt.`,WEG:`Mit einem Trumpf-Ass und zwei Königen holst du fast sicher einen Stich. «Weg» verschenkt deinen Einsatz, und der Pot ist dick genug, dass es sich lohnt, dabei zu sein.`},fx:{badges:[`Trumpf: Schelle`,`Pot: 60 Rp`,`Du: Dabei`],bubbles:{SUED:`Dabei`}}},{t:`play`,seat:`OST`,code:`EA`,text:`{OST} chratzt und eröffnet, mit dem Eichel-Ass. Er hat noch das Rosen-Ass und glaubt an zwei Stiche.`},{t:`play`,seat:`WEST`,code:`E7`,text:`{WEST} bedient die Eichel.`},{t:`play`,seat:`SUED`,code:`E6`,text:`Farbzwang: Du hast eine Eichel, also bedienst du. Dein Stich ist es nicht.`,wrong:{"*":`Spiel die Eichel 6, Farbzwang.`}},{t:`play`,seat:`OST`,code:`RA`,text:`{OST} spielt gleich das nächste Ass aus: Rosen-Ass.`},{t:`choose`,text:`{WEST} hat keine Rose mehr. Was darf er tun?`,options:[{id:`TRUMPFEN`,label:`Er muss mit Schelle trumpfen`},{id:`FREI`,label:`Trumpfen oder abwerfen, wie er will`}],answer:`FREI`,wrong:{TRUMPFEN:`Nein, einen Trumpfzwang gibt es nicht. Er hat zwei Schellen und darf trumpfen, muss aber nicht.`}},{t:`play`,seat:`WEST`,code:`S6`,text:`{WEST} trumpft mit der kleinsten Schelle und behält den Nell. Das Rosen-Ass ist geschlagen: {OST} hat sein Ziel nicht mehr in der Tasche.`},{t:`play`,seat:`SUED`,code:`RK`,text:`Du musst Rose bedienen: der König. Der Stich geht trotzdem an {WEST}, weil Trumpf gestochen hat.`,wrong:{"*":`Farbzwang: Spiel den Rosen-König.`}},{t:`play`,seat:`WEST`,code:`L8`,text:`{WEST} hat gewonnen und spielt Schilten aus.`},{t:`play`,seat:`SUED`,code:`LK`,text:`Dein Schilten-König schlägt die Acht und die Neun von {OST}. Das ist dein Stich: Dein Ziel «Dabei» ist erreicht.`,wrong:{"*":`Farbzwang: Spiel den Schilten-König.`},fx:{badges:[`Trumpf: Schelle`,`Pot: 60 Rp`,`Du: Dabei`,`Ziel erreicht`],bubbles:{}}},{t:`play`,seat:`OST`,code:`L9`},{t:`play`,seat:`SUED`,code:`SA`,text:`Die letzte Karte: das Schellen-Ass. Du musst sie ausspielen.`},{t:`play`,seat:`OST`,code:`R10`,text:`{OST} hat keine Schelle und keinen Trumpf: Er wirft die Rosen 10 ab.`},{t:`play`,seat:`WEST`,code:`S9`,text:`Und da ist der Nell! Er schlägt dein Ass. Siehst du, warum «Chräbele» falsch gewesen wäre?`},{t:`choose`,text:`Abrechnung. {OST} hat nur einen Stich gemacht, {WEST} zwei, du einen. Im Pot liegen 6 Batzen. {WEST} und du haben euer «Dabei» erreicht, die Stiche zählen einfach: {WEST} 2 Teile, du 1 Teil. Wie viel bekommt {WEST}?`,options:[{id:`R20`,label:`2 Batzen`},{id:`R40`,label:`4 Batzen`},{id:`R60`,label:`6 Batzen`}],answer:`R40`,wrong:{R20:`Das ist dein Anteil, ein Teil von dreien. {WEST} hat zwei Teile von drei.`,R60:`Den ganzen Pot bekommt nur, wer allein sein Ziel erreicht. Du hast deines auch.`}},{t:`choose`,text:`{OST} hat «Chräbele» verfehlt. Wie viel muss er in den nächsten Pot nachlegen?`,options:[{id:`R10`,label:`1 Batzen (ein Einsatz)`},{id:`R20`,label:`2 Batzen (das Doppelte)`},{id:`R40`,label:`4 Batzen`}],answer:`R20`,wrong:{R10:`Das wäre bei «Dabei». Wer «Chräbele» verfehlt, zahlt das Doppelte des Einsatzes.`,R40:`So hart sind wir nicht. Bei «Chräbele» das Doppelte des Einsatzes: 2 Batzen.`}},e(`Du hast also 2 Batzen bekommen und 1 eingesetzt: plus 1. {WEST} plus 3. {OST} minus 3 (Einsatz und Strafe), {NORD} minus 1. Das ergibt null. Der nächste Pot beginnt mit den 2 Batzen von {OST}.`,`Merksatz: Eine Ansage ist ein Versprechen. «Dabei» ist das sichere Mittelmass, «Chräbele» das teure Wagnis. Ein Ass ist nicht sicher, solange der Nell oder der Under noch draussen ist.`)]}],S=[e(`Nu, willkommen am Jassturnier. Beim Einzelschieber spielst du jeden Durchgang mit einem anderen Partner: Er wird zugelost. Diesmal sitzt {NORD} dir gegenüber, gegen {OST} und {WEST}. Es gilt einfacher Schieber – nur die sechs Trümpfe, kein Weis, kein Stöck. Alle Karten liegen hier offen.`,`Wer mit wem spielt, zeigt dir vor jedem Durchgang die Auslosung.`),e(`Zweite Hand am Turnier: Obenabe. Dein Partner wurde zugelost, aber das Spiel ist dasselbe: Es gibt keinen Trumpf, und das Ass einer Farbe ist immer ein sicherer Stich. Auch hier zählen nur die Stichpunkte, kein Weis, kein Stöck, kein Faktor.`,`Beim Obenabe sticht nichts: Wer die Farbe nicht hat, wirft ab.`),e(`Dritte Hand am Turnier: Trumpf ziehen. Auch mit einem zugelosten Partner gilt: erst die hohen Trümpfe, dann die Asse. Gezählt werden nur die Stichpunkte, ohne Weis und Stöck.`,`Wer den Trumpf ansagt, hat meist die Karten, ihn auch durchzuziehen.`)],C=[e(`So geht es weiter bis zum 9. Stich. Ein Durchgang dauert 4 oder 8 Hände. Du schreibst die Punkte auf, die dein Team macht – jeder für sich. Danach lost das Turnier neue Partner zu, und am Schluss steht zuoberst in der Rangliste, wer die meisten Punkte gesammelt hat.`,`Am besten spielst du mit jedem Partner gut – du kannst dir ihn nicht aussuchen.`),e(`Merk dir: Ass vor König vor Ober, ein Zeichen vom Partner lesen und die Zehn auf seinen sicheren Stich legen. Das gilt mit jedem Partner, den dir das Turnier zulost.`,`Die Acht zählt in Obenabe 8 Punkte.`),e(`Erst die hohen Trümpfe, damit die Gegner leer sind, dann die Asse. Mit jedem Partner, der dir zugelost wird, ist das der sicherste Weg zu Punkten im Turnier.`,`Trumpf ziehen, dann Asse.`)],w=a.map((e,t)=>({...e,regionId:`EINZEL`,title:`Einzelschieber`,steps:[S[t],...e.steps.slice(1,-1).filter(e=>!e.nurSchieber),C[t]]})),T=[e(`Nu, willkommen am Partnerturnier. Beim Partnerschieber bleibst du das ganze Turnier mit demselben Partner zusammen: Du spielst mit {NORD} gegen {OST} und {WEST}. Es gilt einfacher Schieber – nur die sechs Trümpfe, kein Weis, kein Stöck. Alle Karten liegen hier offen.`,`Ihr seid ein eingespieltes Paar: Nutzt das beim Schieben und Schmieren.`),e(`Zweite Hand am Turnier: Obenabe. Mit einem festen Partner lernst du, seine Zeichen zu lesen. Ohne Trumpf gewinnt die höchste Karte der Farbe, und das Ass ist immer ein sicherer Stich. Gezählt werden nur die Stichpunkte, kein Weis, kein Stöck, kein Faktor.`,`Beim Obenabe sticht nichts: Wer die Farbe nicht hat, wirft ab.`),e(`Dritte Hand am Turnier: Trumpf ziehen. Du und dein Partner wisst: erst die hohen Trümpfe, dann die Asse. Gezählt werden nur die Stichpunkte, ohne Weis und Stöck.`,`Wer den Trumpf ansagt, hat meist die Karten, ihn auch durchzuziehen.`)],E=[e(`So geht es weiter bis zum 9. Stich. Ein Durchgang dauert 4 oder 8 Hände, in jedem spielt ihr gegen ein anderes Paar. Gewertet wird pro Paar: die Punkte eures Teams. Zuoberst in der Rangliste steht am Schluss das Paar mit den meisten Punkten.`,`Ihr gewinnt als Paar – oder verliert als Paar.`),e(`Merk dir: Ass vor König vor Ober, ein Zeichen vom Partner lesen und die Zehn auf seinen sicheren Stich legen. Wer lange zusammen spielt, versteht jedes Zeichen sofort.`,`Die Acht zählt in Obenabe 8 Punkte.`),e(`Erst die hohen Trümpfe, damit die Gegner leer sind, dann die Asse. Als eingespieltes Paar holt ihr so Stich um Stich.`,`Trumpf ziehen, dann Asse.`)],D=a.map((e,t)=>({...e,regionId:`PARTNER`,title:`Partnerschieber`,steps:[T[t],...e.steps.slice(1,-1).filter(e=>!e.nurSchieber),E[t]]})),O=(e,t)=>({id:e,label:t}),k=[{regionId:`QUARTETT`,kind:`quartett`,title:`Quartett`,lesson:`Fragen und Quartett`,ziele:[`Nach einem Wert fragen, den du hast`,`Ein Quartett ablegen`,`Bei einem Treffer weiterfragen`,`Zwei Quartette sammeln`],zielAt:[1,2,4,6],einstieg:`Vier Gleiche gehören zusammen. Frag einfach nett nach.`,order:t,score:`none`,hands:{SUED:`EA SA RA LK`,OST:`EK SK RO LU`,NORD:`LA RK EO SU`,WEST:`SO LO EU RU`},steps:[e(`Quartett, das Spiel ohne Stiche. Gesammelt werden Quartette: vier gleiche Karten, etwa alle vier Asse. Wer dran ist, verlangt von einem Mitspieler eine bestimmte Karte. Hat er sie, gibt er sie her, und du fragst weiter. Hat er sie nicht, ist er an der Reihe. Zum Üben spielen wir mit nur vier Werten, 16 Karten, und alle Karten liegen offen.`,`Wichtig: Du darfst nur nach einem Wert fragen, von dem du selbst schon eine Karte hast.`),{t:`choose`,text:`Du hast drei Asse (Eichel, Schelle, Rose) und den Schilten-König. Du bist dran. Was verlangst du?`,tip:`Je mehr Karten du von einem Wert hast, desto näher bist du am Quartett: Frag nach dem Wert, von dem du am meisten hast.`,options:[O(`NORD:LA`,`{NORD} nach dem Schilten-Ass fragen`),O(`OST:SK`,`{OST} nach dem Schellen-König fragen`),O(`WEST:RU`,`{WEST} nach dem Rosen-Under fragen`)],answer:`NORD:LA`,wrong:{"OST:SK":`Mit dem Schellen-König kommst du nicht weit: Du hast erst einen König, für ein Quartett fehlen dir noch drei. Dir fehlt aber nur ein Ass bis zum Quartett. Frag nach dem vierten Ass.`,"WEST:RU":`Einen Under hast du gar nicht, und dann darfst du auch nicht nach ihm fragen: Es gibt nur Fragen nach Werten, von denen du schon eine Karte hast.`}},{t:`ask`,seat:`SUED`,target:`NORD`,code:`LA`,ok:!0,text:`{NORD} hat das Schilten-Ass und gibt es dir. Jetzt hast du alle vier Asse: ein Quartett! Es wird sofort abgelegt und zählt als ein Punkt am Schluss. Weil die Frage geklappt hat, bist du nochmals dran.`},{t:`choose`,text:`Du hast nur noch den Schilten-König. {OST} hat zwei Könige offen vor sich liegen. Was verlangst du?`,tip:`In einer richtigen Partie siehst du die Karten der anderen nicht. Dort merkst du dir, wer nach was gefragt hat.`,options:[O(`OST:EK`,`{OST} nach dem Eichel-König fragen`),O(`WEST:SO`,`{WEST} nach dem Schellen-Ober fragen`),O(`OST:LU`,`{OST} nach dem Schilten-Under fragen`)],answer:`OST:EK`,wrong:{"WEST:SO":`Einen Ober hast du nicht, also darfst du nicht nach ihm fragen. Du hast den Schilten-König: Frag nach einem anderen König.`,"OST:LU":`Der Under gehört {OST}, und du hast keinen: Nach einem Wert, den du nicht hast, fragst du nicht. Bleib beim König.`}},{t:`ask`,seat:`SUED`,target:`OST`,code:`EK`,ok:!0,text:`{OST} gibt dir den Eichel-König. Zwei Könige, zwei fehlen noch. Du bleibst am Zug.`},{t:`ask`,seat:`SUED`,target:`OST`,code:`SK`,ok:!0,text:`Auch den Schellen-König holst du dir bei {OST}. Fehlt nur noch der Rosen-König, und der liegt bei {NORD}.`},{t:`ask`,seat:`SUED`,target:`NORD`,code:`RK`,ok:!0,text:`Vier Könige: das zweite Quartett! Jetzt hast du keine Karten mehr in der Hand. Wer keine Karten mehr hat, ist draussen und schaut zu.`},e(`Die anderen spielen weiter, bis alle Quartette liegen. Mit der Partie zu viert und 36 Karten sind es neun. Gewonnen hat am Schluss, wer die meisten hat. Du hast zwei, das kann sich sehen lassen.`,`Die nächste Hand zeigt dir, wie du aus den Fragen der anderen etwas lernst.`)]},{regionId:`QUARTETT`,kind:`quartett`,title:`Quartett`,lesson:`Nein sagen und merken`,ziele:[`Nein sagen, wenn die Karte fehlt`,`Aus Fragen etwas lernen`,`Dort fragen, wo der Wert liegt`,`Das Quartett zurückholen`],zielAt:[2,3,4,7],einstieg:`Jetzt hörst du gut zu: Jede Frage verrät etwas.`,order:t,score:`none`,hands:{SUED:`EA SA EK RO`,OST:`RA LA SK LU`,NORD:`LK RK EO SU`,WEST:`SO LO EU RU`},steps:[e(`Neue Hand, gleiche Regeln. Diesmal fängt {OST} an. Schau genau zu: Jede Frage verrät etwas, denn wer nach einem Wert fragt, muss davon selbst eine Karte haben.`,`Eine Frage, die ins Leere geht, bringt dem Fragenden nichts, aber allen anderen eine Auskunft.`),{t:`ask`,seat:`OST`,target:`SUED`,code:`EA`,ok:!0,text:`{OST} verlangt von dir das Eichel-Ass, und du hast es. Es wandert zu {OST}, der darum nochmals fragt.`},{t:`ask`,seat:`OST`,target:`SUED`,code:`RK`,ok:!1,text:`{OST} fragt dich nach dem Rosen-König. Den hast du nicht, du sagst «Nein». Jetzt bist du dran, denn nach einer Fehlfrage kommt der Gefragte an die Reihe.`},{t:`choose`,text:`{OST} hat nach einem Ass und nach einem König gefragt. Was weisst du jetzt über {OST}?`,tip:`Wer nach einem Wert fragt, hat selbst mindestens eine Karte davon.`,options:[O(`AK`,`{OST} hat mindestens ein Ass und einen König`),O(`O`,`{OST} hat mindestens einen Ober`),O(`NICHTS`,`Nichts: Man kann aus einer Frage nichts lernen`)],answer:`AK`,wrong:{O:`Nach einem Ober hat {OST} nicht gefragt. Wissen kannst du nur, was die Fragen verraten haben: ein Ass und ein König.`,NICHTS:`Doch, ganz viel. Jede Frage zeigt, dass der Fragende diesen Wert in der Hand hat. Das merkt sich ein guter Quartett-Spieler.`}},{t:`choose`,text:`Du bist dran. Du hast ein Ass, einen König und einen Ober. Von wem holst du dir jetzt am ehesten ein Ass?`,tip:`Frag dort, wo du weisst, dass der Wert liegt: Das hat dir {OST} eben verraten.`,options:[O(`OST`,`{OST}`),O(`NORD`,`{NORD}`),O(`WEST`,`{WEST}`)],answer:`OST`,wrong:{NORD:`{NORD} hat bisher nichts gefragt und nichts verraten. Bei {OST} weisst du es sicher: Er hat Asse.`,WEST:`{WEST} hat bisher nichts gefragt, du rätst nur. Bei {OST} weisst du, dass er Asse hat.`}},{t:`ask`,seat:`SUED`,target:`OST`,code:`RA`,ok:!0,text:`Treffer: {OST} gibt dir das Rosen-Ass. Du hast jetzt zwei Asse und bleibst am Zug.`},{t:`ask`,seat:`SUED`,target:`OST`,code:`LA`},{t:`ask`,seat:`SUED`,target:`OST`,code:`EA`,ok:!0,text:`Auch das Eichel-Ass, das du vorher hergeben musstest, kommt zurück. Vier Asse: ein Quartett für dich. So nutzt man, was die Fragen verraten.`},e(`Das war Quartett. Merk dir: nur nach Werten fragen, die du selbst hast, aufpassen, wer nach was gefragt hat, und bei einem Treffer weiterfragen. In der richtigen Partie sind es 36 Karten und neun Quartette, und die Karten der anderen siehst du nicht.`,`Wer sich die Fragen merkt, gewinnt.`)]}],A={untertrumpfVerbot:!1,schellen:`SCHELLE`},j=[{regionId:`NEUENBURG`,kind:`trick`,title:`Schellenjass`,lesson:`Schellen meiden`,ziele:[`Das Ziel kennen: wenig Schellen`,`Tief zugeben, wenn du bedienen musst`,`Ohne Schelle im Stich hoch gewinnen`,`Eine Schelle in fremden Stich werfen`],zielAt:[1,8,14,17],einstieg:`Hier zählen nur die Schellen. Am besten nimmst du keine.`,order:t,score:`schellen`,rules:A,trump:null,hands:{SUED:`E6 S6 RA E9 S9 R7 R8 RU RO`,OST:`E8 SU R6 EO LU SO SA L9 LK`,NORD:`E10 S7 R9 EU LA RK EA L6 L10`,WEST:`E7 S8 R10 EK L8 S10 SK LO L7`},steps:[e(`Schellenjass, wie man ihn im Welschland und bei uns spielt. Es gibt keinen Trumpf, und gezählt werden nur die neun Schellen. Jede Schelle in deinen Stichen ist ein Strich auf der Tafel, und am Schluss verliert, wer die meisten hat. Das Ass sticht, sonst gilt: Farbe bedienen.`,`Stöck, Weis und der letzte Stich zählen nicht. Gespielt wird gegen den Uhrzeigersinn: du, dann {OST}, {NORD}, {WEST}.`),{t:`choose`,text:`Erste Frage, damit ich weiss, ob du zugehört hast: Was willst du beim Schellenjass?`,options:[{id:`WENIG`,label:`Möglichst wenige Schellen in meinen Stichen`},{id:`STICHE`,label:`Möglichst viele Stiche`},{id:`PUNKTE`,label:`Möglichst viele Jasspunkte`}],answer:`WENIG`,wrong:{STICHE:`Hmpf. Ein Stich ist hier nichts wert, im Gegenteil: Wer ihn holt, bekommt die Schellen, die darin liegen.`,PUNKTE:`Jasspunkte kannst du vergessen, die zählen hier gar nichts. Es geht nur um die Schellen.`}},{t:`play`,seat:`SUED`,code:`E6`,text:`Du spielst aus. Es gibt keine Regel, was du ausspielen musst. Fang klein an, mit der Eichel 6: In dieser Farbe liegen keine Schellen.`,tip:`Die höchste Karte der ausgespielten Farbe holt den Stich.`,wrong:{"*":`Nimm die Eichel 6, sie kostet dich nichts.`}},{t:`play`,seat:`OST`,code:`E8`},{t:`play`,seat:`NORD`,code:`E10`,text:`{NORD} legt die Eichel 10, die höchste bisher.`},{t:`play`,seat:`WEST`,code:`E7`},{t:`play`,seat:`NORD`,code:`S7`,text:`{NORD} hat den Stich geholt und spielt aus: die Schellen 7. Jetzt wird es ernst, denn es sind Schellen im Spiel. Die anderen müssen Schellen zugeben, wenn sie können.`},{t:`play`,seat:`WEST`,code:`S8`},{t:`play`,seat:`SUED`,code:`S6`,riddle:!0,text:`Du musst Schellen bedienen und hast die 6 und die 9. Welche gibst du zu? Wer die höchste Schelle legt, holt den Stich und alle Schellen darin.`,tip:`Gib die tiefste Karte zu, wenn du den Stich nicht holen willst.`,wrong:{S9:`Die 9 ist im Moment die höchste Schelle. Du würdest den Stich holen, wenn {OST} nicht noch höher hätte. Das Risiko gehst du nicht ein: Gib die 6 zu.`,"*":`Schellen müssen bedient werden. Du hast die 6 und die 9, und du willst tief bleiben.`}},{t:`play`,seat:`OST`,code:`SU`,text:`{OST} hat den Under, die höchste Schelle im Stich, und holt alle vier Schellen. Deine 6 liegt auch dabei, aber nicht in deinem Stich: Das ist dein Glück.`},e(`Merk dir das: Schellen gehen immer an den, der die höchste Schelle spielt. Vier Striche für {OST}, ohne dass er etwas dafür getan hätte.`,`Mit einer tiefen Schelle in der Hand bist du fast immer sicher.`),{t:`play`,seat:`OST`,code:`R6`,text:`{OST} spielt aus: die Rosen 6.`},{t:`play`,seat:`NORD`,code:`R9`},{t:`play`,seat:`WEST`,code:`R10`},{t:`play`,seat:`SUED`,code:`RA`,riddle:!0,text:`Du hast Rosen: 7, 8, Under, Ober und das Ass. Im Stich liegt keine einzige Schelle. Was spielst du?`,tip:`Ein Stich ohne Schelle ist harmlos.`,wrong:{"*":`Du darfst auch tief zugeben. Aber ohne Schelle im Stich ist das Rosen-Ass die sicherste Karte: Du holst den Stich, ohne einen Strich zu riskieren, und wirst die hohe Karte los.`}},{t:`replay`,tricks:[`E9 EO EU EK`],text:`Du hast den Stich geholt und spielst aus: die Eichel 9. Alle bedienen, {WEST} holt ihn mit dem König. Wieder keine Schelle.`},{t:`play`,seat:`WEST`,code:`L8`,text:`{WEST} spielt Schilten aus. Du hast keine Schilten mehr. Dann darfst du eine beliebige Karte abwerfen.`},{t:`play`,seat:`SUED`,code:`S9`,riddle:!0,text:`Welche Karte wirfst du ab? Überleg: Die Schelle in deiner Hand ist eine Gefahr, die Schilten-Karten holen sicher jemand anders.`,tip:`Eine Schelle in einen fremden Stich zu werfen ist das Beste, was dir passieren kann.`,wrong:{"*":`Wirf deine Schellen 9 ab. Der Stich geht an einen anderen, und die Schelle ist bei ihm gut aufgehoben: bei dir wäre sie ein Strich.`}},{t:`play`,seat:`OST`,code:`LU`},{t:`play`,seat:`NORD`,code:`LA`,text:`{NORD} holt den Stich mit dem Schilten-Ass und bekommt deine Schelle dazu. Genau so wirst du eine Schelle los.`},{t:`replay`,tricks:[`RK S10 R7 SO`,`EA SK R8 SA`,`L6 L7 RU L9`,`LK L10 LO RO`],text:`Die letzten vier Stiche im Schnelldurchlauf: {NORD} holt mit dem Rosen-König die Schellen 10 und den Ober, dann mit dem Eichel-Ass den König und das Ass. Du gibst zu, was du musst, und bleibst ohne Strich.`},e(`Gezählt wird: {NORD} hat fünf Schellen, {OST} vier, {WEST} und du keine. So geht ein Spiel meistens aus: Wer am wenigsten erwischt wird, gewinnt. Und weil es zwölf Spiele sind, gleicht sich vieles wieder aus.`,`In der nächsten Hand zeige ich dir, wie du eine gefährliche hohe Schelle loswirst.`)]},{regionId:`NEUENBURG`,kind:`trick`,title:`Schellenjass`,lesson:`Bockkarten`,ziele:[`Eine hohe Schelle früh loswerden`,`Bockkarten tief zugeben`,`Ohne Schelle ruhig weiterspielen`,`Mit tiefen Karten ohne Strich bleiben`],zielAt:[4,6,10,11],einstieg:`Tiefe Karten sind deine Freunde. Sie halten dich aus dem Stich.`,order:t,score:`schellen`,rules:A,trump:null,firstLeader:`OST`,hands:{SUED:`SA E6 E7 E8 E9 L6 L7 L8 L9`,OST:`R7 R9 EU EO S7 S9 SU L10 LU`,NORD:`R8 RA EK EA S8 S10 SO LK LA`,WEST:`R6 R10 RU RO RK E10 S6 SK LO`},steps:[e(`Neue Hand. Schau dir deine Karten an: Du hast das Schellen-Ass, und es ist deine einzige Schelle. Das ist gefährlich. Sobald jemand Schellen ausspielt, musst du sie bedienen, und dein Ass ist die höchste Schelle überhaupt: Du holst den Stich mit allen Schellen darin.`,`Dazu hast du viele tiefe Karten: Eichel 6 bis 9 und Schilten 6 bis 9. Man nennt sie Bockkarten, denn mit ihnen kommst du nie in einen Stich.`),{t:`play`,seat:`OST`,code:`R7`,text:`{OST} fängt an und spielt Rosen aus.`},{t:`play`,seat:`NORD`,code:`R8`},{t:`play`,seat:`WEST`,code:`RK`},{t:`play`,seat:`SUED`,code:`SA`,riddle:!0,text:`Du hast keine Rosen. Das ist deine Gelegenheit: Welche Karte wirfst du ab?`,tip:`Werde eine hohe Schelle früh los, solange sie in einen fremden Stich fallen kann.`,wrong:{"*":`Hmpf. Der Stich geht an {WEST}, und du kannst ihm etwas schenken. Wirf das Schellen-Ass ab: In deiner Hand wäre es eine tickende Uhr.`}},{t:`play`,seat:`WEST`,code:`E10`,text:`{WEST} hat den Stich mit dem König geholt und das Ass dazubekommen: ein Strich für ihn, keiner für dich. Er spielt Eichel aus.`},{t:`play`,seat:`SUED`,code:`E6`,riddle:!0,text:`Du hast die Eichel 6, 7, 8 und 9 und musst bedienen. Welche gibst du zu?`,tip:`Bleib tief: So bleibst du aus dem Stich und behältst die Hand frei.`,wrong:{"*":`Gib die 6 zu, die tiefste. Höhere Eicheln brauchst du später noch, falls jemand Eichel anspielt, und du willst nie freiwillig in einen Stich.`}},{t:`play`,seat:`OST`,code:`EO`},{t:`play`,seat:`NORD`,code:`EK`},{t:`replay`,tricks:[`EA S6 E7 EU`],text:`{NORD} holt den Stich mit dem Eichel-Ass, spielt weiter Eichel aus und {WEST} hat keine mehr: Er wirft seine Schellen 6 ab. Du gibst die Eichel 7 zu, wieder tief. {NORD} hat jetzt eine Schelle.`},e(`Jetzt hast du keine Schelle mehr. Egal, was jetzt ausgespielt wird: Du kannst nie mehr gezwungen werden, eine Schelle zu nehmen. Mit den tiefen Karten zählst du ruhig mit, was fällt.`,`Wer viele Bockkarten hat, kommt fast immer ohne Strich davon.`),{t:`replay`,tricks:[`S8 SK L9 S7`,`R6 E9 R9 RA`,`S10 RU L8 SU`,`S9 SO R10 L7`,`LK LO L6 LU`,`LA RO E8 L10`],text:`Die restlichen sechs Stiche im Schnelldurchlauf: {NORD} spielt Schellen aus, du hast keine mehr und wirfst zuerst die Schilten 9 ab (hohe Karte weg), dann die Eichel 9, dann die 8 und die 7. {WEST} holt dort drei Schellen, {OST} zwei, {NORD} noch zwei.`},e(`Gezählt wird: {WEST} hat vier Schellen, {NORD} drei, {OST} zwei, du keine. Das Ass, das dir gefährlich war, hast du verschenkt, und die Bockkarten haben den Rest erledigt. Hmpf, so gewinnt man den Schellenjass.`,`Merke: Hohe Schelle früh loswerden, tiefe Karten behalten.`)]},{regionId:`NEUENBURG`,kind:`trick`,title:`Schellenjass`,lesson:`Durchmarsch`,ziele:[`Mit dem Schellen-Ass beginnen`,`Die Schellen im Stich zählen`,`Die hohen Schellen nachspielen`,`Den Durchmarsch schaffen`],zielAt:[1,5,7,8],einstieg:`Einmal alles wagen: neun Schellen holen. Du schaffst das.`,order:t,score:`schellen`,rules:A,trump:null,hands:{SUED:`SA SK SO SU S10 S9 E6 R6 L6`,OST:`S6 E7 E10 R8 RK L7 LA L9 EO`,NORD:`S7 E8 EU R7 R10 L8 LO RA E9`,WEST:`S8 EK EA R9 RU RO L10 LU LK`},steps:[e(`Und jetzt das Schönste: der Durchmarsch. Wer alle neun Schellen holt, schreibt 9 Minuspunkte, und die anderen schreiben nichts. Das lohnt sich, wenn man die hohen Schellen beisammen hat. Du hast Ass, König, Ober, Under, Zehn und Neun. Die drei tiefen, die 6, 7 und 8, haben die anderen, je eine.`,`Dazu hast du drei tiefe Karten: E6, R6, L6. Sie brauchst du erst ganz am Schluss.`),{t:`play`,seat:`SUED`,code:`SA`,riddle:!0,text:`Du spielst aus. Welche Karte? Überleg, wie du an die drei tiefen Schellen der anderen kommst.`,tip:`Jeder muss Schellen bedienen, wenn er kann.`,wrong:{"*":`Spiel die Schellen aus, und zwar das Ass: Jeder muss Schellen zugeben, und mit dem Ass kann dich niemand stechen. Die tiefen Schellen der anderen fallen dir in den Stich.`}},{t:`play`,seat:`OST`,code:`S6`,text:`{OST} hat nur diese eine Schelle und muss sie zugeben.`},{t:`play`,seat:`NORD`,code:`S7`,text:`{NORD} ebenso.`},{t:`play`,seat:`WEST`,code:`S8`,text:`{WEST} auch. Sieh dir den Stich an.`},{t:`choose`,text:`Wie viele Schellen liegen jetzt in deinem Stich?`,tip:`Zähl die Schellen im Stich: Du hast das Ass gespielt, die anderen je eine.`,options:[{id:`N4`,label:`Vier`},{id:`N1`,label:`Eine, das Ass`},{id:`N9`,label:`Alle neun`}],answer:`N4`,wrong:{N1:`Nicht nur das Ass: {OST}, {NORD} und {WEST} haben ihre Schellen zugegeben. Das sind vier.`,N9:`Noch nicht, es kommen erst vier zusammen: dein Ass und die drei tiefen. Die fünf hohen holst du jetzt noch.`}},e(`Jetzt sind alle Schellen, die dich stechen könnten, verbraucht. Was noch fehlt, sind deine fünf hohen. Spiel sie der Reihe nach aus: König, Ober, Under, Zehn, Neun. Niemand kann sie mehr aufhalten, denn die anderen haben keine Schellen mehr.`,`Wer keine Schellen mehr hat, wirft eine beliebige Karte ab, meist eine hohe, damit er sie los ist.`),{t:`replay`,tricks:[`SK LA RA EA`,`SO RK LO EK`,`SU EO EU LK`,`S10 E10 R10 RO`,`S9 L9 E9 RU`],text:`Fünf Stiche, fünf Schellen. Die anderen werfen ihre Asse und Könige in deine Stiche ab, aber das zählt nichts: Es zählen nur die Schellen.`},{t:`replay`,tricks:[`E6 E7 E8 LU`,`R7 R9 R6 R8`,`L10 L6 L7 L8`],text:`Die drei letzten Stiche gehen an die anderen. Egal: Alle neun Schellen liegen bei dir.`,fx:{status:`Durchmarsch! Du schreibst −9, die anderen nichts.`}},e(`Neun von neun: Durchmarsch! Du schreibst 9 Minuspunkte, die anderen nichts. Bei den anderen heisst das: Wer sieht, dass einer alle Schellen sammelt, muss selbst eine nehmen, bevor es zu spät ist. Mit einer einzigen Schelle in deinem Stich ist sein Durchmarsch hin.`,`Und so geht die Partie über zwölf Spiele: Am Schluss gewinnt, wer die wenigsten Striche hat. Viel Glück bei den Schellen.`)]}],M=[{id:`KOMMEN`,label:`I chume`},{id:`EVENTUELL`,label:`Eventuell`},{id:`PASSEN`,label:`Fort`}],N=[{regionId:`HANDJASS`,kind:`trick`,title:`Sackjass`,lesson:`Kommen oder passen`,ziele:[`Mit schwacher Hand passen`,`Mit starker Hand kommen`,`Mit dem Under die Trümpfe holen`,`Striche und Säcke verstehen`],zielAt:[1,2,7,11],einstieg:`Jeder spielt für sich. Schau deine Hand an und sag, ob du kommst.`,order:t,out:[`NORD`],firstLeader:`SUED`,score:`solo`,trump:`ROSE`,hands:{SUED:`RU R9 RA RK EA E10 SA S10 L6`,OST:`RO R10 R8 EK EO E9 SK SO L10`,NORD:`E6 E7 S6 S7 S8 L7 L8 L9 R7`,WEST:`R6 E8 EU SU S9 LA LK LO LU`},steps:[e(`Beim Sackjass spielt jeder für sich, hier in der Spielart Handjass. {WEST} hat gegeben, die unterste Karte liegt offen, das ist der Bodentrumpf: das Rosen-6, also ist Rose Trumpf. Bevor gespielt wird, sagt jeder der Reihe nach, ob er kommt («I chume») oder passt («Fort»). Wer kommt und unter 21 Punkten bleibt, bekommt einen Sack.`,`Wer passt, legt die Karten weg und bekommt weder Strich noch Sack. Die zwei Besten der Hand schreiben je einen Strich, wer zuerst 7 Striche hat, gewinnt.`,{trump:`ROSE`,badges:[`Trumpf: Rose`]}),{t:`choose`,text:`Zuerst eine Aufgabe: Stell dir eine Hand ohne Trumpf und ohne Ass vor, nur Sechser, Siebner und ein Under. Was sagst du?`,tip:`Ohne Trumpf und Asse holst du kaum 21 Punkte. Ein Sack zählt wie ein Strich weniger.`,options:M,answer:`PASSEN`,wrong:{KOMMEN:`Damit holst du kaum einen Stich, und unter 21 Punkten gibt es einen Sack. Sag lieber «Fort».`,EVENTUELL:`«Eventuell» ist für knappe Hände: Du entscheidest später, wenn du weisst, wer kommt. Diese Hand ist nicht knapp, sie ist schwach. «Fort».`}},{t:`choose`,text:`Jetzt deine echte Hand: Trumpf-Under, Nell, Ass und König, dazu zwei Asse. Du bist Vorhand und sprichst zuerst. Was sagst du?`,tip:`Under, Nell und Ass im Trumpf holen ihre Stiche fast sicher, die Asse auch.`,options:M,answer:`KOMMEN`,wrong:{EVENTUELL:`Mit dieser Hand musst du nicht abwarten. Die Striche sind dir fast sicher: «I chume».`,PASSEN:`Diese Hand ist viel zu gut zum Passen. Wer passt, kann keinen Strich schreiben.`},fx:{badges:[`Trumpf: Rose`]}},e(`{OST} kommt auch. {NORD} hat nur tiefe Karten und sagt «Fort», er legt seine Karten weg. {WEST} kommt und zeigt einen Weis: Under, Ober, König und Ass im Schilten, ein Vierblatt für 50 Punkte. Weis und Stöck zählen beim Sackjass zu den eigenen Punkten.`,`Nur wer kommt, spielt mit. Die Vorhand spielt aus. Hätte sie gepasst, spielte der Nächste aus, der kommt.`,{badges:[`Trumpf: Rose`,`Weis 50`],bubbles:{OST:`I chume!`,NORD:`Fort.`,WEST:`50 weise!`}}),{t:`play`,seat:`SUED`,code:`RU`,text:`Du spielst aus. Hol mit dem Trumpf-Under die Trümpfe der anderen heraus.`,tip:`Der Under ist der stärkste Trumpf. Wer Trumpf hat, muss ihn jetzt zugeben (ausser dem Under).`},{t:`play`,seat:`OST`,code:`R8`},{t:`play`,seat:`WEST`,code:`R6`},{t:`play`,seat:`SUED`,code:`R9`,text:`Weiter mit dem Nell.`,tip:`Je weniger Trumpf die anderen haben, desto sicherer stehen deine Asse.`},{t:`play`,seat:`OST`,code:`RO`},{t:`play`,seat:`WEST`,code:`S9`},{t:`replay`,text:`Den Rest im Schnelldurchlauf: Du holst noch das Trumpf-Ass und deine Asse. {OST} sticht mit König und Ober, {WEST} mit dem Schilten-Ass. Den letzten Stich holst du mit dem Trumpf-König.`,tricks:[`RA R10 E8`,`EA E9 EU`,`E10 EK LO`,`SK SU SA`,`S10 SO LU`,`L10 LA L6`,`LK RK EO`]},e(`Die Abrechnung: Du hast 99 Punkte und 5 für den letzten Stich, also 104. {WEST} hat 21 und dazu 50 Weis, also 71, {OST} 32. Die zwei Besten schreiben je einen Strich: du und {WEST}. {OST} bleibt über 21 Punkten und bekommt keinen Sack. {NORD} hat gepasst und bekommt nichts.`,`Hast du schon einen Sack, verdient dein nächster Strich ihn ab, statt zu zählen. Zu dritt darf jeder vorher drei Karten bessern, zu zweit raubt der Trumpf-Sechser die offene Karte.`,{badges:[`Du: Strich`,`Strich für 71`]})]},{regionId:`HANDJASS`,kind:`trick`,title:`Sackjass`,lesson:`Eventuell`,ziele:[`«Eventuell» sagen, wenn es knapp ist`,`In der zweiten Runde entscheiden`,`Tiefe Karten zugeben, hohe behalten`,`Die 21 Punkte sichern`],zielAt:[1,3,13,15],einstieg:`Bei einer mittleren Hand darfst du dir Zeit lassen.`,order:t,out:[`OST`,`NORD`],firstLeader:`SUED`,score:`solo`,trump:`SCHILTE`,hands:{SUED:`LA L10 L8 EA E6 SK S9 R10 R7`,OST:`LK L6 E9 E8 SO SU S10 RK RO`,NORD:`E7 EU EO S6 S7 S8 R6 R9 RU`,WEST:`LU L9 L7 LO EK E10 SA RA R8`},steps:[e(`Die nächste Hand. {WEST} hat gegeben, offen liegt das Schilten-7: Schilte ist Trumpf. Deine Hand ist mittel: Trumpf-Ass, Zehner und Achter, dazu das Eichel-Ass und ein paar mittlere Karten.`,`Gezählt wird für jeden allein. Unter 21 Punkten gibt es einen Sack.`,{trump:`SCHILTE`,badges:[`Trumpf: Schilte`]}),{t:`choose`,text:`Du bist Vorhand und sprichst zuerst. Kommen lohnt sich vielleicht, vielleicht auch nicht. Was sagst du?`,tip:`Mit «Eventuell» («I lose») hörst du zuerst, wer kommt, und entscheidest dann in einer zweiten Runde.`,options:M,answer:`EVENTUELL`,wrong:{KOMMEN:`Kommen ist nicht falsch, aber gegen drei starke Gegner reicht deine Hand vielleicht nicht für 21 Punkte. Hör zuerst zu: «Eventuell».`,PASSEN:`Ganz weg musst du nicht: Mit Trumpf-Ass und Eichel-Ass hast du eine Chance. Sag «Eventuell» und warte, wer kommt.`},fx:{badges:[`Trumpf: Schilte`]}},e(`{OST} und {NORD} sagen «Fort». {WEST} kommt. Jetzt bist du in der zweiten Runde dran: kommen oder passen, «Eventuell» gibt es nicht mehr.`,`Kommen nur zwei, schreibt nur der Bessere einen Strich. Der andere bekommt nichts, ausser er bleibt unter 21 Punkten.`,{badges:[`Trumpf: Schilte`],bubbles:{OST:`Fort.`,NORD:`Fort.`,WEST:`I chume!`}}),{t:`choose`,text:`Nur {WEST} spielt gegen dich. Kommst du?`,tip:`Gegen einen einzigen Gegner holst du mit zwei Assen und Trumpf fast sicher 21 Punkte, und mit etwas Glück den Strich.`,options:M.filter(e=>e.id!==`EVENTUELL`),answer:`KOMMEN`,wrong:{PASSEN:`Gegen nur einen Gegner ist deine Hand gut genug. Wer passt, kann keinen Strich machen. «I chume».`}},{t:`play`,seat:`SUED`,code:`EA`,text:`Du spielst aus. Hol dir zuerst das Eichel-Ass.`,tip:`Ein Ass ist ein sicherer Stich, solange der Gegner die Farbe noch hat.`},{t:`play`,seat:`WEST`,code:`EK`},{t:`play`,seat:`SUED`,code:`SK`},{t:`play`,seat:`WEST`,code:`SA`},{t:`play`,seat:`WEST`,code:`RA`},{t:`play`,seat:`SUED`,code:`R7`,text:`Du musst Rosen angeben. Gib die tiefe Karte, der Zehner bleibt für später.`,tip:`Gegen das Ass gewinnst du nicht: Gib so wenige Punkte wie möglich.`},{t:`play`,seat:`WEST`,code:`LU`},{t:`play`,seat:`SUED`,code:`L8`,text:`Der Trumpf-Under kommt. Du musst Trumpf geben: den Achter.`,tip:`Ass und Zehner sind zu wertvoll für einen verlorenen Stich.`},{t:`play`,seat:`WEST`,code:`L9`},{t:`play`,seat:`SUED`,code:`L10`,text:`Auch den Nell kannst du nicht schlagen. Gib den Zehner, behalte das Ass.`,tip:`Mit dem Ass holst du gleich den nächsten Trumpf.`},{t:`play`,seat:`WEST`,code:`LO`},{t:`play`,seat:`SUED`,code:`LA`,riddle:!0,text:`{WEST} spielt den Trumpf-Ober. Welche Karte bringt dich über 21 Punkte?`,tip:`Du hast 15 Punkte. Das Trumpf-Ass schlägt den Ober und bringt 14 Punkte.`,wrong:`Mit dem Trumpf-Ass holst du diesen Stich und hast die 21 Punkte sicher.`},{t:`replay`,text:`Den Rest im Schnelldurchlauf: Du holst mit dem Rosen-10 noch einen Stich, {WEST} sticht deinen Schellen-9 und holt den letzten Stich.`,tricks:[`R10 R8`,`S9 L7`,`E10 E6`]},e(`Die Abrechnung: {WEST} hat 80 Punkte und 5 für den letzten Stich, also 85, und schreibt den Strich. Du hast 39, also keinen Sack. Mit «Eventuell» hast du erst gehört, wer kommt, und dann richtig entschieden.`,`Zu viert gibt es zwei Striche, kommen nur zwei, nur einen. In der Schläger-Form liegt die Grenze bei 26 Punkten, und es gibt bis zu drei Striche.`,{badges:[`Strich für 85`,`Du: kein Sack`]})]}],P=Object.fromEntries([a,o,l,u,f,p,h,g,_,v,y,x,w,D,k,j,N].map(e=>[e[0].regionId,e]));Object.values(P).flat(),Object.fromEntries(Object.entries(P).map(([e,t])=>[e,t[0]]));var F=(e,t=1)=>P[e]?.[t-1]||null,I=e=>P[e]?.length||0;export{I as n,n as r,F as t};